(window.GIM_TS=window.GIM_TS||{})["Bava Kamma.0"]={"from":0,"a":[["אלו הם \u0003ארבעה אבות\u0004 (סוגים עיקריים) של \u0003נזיקין: השור, והבור, והמבעה\u0004 (שנחלקו אמוראים בגמרא בהגדרתו), \u0003וההבער\u0004 (אש). ואף שכולם הזיקו, אינם דומים בפרטיהם זה לזה ואין ללמוד זה מזה.","כי \u0003לא הרי\u0004 (אינו דומה) \u0003השור כהרי המבעה, ולא הרי המבעה כהרי השור, ולא זה וזה\u0004 שהצד השווה שבהם \u0003שיש בהן רוח חיים, כהרי האש\u0004 (\"ההבער\") \u0003שאין בו רוח חיים,\u0004","\u0003ולא זה וזה,\u0004 השור והמבעה והאש, שהצד השווה שבהם \u0003שדרכן לילך ולהזיק, כהרי הבור שאין דרכו לילך ולהזיק,\u0004 אלא הניזקים הם ההולכים ונתקלים בו.","\u0003הצד השוה שבהן,\u0004 בכל אבות הנזיקין — \u0003שדרכן להזיק, ושמירתן\u0004 מוטלת \u0003עליך,\u0004 או משום שהדבר המזיק שייך לו, או משום שיצר את הדבר שגורם לנזק, \u0003וכשהזיק\u0004 — \u0003חב\u0004 (חייב) \u0003המזיק לשלם תשלומי נזק במיטב הארץ,\u0004 מן המובחר שבקרקעותיו.","תחילה מבררים את פרטי לשון המשנה. \u0003מדקתני\u0004 \u0005[מ\u0006מה \u0005ששנה\u0006 במשנה\u0005]\u0006 \u0003\"אבות\" מכלל\u0004 הדברים אתה למד \u0003דאיכא\u0004 \u0005[שיש]\u0006 גם \u0003תולדות,\u0004 כלומר, סוגי נזקים הנובעים ונלמדים מאבות אלה, ויש לשאול: האם \u0003תולדותיהן\u0004 של אבות הנזיקין \u0003כיוצא בהן,\u0004 ויש להם אותו דין עצמו, \u0003או לאו\u0004 \u0005[לא]\u0006 \u0003כיוצא בהן\u0004 ודיניהם שונים? ומבררים את הדבר מתוך השוואה לנושאים אחרים שאף בהם קיימים אבות ותולדות.","\u0003גבי\u0004 \u0005[אצל]\u0006 \u0003שבת תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003אבות מלאכות\u0004 האסורות בשבת מניינם \u0003ארבעים חסר אחת.\u0004 ואף שם מדייקים: \u0003אבות\u0004 — \u0003מכלל\u0004 הדברים אתה למד \u0003דאיכא\u0004 \u0005[שיש]\u0006 \u0003תולדות,\u0004 ושם","\u0003תולדותיהן כיוצא בהן; לא שנא\u0004 \u0005[שונה]\u0006 אם עשה \u0003אב\u0004 מלאכה בשגגה, כגון ששכח שיום זה הוא שבת, שחייב להביא קרבן \u0003חטאת, ולא שנא\u0004 \u0005[שונה]\u0006 כשעשה בשגגה \u0003תולדה\u0004 של אחת מהמלאכות הללו, שחייב \u0003חטאת. ו\u0004כמו כן, \u0003לא שנא\u0004 \u0005[שונה]\u0006 אם עשה \u0003אב\u0004 מלאכה בשבת במזיד, והיו עדים והתראה, שחייב \u0003סקילה, ולא שנא\u0004 \u0005[שונה]\u0006 אם עשה \u0003תולדה\u0004 במזיד — שחייב \u0003סקילה\u0004 גם כן.","ואם כן \u0003מאי איכא\u0004 \u0005[מה יש\u0006 הבדל\u0005]\u0006 \u0003בין אב לתולדה?\u0004 ומשיבים: \u0003נפקא מינה\u0004 \u0005[יוצא מזה\u0006 הבדל זה\u0005]\u0006 ש\u0003אילו עביד\u0004 \u0005[עושה]\u0006 \u0003שתי אבות\u0004 מלאכה \u0003בהדי הדדי\u0004 \u0005[יחד]\u0006 בשגגה אחת, \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 אם עושה \u0003שתי תולדות\u0004 מאבות שונים \u0003בהדי הדדי\u0004 \u0005[יחד]\u0006 — \u0003מחייב אכל חדא וחדא\u0004 \u0005[מתחייב על כל אחת ואחת]\u0006 קרבן חטאת מיוחד, כי בדיני שבת כל אב מלאכה הוא עבירה בפני עצמה, וחייבים עליו לעצמו. \u0003ואילו עביד\u0004 \u0005[עושה]\u0006 \u0003אב\u0004 מלאכה \u0003ותולדה דידיה\u0004 \u0005[שלו]\u0006 בשגגה אחת, בלא שנודע לו האיסור בינתיים — \u0003לא מחייב\u0004 \u0005[מתחייב]\u0006 \u0003אלא חדא\u0004 \u0005[\u0006קרבן חטאת \u0005אחד],\u0006 כי הריהו כמי שחוזר ועושה אותה עבירה עצמה.","ושואלים: \u0003ול\u0004שיטת \u0003ר' אליעזר\u0004 ש\u0003מחייב\u0004 שני קרבנות גם אם עושה \u0003תולדה במקום\u0004 (יחד עם) \u0003אב\u0004 שלה, אם כן \u0003אמאי קרי ליה\u0004 \u0005[מדוע קורא לו]\u0006 \u0003אב, ואמאי קרי\u0004 \u0005[ומדוע קורא]\u0006 \u0003לה תולדה?\u0004 ומשיבים: יש להסביר לשיטתו כך: \u0003הך דהוה\u0004 \u0005[זו שהיתה]\u0006 \u0003במשכן\u0004 מלאכה \u0003חשיבא\u0004 \u0005[חשובה]\u0006 \u0003קרי ליה\u0004 \u0005[קורא לה]\u0006 \u0003אב,\u0004 כי את הגדרת המלאכות בשבת למדים מן המלאכות שעשו בהקמת המשכן (וראה ספר שמות פרק לה), \u0003הך\u0004 \u0005[זו]\u0006 ש\u0003לא הוי\u0004 \u0005[היתה]\u0006 \u0003במשכן\u0004 מלאכה \u0003חשיבא\u0004 \u0005[חשובה]\u0006 \u0003קרי\u0004 \u0005[קורא]\u0006 \u0003לה תולדה.\u0004 אם כן למדנו מה היחס בין אבות ותולדות לענין שבת.","ומצד שני \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003טומאות תנן\u0004 \u0005[שנינו]\u0006 גם כן אבות ותולדות, \u0003אבות הטומאות,\u0004 הטומאות המפורשות בתורה הם: נבלת \u0003השרץ, והשכבת זרע\u0004 של אדם,"],["\u0003וטמא מת\u0004 (מי שנגע במת). והנוגע באב הטומאה קרוי \"ולד (תולדות) הטומאה\". ואבות אלה \u0003תולדותיהן לאו\u0004 \u0005[לא]\u0006 \u0003כיוצא בהן,\u0004 שאין דין האב ודין התולדה שווים. ש\u0003אילו אב\u0004 הטומאה \u0003מטמא אדם\u0004 הנוגע בו, \u0003ו\u0004כן \u0003כלים\u0004 שנגעו בו. \u0003ואילו\u0004 אחד מן ה\u0003תולדות\u0004 — \u0003אוכלין ומשקין\u0004 הרי הוא \u0003מטמא,\u0004 אבל \u0003אדם וכלים\u0004 — \u0003לא מטמא.\u0004","מצאנו איפוא כי יש הלכות שבהן דין התולדות שווה לאבות, ויש הלכות שבהן דין התולדות אינו דומה לאבות, ולכן יש לשאול: \u0003הכא מאי\u0004 \u0005[כאן\u0006 בנזיקין \u0005מה\u0006 הדין\u0005]?\u0006 \u0003אמר רב פפא:\u0004 כאן אין יחס אחד פשוט של התולדות והאבות, שכן \u0003יש מהן\u0004 שהם \u0003כיוצא בהן, ויש מהן\u0004 שהם \u0003לאו\u0004 \u0005[לא]\u0006 \u0003כיוצא בהן.\u0004","כדי לברר את דברי רב פפא, מקדימים ברייתא המסבירה בפירוט את אבות הנזיקין. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003שלשה אבות נאמרו בשור,\u0004 כלומר, שהשור יכול לגרום לשלושה אבות נזיקין; \u0003הקרן\u0004 שהוא נוגח בה, \u0003והשן\u0004 שהוא אוכל בה, \u0003והרגל\u0004 שהוא דורס ומזיק בה בדרך הילוכו.","ומבררים: \u0003קרן מנלן\u0004 \u0005[מניין לנו]?\u0006 \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]\u0006 בברייתא על הכתוב \"ו\u0003כי יגח\u0004 שור את איש או את אשה\" (שמות כא, כח): \u0003אין נגיחה אלא\u0004 ב\u0003קרן.\u0004 וראייה לדבר ממה \u0003שנאמר: \"ויעש לו צדקיה בן כנענה קרני ברזל ויאמר כה אמר ה' באלה תנגח את ארם\u0004 עד כלותם\u0003\"\u0004 (מלכים א כב, יא), \u0003ואומר\u0004 עוד הכתוב: \u0003\"בכור שורו הדר לו וקרני ראם קרניו בהם עמים ינגח\"\u0004 (דברים לג, יז).","על לשון ברייתא זו שואלים מיד: \u0003מאי\u0004 \u0005[מה]\u0006 הצורך בראיה הנוספת של \u0003\"ואומר\"?\u0004 ומסבירים: היה צורך בראיה נוספת זו, שהיא תשובה לשאלה אפשרית על הראיה מהכתוב שהובא קודם לכן: \u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 כי \u0003דברי תורה מדברי קבלה\u0004 (מדברי נביאים) \u0003לא ילפינן\u0004 \u0005[אין אנו למדים]\u0006 ולכן אין ללמוד הגדרתה של נגיחה שבתורה מדבר האמור בנביאים כגון זה שבספר מלכים — לכך \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 מן הכתוב בתורה \u0003\"בכור שורו הדר לו\"\u0004 וכו'.","על הצעה זו של שאלה תוהים: \u0003והאי מילף\u0004 \u0005[ו\u0006כי \u0005זה לימוד]\u0006 \u0003הוא?\u0004 והרי אין זה לימוד של הלכה, אלא \u0003גילוי מילתא בעלמא\u0004 \u0005[דבר בלבד]\u0006 \u0003הוא\u0004 ש\u0003נגיחה בקרן הוא,\u0004 ובזה הכל מודים שאפשר ללמוד משמעות המילים שבתורה גם מדברי נביאים!","\u0003אלא\u0004 כך היתה השאלה האפשרית: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 \u0003כי פליג רחמנא\u0004 \u0005[כאשר חילקה התורה]\u0006 \u0003בין\u0004 דין שור \u0003תם\u0004 שנגח פעם או פעמיים, שמשלם רק חצי נזק, \u0003ל\u0004דינו של שור \u0003מועד\u0004 שנגח שלוש פעמים, שמשלם נזק שלם — הרי \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים דווקא בקרן \u0003תלושה,\u0004 כגון שהחזיקה הבהמה קרן בין שיניה והזיקה בה, וכעין הקרניים שעשה צדקיה בן כנענה לעצמו, שנזק כזה הוא בלתי מצוי, והיה מקום לחלק בו בין שור תם למועד, \u0003אבל ב\u0004קרן \u0003מחוברת\u0004 שמזיקה כדרכה — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003כולה\u0004 מתחילתה \u0003מועדת היא,\u0004 שדרך השור לנגוח, על כן","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה שנאמר \u0003\"בכור שורו הדר לו\u0004 וקרני ראם קרניו בהם עמים ינגח","\u0003\",\u0004 שאף בקרן מחוברת נאמרה לשון \"נגיחה\", ואף היא בכלל פרשת \"כי יגח\". זו היא קרן הכתובה בתורה. \u0003תולדה\u0004 של \u0003קרן מאי\u0004 \u0005[מה]\u0006 \u0003היא\u0004 — נזקים שעשה השור בגופו בזדון כדי להזיק: \u0003נגיפה\u0004 (דחיפה), \u0003נשיכה, רביצה\u0004 על דברים כדי להזיקם, \u0003ובעיטה.\u0004 ותחילה מבררים את מהות ההבדלים בין הנאמרים ברשימה זו.","\u0003מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה]\u0006 \u0003נגיחה\u0004 \u0003דקרי\u0004 \u0005[ש\u0006הוא \u0005קורא]\u0006 \u0003לה אב\u0004 נזיקין — \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 במפורש \u0003\"כי יגח\"\u0004 (שמות כא, כח), אולם \u0003נגיפה נמי כתיב\u0004 \u0005[גם כן נאמר]\u0006 \u0003\"כי יגף\u0004 שור איש את שור רעהו\u0003\"\u0004 (שמות כא, לה)! ומשיבים: \u0003האי\u0004 \u0005[זו]\u0006 ה\u0003נגיפה\u0004 שנאמרה בכתוב אין פירושה דחיפה בגוף, אלא \u0003נגיחה\u0004 בקרן \u0003היא. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003פתח\u0004 הכתוב \u0003בנגיפה\u0004 (\"כי יגוף\") \u0003וסיים בנגיחה,\u0004 שהכתוב אומר בהמשך \"כי שור נגח הוא\" (שמות כא, לו), \u0003לומר לך: זו היא נגיפה זו היא נגיחה\u0004 והם דבר אחד, ואין הבדל במובנם.","ושואלים עוד: אם כן \u0003ומאי שנא\u0004 \u0005[ובמה שונה]\u0006 השימוש בלשונות אלה בתורה \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003אדם, דכתיב\u0004 \u0005[שנאמר]\u0006 בו תמיד \u0003\"כי יגח\"\u0004 (כגון שמות כא, כח), \u0003ומאי שנא\u0004 \u0005[ובמה שונה]\u0006 \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003בהמה דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"כי יגף\"?\u0004 והרי אף נגיפה — נגיחה היא!","ומסבירים: \u0003אדם דאית ליה מזלא\u0004 \u0005[שיש לו מזל],\u0006 כלומר, שיש בו דעת להיזהר ואינו נפגע בקלות, \u0003כתיב\u0004 \u0005[נאמר]\u0006 בו לשון \u0003\"כי יגח\",\u0004 אולם \u0003בהמה דלית\u0004 \u0005[שאין]\u0006 \u0003לה מזלא\u0004 \u0005[מזל]\u0006 \u0003כתיב\u0004 \u0005[נאמר]\u0006 בה לשון \u0003\"כי יגף\",\u0004 ללמד שכל נגיחה בה היא נגיפה (כמו: מגיפה), כלומר, מביאה לידי חבלה ומוות.","ומוסיפים: \u0003ומלתא אגב אורחיה קא משמע לן\u0004 \u0005[ודבר\u0006 נוסף \u0005בדרך אגב השמיע לנו]\u0006 השימוש השונה בלשונות אלה — ששור ה\u0003מועד\u0004 שנגח אדם שלוש פעמים ורגיל \u0003ל\u0004נגוח בני \u0003אדם הוי\u0004 \u0005[הריהו]\u0006 גם כן \u0003מועד ל\u0004נגיחת \u0003בהמה\u0004 ואם נגח בהמה — משלם נזק שלם. שהרי נגיחת אדם עד שימות מצויה פחות מנגיחת שור אחר, ואם נוגח בני אדם — ודאי שמועד הוא לנגוח ולהמית גם שוורים. אבל שור ה\u0003מועד לבהמה,\u0004 שנגח בהמה שלוש פעמים — \u0003לא הוי\u0004 \u0005[אין הוא]\u0006 \u0003מועד לאדם.\u0004","ושואלים עוד: הלא \u0003נשיכה\u0004 שאמרנו כי היא אחת מתולדות הקרן, \u0003תולדה\u0004 של \u0003שן היא,\u0004 שהרי השור נושך בשיניו! ומשיבים: \u0003לא,\u0004 אין הדברים דומים זה לזה, שכן, אצל \u0003שן\u0004 — \u0003יש הנאה\u0004 \u0003להזיקה,\u0004 שהשור נהנה באכילה זו, \u0003ו\u0004אילו \u0003הא\u0004 \u0005[וזו]\u0006 הנשיכה — \u0003אין הנאה\u0004 \u0003להזיקה,\u0004 אלא היא נשיכה כדי להזיק בלבד.","כיוצא בזה שואלים: הלא \u0003רביצה ובעיטה תולדה\u0004 של \u0003רגל היא,\u0004 שהרי הן נעשות ברגל ובדרך הילוך! ודוחים: \u0003לא, רגל הזיקה מצוי,\u0004 שאין היא כוללת אלא נזקים המצויים והרגילים על ידי הליכתה של הבהמה, ואילו \u0003הני\u0004 \u0005[אלה],\u0006 רביצה ובעיטה, \u0003אין הזיקן מצוי,\u0004 שאין דרך הבהמה לבעוט או לרבוץ על גבי כלים.","ומעתה שבים להסביר את דברי רב פפא: \u0003אלא תולדותיהן לאו\u0004 \u0005[לא]\u0006 \u0003כיוצא בהן\u0004 ש\u0003אמר רב פפא אהייא\u0004 \u0005[על איזה]\u0006 מאבות נזיקין מדובר?","\u0003אילימא אהני\u0004 \u0005[אם תאמר על אלה]\u0006 שמנינו, אולם \u0003מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה]\u0006 \u0003קרן\u0004 ש\u0003כוונתו להזיק,\u0004 \u0003ו\u0004המזיק הוא \u0003ממונך,\u0004 שייך לך, \u0003ושמירתן עליך\u0004 — הלא \u0003הני נמי\u0004 \u0005[אלה גם כן]\u0006 תולדותיה: נגיפה, נשיכה וכו', נכללות באותה הגדרה: \u0003כוונתן להזיק, וממונך\u0004 הם, \u0003ושמירתן עליך!\u0004","\u0003אלא\u0004 יש לומר ש\u0003תולדה\u0004 של \u0003קרן\u0004 דינה \u0003כקרן, וכי קאמר\u0004 \u0005[וכאשר אמר]\u0006 \u0003רב פפא\u0004 שיש הבדל בין אב לתולדה — על \u0003שן ורגל\u0004 אמר.","ושואלים: \u0003שן ורגל היכא כתיבי\u0004 \u0005[היכן\u0006 הן \u0005נאמרות]\u0006 בכתוב, כך שניתן לקרוא להן אבות נזיקין? ומשיבים: \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 על מה שנאמר \"ושלח את בעירה ובער בשדה אחר\" (שמות כב, ד): \u0003\"ושלח\"\u0004 — \u0003זה הרגל,\u0004 עצם שילוח הבהמות (\"בעירה\") גורם לנזק הבא מדריסת הרגל, \u0003וכן הוא אומר: \"משלחי רגל השור והחמור\"\u0004 (ישעיה לב, כ). הרי שהפעל \"לשלח\" מתייחס בלשון הכתוב לרגל.","\u0003\"ובער\"\u0004 — \u0003זו\u0004 דרך ההיזק הנגרמת על ידי \u0003השן, וכן הוא אומר: \"כאשר יבער\u0004"],["\u0003הגלל עד תמו\"\u0004 (מלכים א יד, י), ולמדו ש\"גלל\" זה הוא שן הבהמה.","ומבררים את הברייתא. \u0003אמר מר\u0004 \u0005[החכם]\u0006 בברייתא זו: \u0003\"ושלח\" זו הרגל, וכן הוא אומר: \"משלחי רגל השור והחמור\"\u0004 (ישעיה לב, כ). ושואלים: אפשר לדייק ולומר כי \u0003טעמא\u0004 \u0005[הטעם]\u0006 ש\"ושלח\" זה רגל רק משום \u0003דכתב רחמנא\u0004 \u0005[שכתבה התורה\u0006 בנביא\u0005]\u0006 \u0003\"משלחי רגל השור והחמור\",\u0004 ואולם לכאורה פירוש זה הוא הכרחי מעצמו, \u0003הא לאו הכי במאי מוקמת לה\u0004 \u0005[הרי בלא כך במה היית מעמיד אותו\u0006 את הכתוב\u0005]\u0006 \"ושילח את בעירה\"?","שהרי \u0003אי\u0004 \u0005[אם]\u0006 \u0003קרן\u0004 — הלא הדבר \u0003כתיב\u0004 \u0005[נאמר]\u0006 כבר בפסוק אחר, ו\u0003אי\u0004 \u0005[אם]\u0006 בנזקי \u0003שן\u0004 — גם כן הרי \u0003כתיב\u0004 \u0005[נאמר]\u0006 פסוק אחר, שנאמר \"וביער בשדה אחר\", וממילא אין כתוב זה עוסק אלא בנזקי רגל!","ומשיבים: \u0003איצטריך\u0004 \u0005[צריך]\u0006 ראיה נוספת לדבר, כי \u0003סלקא דעתך אמינא\u0004 \u0005[היה עולה על דעתך לומר]\u0006 \u0003אידי ואידי\u0004 \u0005[זה וזה]\u0006 גם \"ושילח\" וגם \"וביער\", מדברים \u0003אשן\u0004 \u0005[על\u0006 נזקי \u0005שן]\u0006 בשני אופנים של נזקי שן, \u0003והא\u0004 \u0005[וזה],\u0006 הכתוב \"וביער בשדה אחר\" מדבר באופן \u0003דמכליא קרנא\u0004 \u0005[שמכלה\u0006 את \u0005הקרן],\u0006 את כל תבואת השדה, ואילו \u0003הא\u0004 \u0005[זה],\u0006 הכתוב שנאמר בו \"ושילח\" מדבר באופן \u0003דלא מכליא קרנא\u0004 \u0005[שאינה מכלה\u0006 את \u0005הקרן],\u0006 אלא רק מקצת הפירות, והוא ענין של \"ושילח\" בלבד, שאף עליו חייבה התורה לשלם. על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 הכתוב \"משלחי הרגל\" ש\"שילוח\" הוא נזקי רגל.","ושואלים: \u0003והשתא דאוקימנא\u0004 \u0005[ועכשיו, שהעמדנו,\u0006 הסברנו\u0005]\u0006 קטע זה של הפסוק \u0003ארגל\u0004 \u0005[על\u0006 נזקי \u0005רגל],\u0006 נזקי \u0003שן דלא מכליא קרנא מנלן\u0004 \u0005[שאינה מכלה\u0006 את \u0005הקרן, מניין לנו]?\u0006 שהרי לפי זה נזקי שן נלמדים רק מן הכתוב \"וביער בשדה אחר\", ומשמע דווקא שן כזו שמבערת ומכלה הכל!","ומשיבים: אין צורך בכתוב מיוחד לענין זה, שאנו דנים בנזקי שן \u0003דומיא דרגל\u0004 \u0005[\u0006ב\u0005דומה ל\u0006נזקי \u0005רגל]\u0006 שנזכרו באותו פסוק: \u0003מה רגל לא שנא מכליא קרנא ולא שנא לא מכליא קרנא\u0004 \u0005[אינו שונה\u0006 כש\u0005מכלה\u0006 את \u0005הקרן ואינו שונה\u0006 כש\u0005אינה מכלה\u0006 את \u0005הקרן]\u0006 \u0003אף שן\u0004 — \u0003לא שנא מכליא קרנא, ולא שנא לא מכליא קרנא\u0004 \u0005[אינו שונה\u0006 כשהיא \u0005מכלה\u0006 את \u0005הקרן, ואינו שונה\u0006 כש\u0005אינה מכלה\u0006 את \u0005הקרן].\u0006 וממשיכים לדון בפרטי הברייתא.","\u0003אמר מר\u0004 \u0005[החכם]\u0006 בברייתא זו: \u0003\"ובער\"\u0004 — \u0003זו השן, וכן הוא אומר: \"כאשר יבער הגלל עד תמו\".\u0004 ונדייק: \u0003טעמא דכתב רחמנא\u0004 \u0005[הטעם,\u0006 דווקא, משום \u0005שכתבה התורה]\u0006 \u0003\"כאשר יבער הגלל עד תמו\"\u0004 יודעים אנו שמדובר בשן, ואולם לכאורה אינו נחוץ כתוב מיוחד לכך, ומעצמו היה מובן כך הכתוב, \u0003הא לאו הכי במאי אוקימנא ליה\u0004 \u0005[הרי בלא כך במה היינו מעמידים,\u0006 מסבירים \u0005אותו\u0006 את הכתוב\u0005]?\u0006","\u0003אי\u0004 \u0005[אם]\u0006 נזקי \u0003קרן\u0004 — הלא \u0003כתיב\u0004 \u0005[נאמר],\u0006 \u0003אי\u0004 \u0005[אם]\u0006 נזקי \u0003רגל\u0004 — הלא \u0003כתיב\u0004 \u0005[נאמר]!\u0006 ומשיבים: \u0003איצטריך\u0004 \u0005[הוצרך]\u0006 הדבר להיאמר, כי \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 \u0003אידי ואידי ארגל\u0004 \u0005[זה וזה\u0006 מדברים \u0005על רגל],\u0006 ואולם \u0003הא\u0004 \u0005[זה]\u0006 שנאמר \"וביער בשדה אחר\" — הרי זה מדובר באופן \u0003דאזיל\u0004 \u0005[ש\u0006היא \u0005הולכת]\u0006 \u0003ממילא\u0004 (מאליה), שהבהמות מזיקות מעצמן, ואילו \u0003הא\u0004 \u0005[זה]\u0006 שנאמר \"ושילח את בעירו\" הרי זה מדובר באופן \u0003דשלח שלוחי\u0004 \u0005[ששלח\u0006 בכוונה\u0005],\u0006 ובשניהם חייבה התורה לשלם, ולא היינו יודעים על נזקי שן, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 ש\"וביער\" הוא נזקי השן.","ושואלים: \u0003והשתא דאוקי אשן\u0004 \u0005[ועכשיו שהעמיד,\u0006 הסביר, את \"וביער\" \u0005על\u0006 נזקי \u0005השן],\u0006 \u0003רגל דאזלא ממילא מנלן\u0004 \u0005[ההולכת מעצמה מניין לנו]\u0006 שחייב עליה? שהרי נאמר באב נזיקין זה רק \"ושילח\"!","ומשיבים: \u0003דומיא\u0004 \u0005[בדומה]\u0006 לנזקי \u0003שן\u0004 שהוזכרו באותו פסוק; \u0003מה שן לא שנא שלחה שלוחי, לא שנא דאזל ממילא\u0004 \u0005[אינו שונה\u0006 אם \u0005שלחה,\u0006 ו\u0005אינו שונה\u0006 אם \u0005הלכה מעצמה]\u0006 — \u0003אף רגל לא שנא שלחה שלוחי, לא שנא אזלא ממילא\u0004 \u0005[אינו שונה\u0006 אם \u0005שלחה,\u0006 ו\u0005אינו שונה\u0006 אם \u0005הלכה מעצמה].\u0006","ושואלים: \u0003ולכתוב רחמנא\u0004 \u0005[ושתכתוב התורה]\u0006 רק \u0003\"ושלח\u0004 את בעירה\u0003\"\u0004\u0003 ולא בעי\u0004 \u0005[יצטרך]\u0006 כלל את הכתוב של \u0003\"ובער\u0004 בשדה אחר \u0003\",\u0004 ונאמר כי הביטוי \"ושילח\" \u0003משמע רגל ומשמע שן,\u0004 כיצד? \u0003משמע רגל\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"משלחי רגל השור והחמור\",\u0004 \u0003ומשמע שן\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"ושן בהמת אשלח בם\"\u0004 (דברים לב, כד)!","ומשיבים: \u0003אי לאו קרא יתירה\u0004 \u0005[אם לא המקרא היתר]\u0006 של \"וביער\", \u0003הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 אין הפסוק מדבר בכל הנזקים, אלא \u0003או הא\u0004 \u0005[זה]\u0006 \u0003או הא\u0004 \u0005[זה]\u0006 והייתי אומר שכוונת הכתוב לחייב בתשלום \u0003או רגל\u0004 לפי ש\u0003הזיקו מצוי\u0004 וצריך שמירה תמידית, \u0003או שן\u0004 ש\u0003יש הנאה להזיקו\u0004 (עם ההיזק).","ומקשים: \u0003מכדי\u0004 \u0005[הרי]\u0006 \u0003שקולין הן,\u0004 ששתי האפשרויות שקולות זו כזו, ושתיהן יכולות להיכנס למשמעות \"ושילח\", \u0003ו\u0004אם כן \u0003יבאו שניהם,\u0004 שהכתוב מדבר בשני אבות נזיקין אלה, \u0003דהי מנייהו מפקת\u0004 \u0005[ש\u0006הרי \u0005איזה מהם אתה מוציא]\u0006 ממשמעות הכתוב? ואם כן, שוב אין צורך ב\"וביער\"! ומשיבים: אף על פי כן \u0003איצטריך\u0004 \u0005[נצרך\u0006 הדבר\u0005],\u0006 שכן \u0003סלקא דעתך אמינא\u0004 \u0005[היה עולה על דעתך לומר]\u0006 כי \u0003הני מילי\u0004 \u0005[דברים אלה\u0006 אמורים\u0005]\u0006 דווקא \u0003היכי דשלח שלוחי\u0004 \u0005[כאשר שולח]\u0006 את בהמתו לשדה חבירו בין לנזקי שן בין לנזקי רגל, \u0003אבל\u0004 אם \u0003אזלא ממילא\u0004 \u0005[הולכת מעצמה]\u0006 — \u0003לא,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שבכל מקרה חייב.","ולאחר שביררנו את המקור בתורה לנזקי שן ורגל, שבים לדון בדבריו של רב פפא \"יש מהן (מן התולדות) שלאו כיוצא בהן (באבות)\", האם דבריו אלה אמורים באבות אלו. \u0003תולדה\u0004 של \u0003שן מאי\u0004 \u0005[מה]\u0006 \u0003היא\u0004 — כגון \u0003נתחככה\u0004 הבהמה \u0003בכותל להנאתה\u0004 וגרמה על ידי כך נזקים לכותל, או \u0003טינפה פירות\u0004 על ידי שנתגלגלה עליהם \u0003להנאתה.\u0004","ואם כן \u0003מאי שנא\u0004 \u0005[במה שונה]\u0006 אב הנזיקין \u0003שן\u0004 שהוא נזק הבא על ידי אכילה, שהגדרתו ש\u0003יש הנאה להזיקו\u0004 שבהמה גורמת נזק מתוך שרצונה ליהנות, \u0003ו\u0004המזיק הוא \u0003ממונך, ושמירתו\u0004 מוטלת \u0003עליך\u0004 — \u0003הני נמי\u0004 \u0005[אלה גם כן]\u0006 נכללים בהגדרה זו לגמרי, שכן גם בהם \u0003יש הנאה להזיקן, וממונך\u0004 הם, \u0003ושמירתן עליך! אלא\u0004 יש לומר כי \u0003תולדה\u0004 של \u0003שן כשן\u0004 עצמה היא. \u0003וכי קאמר\u0004 \u0005[וכאשר אמר]\u0006 \u0003רב פפא\u0004 שיש הבדל בין אב לתולדה הרי זה ביחס ל\u0003תולדה\u0004 של \u0003רגל.\u0004","ועל כך מקשים: \u0003תולדה\u0004 של \u0003רגל מאי\u0004 \u0005[מה]\u0006 \u0003היא\u0004 — כגון ש\u0003הזיקה\u0004 הבהמה \u0003בגופה\u0004 (ולא ברגליה) \u0003דרך הילוכה,\u0004 או \u0003בשערה\u0004 שהסתבך בדבר \u0003דרך הילוכה,\u0004 או \u0003בשליף\u0004 (חבל) \u0003שעליה,\u0004 או \u0003בפרומביא\u0004 (זמם) \u0003שבפיה,\u0004 או \u0003בזוג\u0004 (פעמון) \u0003ש\u0004תלוי \u0003בצוארה.\u0004","אולם גם בזה, \u0003מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה]\u0006 אב הנזיקין \u0003רגל\u0004 שהגדרתו: ש\u0003הזיקו מצוי, וממונך, ושמירתו\u0004 מוטלת \u0003עליך, הני נמי\u0004 \u0005[אלה גם כן]\u0006 \u0003הזיקן מצוי, ו\u0004הם \u0003ממונך, ושמירתן\u0004 מוטלת \u0003עליך! אלא\u0004 ודאי \u0003תולדה\u0004 של \u0003רגל כרגל. וכי קאמר\u0004 \u0005[וכאשר אמר]\u0006 \u0003רב פפא\u0004 דבריו שתולדה אינה כאב, הרי זה על \u0003תולדה\u0004 של \u0003בור.\u0004","ונברר תחילה: \u0003תולדה\u0004 של \u0003בור מאי ניהו\u0004 \u0005[מה הוא]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 ש\u0003אב\u0004 הנזיקין הוא כשהבור עמוק \u0003עשרה\u0004 טפחים לפחות, שזהו שיעור בור האמור בתורה, \u0003ותולדה\u0004 היא בור שעומקו \u0003תשעה\u0004 טפחים. אולם, הרי \u0003לא תשעה כתיבי\u0004 \u0005[נאמרו]\u0006 בתורה במפורש, \u0003ולא עשרה כתיבי\u0004 \u0005[נאמרו],\u0006 ואם אב הנזיקין הוא זה הכתוב במפורש בתורה — הרי שניהם אינם כתובים!","ומשיבים: \u0003הא לא קשיא\u0004 \u0005[זה אינו קשה],\u0006 ואפשר לומר שאף שאין השיעורים מפורשים בכתוב, מכל מקום כך יש להבין את משמעו. שהרי בנזקי בור \u0003\"והמת יהיה לו\"\u0004 (שמות כא, לד) \u0003אמר רחמנא\u0004 \u0005[אמרה התורה],\u0006 \u0003וקים להו לרבנן\u0004 \u0005[ומוחזק להם לחכמים]\u0006 כי \u0003עשרה\u0004 טפחים בעומק \u0003עבדן\u0004 \u0005[עושים,\u0006 גורמים\u0005]\u0006 \u0003מיתה\u0004 לבעל חיים הנופל בהם, ואילו \u0003תשעה\u0004 טפחים — \u0003נזיקין עבדי\u0004 \u0005[עושים],\u0006 \u0003מיתה לא עבדי\u0004 \u0005[עושים].\u0006 ואם כן אותו בור הכתוב בתורה — של עשרה טפחים הוא, ופחות מכן הריהו תולדה.","ועדיין מקשים: \u0003סוף סוף\u0004 נמצא כי \u0003זה,\u0004 בור בן עשרה טפחים, הוא \u0003אב\u0004 נזיקין \u0003למיתה, וזה\u0004 של תשעה טפחים הוא \u0003אב לנזקין\u0004 אחרים, ואין איפוא לחלק בין בור עשרה לבור תשעה, ולומר כי אחד מהם הוא אב והשני הוא תולדה!","\u0003אלא\u0004 יש לומר שדבריו של רב פפא אודות התולדות שאינן כאב, מוסבים \u0003אאבנו\u0004 \u0005[על אבנו],\u0006 \u0003סכינו, ומשאו שהניחן ברשות הרבים והזיקו,\u0004 ואלה דינם אינו כדין אב הנזיקין בור.","ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אי דאפקרינהו\u0004 \u0005[אם שהפקירם]\u0006 את אבנו סכינו ומשאו — הרי \u0003בין ל\u0004שיטת \u0003רב ובין ל\u0004שיטת \u0003שמואל\u0004 שתתבררנה להלן — \u0003היינו\u0004 \u0005[זהו]\u0006 ממש, \u0003בור\u0004 ששניהם מסכימים כי בכלל הגדרת בור כל דבר שהפקירו בעליו, וגרם להיזק ברשות הרבים."],["\u0003ואי\u0004 \u0005[ואם]\u0006 מדובר במקרה ש\u0003לא אפקרינהו\u0004 \u0005[הפקירם],\u0006 הרי \u0003אי\u0004 \u0005[אם]\u0006 \u0003ל\u0004דעת \u0003שמואל\u0004 ש\u0003אמר\u0004 שכל המכשולים \u0003כולם\u0004 שאדם מניח ברשות הרבים אף שלא הפקירם \u0003מבורו למדנו,\u0004 ובכלל בור הם, אם כן, \u0003היינו\u0004 \u0005[הרי זה]\u0006 \u0003בור,\u0004 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003ל\u0004שיטת \u0003רב\u0004 ש\u0003אמר\u0004 שמכשולים כאלה שלא הפקירם \u0003כולם משורו,\u0004 מדין קרן, \u0003למדנו,\u0004 שבכללה ממונו המזיק ברשות הרבים, בין שהלך והזיק בין שהלך אחר והוזק בו — \u0003היינו\u0004 \u0005[הרי זה]\u0006 \u0003שור,\u0004 לכל דיניו. ונאמר: לשיטת רב שתולדות הקרן הן, הרי כבר נתברר שתולדות הקרן הן כמותה.","ואולם אף לשיטת שמואל שתולדות הבור הן, \u0003מאי שנא\u0004 \u0005[מה שונה]\u0006 \u0003בור\u0004 — \u0003שכן תחלת עשייתו\u0004 גורמת \u0003לנזק,\u0004 \u0003ו\u0004הוא \u0003ממונך, ושמירתו\u0004 מוטלת \u0003עליך,\u0004 אם כן \u0003הני נמי\u0004 \u0005[אלה גם כן]\u0006 \u0003תחלת עשייתן לנזק,\u0004 \u0003ו\u0004הם \u0003ממונך, ושמירתן\u0004 מוטלת \u0003עליך! אלא\u0004 יש לומר כי כל \u0003תולדה\u0004 של \u0003בור\u0004 הרי היא \u0003כבור, וכי קאמר\u0004 \u0005[וכאשר אמר]\u0006 \u0003רב פפא\u0004 שיש הבדל בין תולדה לאב — הרי זה על \u0003תולדה\u0004 של ה\u0003מבעה.\u0004","אלא שדבר זה עצמו צריך עיון, שכן \u0003מאי ניהו\u0004 \u0005[מה הוא]\u0006 מבעה זה? כי כפי שיתבאר להלן לא ברור מה הוא בדיוק המבעה הכתוב במשנה, ומעתה \u0003אי\u0004 \u0005[אם]\u0006 \u0003ל\u0004דעת \u0003שמואל\u0004 ש\u0003אמר: מבעה זו שן\u0004 — \u0003הא אוקימנא\u0004 \u0005[הרי\u0006 כבר \u0005העמדנו,\u0006 הגענו למסקנה\u0005]\u0006 ש\u0003תולדה\u0004 של \u0003שן\u0004 — \u0003כשן. אי\u0004 \u0005[אם]\u0006 \u0003ל\u0004דעת \u0003רב,\u0004 ש\u0003אמר: מבעה זה אדם\u0004 המזיק, אם כן \u0003מאי\u0004 \u0005[מה]\u0006 \u0003אבות ומאי\u0004 \u0005[ומה]\u0006 \u0003תולדות אית ביה\u0004 \u0005[יש בו]\u0006 באדם המזיק? הרי לכל נזקיו יש דין אחד!","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 לחלק כך באדם המזיק: \u0003אב\u0004 נזיקין לגבי אדם, הוא כאשר הזיק בזמן שהוא \u0003ניעור,\u0004 ואילו \u0003תולדה\u0004 היא כאשר הוא \u0003ישן\u0004 וגורם נזק שלא בכוונה, אלא תוך כדי שינה, \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003אדם\u0004 נחשב \u0003מועד לעולם, בין\u0004 שהוא \u0003ער\u0004 בעת שמזיק, \u0003בין\u0004 שהוא אז \u0003ישן.\u0004 משמע שלגבי אדם אין חלוקה בין ער לישן לענין אחריותו בנזקין!","\u0003אלא\u0004 תאמר שהכוונה בתולדה היא ל\u0003כיחו וניעו\u0004 שגרמו לנזק. על כך יש לשאול: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק\u0006 \u0005היה הדבר]?\u0006 \u0003אי בהדי דאזלי קמזקי\u0004 \u0005[אם בשעה ש\u0006הם \u0005הולכים,\u0006 יוצאים מפיו, הם \u0005מזיקים]\u0006 (שליכלכו דבר או המאיסוהו משימוש) הרי \u0003כחו הוה\u0004 \u0005[היה\u0006 זה\u0005],\u0006 שדינם כשאר דברים שאדם עושה בכחו, והריהם כמו שעושה בגופו. \u0003אי בתר דנייח\u0004 \u0005[אם לאחר שנח]\u0006 הרוק במקומו נתקל בו אדם וניזוק, אם כן \u0003בין לרב בין לשמואל\u0004 דבר שהפקירו ברשות הרבים וגורם לנזק \u0003היינו\u0004 \u0005[זהו]\u0006 \u0003בור\u0004 וכבר אמרנו שתולדותיו כמותו! \u0003אלא תולדה\u0004 של \u0003מבעה,\u0004 בכל אופן שנבין מושג זה, דינה \u0003כמבעה. וכי קאמר\u0004 \u0005[וכאשר אמר]\u0006 \u0003רב פפא\u0004 שיש הבדל בין תולדה לאב הרי זה בענין \u0003תולדה\u0004 של \u0003אש.\u0004","ושואלים: \u0003תולדה\u0004 של \u0003אש מאי ניהו\u0004 \u0005[מה היא]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003אבנו סכינו ומשאו שהניחן\u0004 במקום גבוה, כגון \u0003בראש גגו, ונפלו ברוח מצויה והזיקו,\u0004 עדיין יש לברר: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר],\u0006 \u0003אי בהדי דאזלי קא מזקי\u0004 \u0005[אם בשעה שהולכים,\u0006 נופלים, הם \u0005מזיקים]\u0006 \u0003היינו\u0004 \u0005[זהו]\u0006 \u0003אש,\u0004 שהרי","\u0003מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה]\u0006 \u0003אש\u0004 שהגדרתה היא ש\u0003כח אחר מעורב בהן,\u0004 שהרי אין האש שהדליק מזיקה אלא בסיוע הרוח, \u0003ו\u0004מעיקרו \u0003ממונך\u0004 היא, \u0003ושמירתו\u0004 מוטלת \u0003עליך, הני נמי\u0004 \u0005[אלה גם כן]\u0006 יש בהם את כל התנאים הללו: \u0003כח אחר מעורב בהן, ו\u0004הם \u0003ממונך, ושמירתן\u0004 מוטלת \u0003עליך! אלא תולדה\u0004 של \u0003אש כאש, וכי קאמר\u0004 \u0005[וכאשר אמר]\u0006 \u0003רב פפא\u0004 שיש להבדיל בין תולדה לאב הרי זה על \u0003תולדה\u0004 של \u0003רגל.\u0004","ותוהים: \u0003רגל?! הא אוקימנא\u0004 \u0005[הרי\u0006 כבר \u0005העמדנו,\u0006 הסברנו\u0005]\u0006 ש\u0003תולדה\u0004 של \u0003רגל\u0004 הרי היא \u0003כרגל!\u0004 ומשיבים: רב פפא אמר דבריו \u0003בחצי נזק צרורות.\u0004 שאם הלכה בהמה כדרכה, והתיזה צרורות אבן או דברים אחרים מתחת רגליה, והלכו אלה וגרמו לנזק — משלם בעל הבהמה חצי נזק בלבד, כדין קרן. \u0003דהלכתא גמירי לה\u0004 \u0005[שהלכה\u0006 למשה מסיני \u0005למדנו אותה]\u0006 ואינה מפורשת בתורה, שמשלם על כך חצי נזק בלבד.","ומסבירים: \u0003ואמאי קרי\u0004 \u0005[ומדוע,\u0006 לאיזה ענין, \u0005קורא]\u0006 \u0003לה\u0004 רב פפא \u0003תולדה\u0004 של \u0003רגל\u0004 למרות שהוא סוג נזק מיוחד לעצמו — הרי זה לענין \u0003לשלם מן העלייה\u0004 (ממיטב ממונו ולא מגוף המזיק), כלומר, חיוב התשלומים מוטל על בעל הבהמה, ומשלם אותם מממונו, ולא מגוף המזיק, כפי שמשלמים חצי נזק בשור תם שנגח.","ושואלים: וכי הלכה זו ברורה היא? \u0003והא מבעיא בעי\u0004 \u0005[והרי שאל\u0006 והסתפק בכך\u0005]\u0006 \u0003רבא.\u0004 \u0003דבעי\u0004 \u0005[ששאל]\u0006 \u0003רבא:\u0004 \u0003חצי נזק\u0004 שמשלמים הבעלים על נזקי \u0003צרורות\u0004 של בהמותיהם, האם \u0003מגופו\u0004 של המזיק \u0003משלם\u0004 בעליו, או מן העלייה הוא \u0003משלם?\u0004 ודוחים: זו אינה קושיה, \u0003לרבא\u0004 —","\u0003מבעיא ליה\u0004 \u0005[מסופקת לו\u0006 הלכה זו\u0005],\u0006 \u0003לרב פפא פשיטא ליה\u0004 \u0005[פשוטה לו]\u0006 שמשלם מהעלייה.","ושואלים: ו\u0003לרבא דמבעיא ליה\u0004 \u0005[שנשאלה לו]\u0006 שהיה לו ספק בדבר, \u0003אמאי קרי\u0004 \u0005[מדוע,\u0006 לאיזה ענין \u0005קורא]\u0006 \u0003לה\u0004 לצרורות, \u0003תולדה\u0004 של \u0003רגל?\u0004 והרי דינה שונה לגמרי מדין רגל, הן בגודל חיוב הנזק והן בדרך תשלומיו! ומסבירים: בכל זאת דומה דין זה לרגל לענין \u0003לפוטרה ברשות הרבים,\u0004 כי אין חייבים על נזקי רגל, ולא על צרורות, ברשות הרבים, כיון שהכל מותר להם ללכת בה.","לאחר שביררנו ענין אב ותולדה בנזיקין, באים לבאר את המונחים השונים המוזכרים במשנה. בין אבות נזיקין נמנו \u0003המבעה וההבער.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"מבעה\"\u0004 שאמרו? — \u0003רב אמר: מבעה זה אדם,\u0004 והכוונה היא לנזקים שגורם אדם בעצמו. \u0003ושמואל אמר: מבעה זה השן\u0004 של בהמה.","ומבארים את דבריהם: \u0003רב אמר: מבעה זה אדם, דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 \u0003\"אמר שמר אתא בקר וגם לילה אם תבעיון בעיו\"\u0004 (ישעיה כא, יב), הרי שלשון \"בעה\" מתייחסת לאדם.","\u0003ושמואל אמר: מבעה זה השן, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"איך נחפשו עשו נבעו מצפניו\"\u0004 (עובדיה א, ו). על פסוק זה שהובא לדעת שמואל, שואלים: \u0003מאי משמע\u0004 \u0005[מה המשמעות],\u0006 כלומר, כיצד מגיעים מפסוק זה למשמעות של שן? ומשיבים: \u0003כדמתרגם\u0004 \u0005[כמו שהיה מתרגם]\u0006 \u0003רב יוסף\u0004 פסוק זה בתרגום המקובל: \u0003איכדין איתבליש\u0004 \u0005[איך זה נחפש]\u0006 \u0003עשו אתגלין מטמרוהי\u0004 \u0005[נגלו מסתריו],\u0006 ואם כן \"נבעה\" משמעו — נתגלה, ולענייננו: מבעה זה השן, שכן שיניה של הבהמה מתגלות בשעת האכילה.","ומבררים: \u0003ורב מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אמר כשמואל?\u0004 ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך: מי קתני\u0004 \u0005[האם שנה]\u0006 במשנה \u0003\"נבעה\"?\u0004 שהרי לפי הסברו של שמואל צריך לקרוא לשן \"נבעה\" — מה שנתגלה.","ושואלים: \u0003ושמואל מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אמר כרב?\u0004 ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך:\u0004 \u0003מי קתני\u0004 \u0005[האם שנה]\u0006 \u0003\"בועה\"\u0004 לומר שהיא פעולה ישירה של האדם? הלא \"מבעה\" שנינו, ומשמע שגורם לאחר לעשות מעשה.","ולבירור הדברים שואלים: \u0003מכדי קראי\u0004 \u0005[הרי הכתובים]\u0006 עצמם \u0003לא כמר דייקי\u0004 \u0005[כחכם זה מדוייקים]\u0006 \u0003ולא כמר דייקי\u0004 \u0005[כחכם זה מדוייקים],\u0006 שהרי לשון \"מבעה\" איננה זהה לכתובים שהביאו חכמים אלה, ולכן בהכרח לא על סמך לשון הכתוב נחלקו, אלא מטעם אחר, אם כן יש לחזור ולשאול: \u0003רב מאי טעמא\u0004 \u0005[מה הטעם]\u0006 \u0003לא אמר כשמואל?\u0004 ומשיבים: לדעת רב \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]\u0006 \u0003שור\u0004 \u0003וכל מילי\u0004 \u0005[הדברים]\u0006 של \u0003שור\u0004 בכלל זה. כלומר, שלדעתו \"שור\" כולל את שלושה מיני הנזיקין שעושה השור; בקרן בשן וברגל, ובהכרח מבעה הוא סוג נזיקין אחר.","ושואלים: \u0003ושמואל נמי\u0004 \u0005[גם כן]\u0006 \u0003הא תנא ליה\u0004 \u0005[הרי שנה כבר]\u0006 \u0003שור\u0004 ובכלל זה שן! \u0003אמר רב יהודה: תנא\u0004 \u0005[שנה\u0006 החכם במשנה\u0005]\u0006 \u0003שור\u0004 \u0003ל\u0004ענין \u0003קרנו,\u0004 שסתם נזקי שור נזקי קרן הם, כמפורש בכתוב. \u0003ומבעה\u0004 — \u0003ל\u0004ענין \u0003שינו\u0004 של שור או שאר בהמה. \u0003והכי קאמר\u0004 \u0005[וכך אמר],\u0006 כך יש להבין את המשך לשון המשנה: צריך הכתוב לפרט את החיוב באבות הנזיקין השונים, שכן \u0003לא ראי\u0004 \u0003הקרן\u0004 שחמור \u0003שאין הנאה להזיקו, כראי\u0004 \u0003השן\u0004 שאינה חמורה כמותה, \u0003שיש הנאה\u0004 לבהמה \u0003להזיקה,\u0004 ואין כאן נזק מכוון."],["\u0003ולא ראי השן שאין כוונתו להזיק\u0004 אלא ליהנות, \u0003כראי הקרן שכוונתו להזיק,\u0004 ולכן לא ניתן היה ללמוד קרן משן.","ושואלים: \u0003ולאו\u0004 \u0005[והאם לא]\u0006 \u0003קל וחומר הוא:\u0004 \u0003ומה שן\u0004 הקלה \u0003ש\u0004כן \u0003אין כוונתו להזיק\u0004 — בכל זאת \u0003חייב\u0004 על נזקיה, \u0003קרן\u0004 החמורה, \u0003ש\u0004כן \u0003כוונתו להזיק\u0004 — \u0003לא כל שכן\u0004 שחייב? ומשיבים: \u0003איצטריך\u0004 \u0005[הוצרך]\u0006 הכתוב לאומרו, כי \u0003סלקא דעתך אמינא\u0004 \u0005[היה עולה על דעתך לומר]\u0006 שתהא קרן פטורה \u0003מידי דהוה\u0004 \u0005[כשם שהוא]\u0006 הדין בענין \u0003עבד ואמה, עבד ואמה לאו אף על גב\u0004 \u0005[האם לא אף על פי]\u0006 ש\u0003כוונתן להזיק, אפילו הכי\u0004 \u0005[כך]\u0006 \u0003פטירי\u0004 \u0005[פטורים]\u0006 בעליהם מתשלום על הנזקים שעשו? \u0003הכי נמי לא שנא\u0004 \u0005[כך גם כן אינו שונה],\u0006 שלא יתחייבו הבעלים על נזק שגרם ממונם מתוך כוונה להזיק, ושמא אף על הקרן אינו משלם, ולכן צריך הכתוב להשמיענו שחייבים.","\u0003אמר רב אשי: אטו\u0004 \u0005[וכי]\u0006 \u0003עבד ואמה לאו טעמא רבה אית בהו\u0004 \u0005[האם לא טעם גדול יש בהם]\u0006 לפטור את בעליהם מנזקים שעשו? שהרי באלה קיים החשש \u0003שמא\u0004 כאשר \u0003יקניטנו\u0004 (יצערנו) \u0003רבו\u0004 (אדוניו), \u0003וילך\u0004 העבד \u0003וידליק גדישו של חבירו, ונמצא זה מחייב את רבו\u0004 לשלם \u0003מאה מנה בכל יום.\u0004 ואין איפוא להביא ראיה מעבד, שייתכן שמצד הדין יש חובת תשלומים על האדון לנזקי העבד, אלא שאי אפשר לעשות כן, כדי למנוע מצב של נזק שבו העבד מתכוון לגרום הפסד לרבו.","\u0003אלא פריך הכי\u0004 \u0005[שבור,\u0006 אמור את הדברים \u0005כך,\u0006 אחרת\u0005]:\u0006 \u0003לא ראי הקרן\u0004 שהוא חמור, \u0003ש\u0004כן \u0003כוונתו להזיק, כראי השן\u0004 שהוא קל, \u0003ש\u0004כן \u0003אין כוונתו להזיק, ולא ראי השן שיש הנאה להזיקו, כראי הקרן שאין הנאה להזיקו.\u0004","ושואלים: ולפי דעת שמואל ש\"שור\" במשנה הוא קרן ו\"מבעה\" הוא שן, \u0003ורגל מאי\u0004 \u0005[מה]?\u0006 וכי \u0003שייריה\u0004 \u0005[שייר אותה]?!\u0006 שהרי לפי פירוש זה אין נזכר כלל במשנה עניינה של רגל! ומשיבים: סיום המשנה \u0003\"כשהזיק חב המזיק\"\u0004 הרי זו לשון כוללת, וממנה למדים \u0003לאתויי\u0004 \u0005[להביא,\u0006 להוסיף\u0005]\u0006 על ידי כלל זה גם נזקי \u0003רגל.\u0004","ומקשים: \u0003וליתנייה בהדיא\u0004 \u0005[ושישנה אותו במפורש]!\u0006","\u0003אלא אמר רבא:\u0004 יש לחזור מפירוש זה, ולומר כי \u0003תנא\u0004 \u0005[שנה]\u0006 \u0003שור ל\u0004ענין נזקי \u0003רגלו, ומבעה ל\u0004ענין נזקי \u0003שינו. והכי קאמר\u0004 \u0005[וכך אמר],\u0006 כך יש להבין את דברי המשנה: \u0003לא ראי הרגל\u0004 שהיא חמורה כיון \u0003שהזיקה מצוי, כראי השן שאין הזיקה מצוי. ולא ראי השן שיש הנאה להזיקו, כראי הרגל שאין הנאה להזיקו.\u0004","ושואלים: אם כן, \u0003וקרן מאי\u0004 \u0005[מה]?\u0006 וכי \u0003שייריה\u0004 \u0005[שייר אותה]?!\u0006 ומשיבים: הביטוי \u0003\"כשהזיק חב המזיק\"\u0004 בלשון כללית בא \u0003לאתויי\u0004 \u0005[להביא]\u0006 גם נזקי \u0003קרן.\u0004","ושואלים: \u0003וליתנייה בהדיא\u0004 \u0005[ושישנה אותו במפורש],\u0006 ומדוע רק רמז לנזק זה? ומשיבים: \u0003במועדין מתחילתן\u0004 בלבד \u0003קמיירי\u0004 \u0005[עוסק\u0006 במשנה זו\u0005],\u0006 שמנה בה סוגי נזקים שבהם המזיק אחראי לתשלום כל הנזק כבר בפעם הראשונה שהזיק, ואילו \u0003בתמין ולבסוף מועדין לא קמיירי\u0004 \u0005[עוסק]\u0006 ודין קרן שונה משאר הנזיקין, שהרי יש בו הבדל בין תשלומי תם למועד, ולכן אינו נכנס לכלל זה.","ולעצם פירוש \"מבעה\" שואלים: \u0003ושמואל מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אמר כרב?\u0004 ומסבירים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך:\u0004 \u0003אי סלקא דעתך\u0004 \u0005[אם עולה על דעתך]\u0006 לומר שהכוונה ב\"מבעה\" היא ל\u0003אדם, הא קתני סיפא\u0004 \u0005[הרי שנינו\u0006 ב\u0005סופה\u0006 של המשנה\u0005]\u0006 (ולפי חלוקתנו, במשנה הבאה): \u0003שור המועד, ושור המזיק\u0004 שהזיק \u0003ברשות הניזק, והאדם,\u0004 הרי הוא שנוי בחלק זה של המשנה, ואין דרך התנא לחזור על דבריו.","ושואלים: ומכל מקום \u0003וליתני ברישא\u0004 \u0005[ושישנה\u0006 וימנה גם את האדם \u0005בראש\u0006 המשנה\u0005]\u0006 בין אבות הנזיקין! ומשיבים: \u0003בנזקי ממון קמיירי\u0004 \u0005[מדבר],\u0006 שהמשנה עוסקת בנזקים שנגרמים על ידי רכושו של אדם, ואילו \u0003בנזקי גופו,\u0004 כאשר הוא עצמו מזיק — \u0003לא קמיירי\u0004 \u0005[אינו מדבר,\u0006 עוסק\u0005].\u0006","ושואלים: \u0003ו\u0004לדעת \u0003רב נמי\u0004 \u0005[גם כן]\u0006 קשה: \u0003הא קתני\u0004 \u0005[הרי שנה]\u0006 \u0003אדם\u0004 במפורש \u0003בסיפא\u0004 \u0005[בסוף\u0006 המשנה\u0005],\u0006 משמע שלא דובר בו בתחילת המשנה, ואם כן \"מבעה\" אינו אדם! ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך רב:\u0004 לא לצורך עצם הענין נזכר אדם בסוף המשנה, אלא \u0003ההוא\u0004 כדי \u0003למחשביה בהדי\u0004 \u0005[למנות אותו אצל]\u0006 ה\u0003מועדין הוא דאתא\u0004 \u0005[שבא],\u0006 לומר שאדם המזיק מבחינת הדין נמנה בין המועדים.","ושואלים: \u0003ו\u0004לפי שיטת רב \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"לא הרי\u0004 השור כהרי המבעה\u0003\"\u0004וכו' ששנינו במשנתנו?","ומשיבים: \u0003הכי קאמר\u0004 כך יש להבין: \u0003לא ראי השור\u0004 שהוא חמור \u0003שמשלם את הכופר\u0004 אם הרג אדם, \u0003כראי האדם\u0004 שהרג \u0003שאין משלם את הכופר\u0004 אלא נענש בגופו, אם בגלות (כשהרג בשוגג) ואם במיתה (כשהרג בעדים ובהתראה), \u0003ולא ראי האדם\u0004 שהזיק לאדם אחר \u0003שחייב\u0004 מלבד הנזק \u0003בארבעה דברים:\u0004 צער, בושת, ריפוי ושבת, \u0003כראי השור שאין בו ארבעה דברים\u0004 אלו, אלא תשלומי נזק בלבד.","ומעתה יש לשאול על המשך המשנה לאור הבנה זו של רב, ש\"מבעה\" הוא אדם ו\"שור\" הוא כל נזקי שור, ובכללם קרן, שהרי שנינו: \u0003הצד השוה שבהן\u0004 — \u0003שדרכן להזיק\u0004 ושמירתם עליך. \u0003וכי שור דרכו להזיק?\u0004 הלא בדרך כלל אין השור מזיק ונוגח! ומשיבים: כאן מדובר \u0003ב\u0004שור \u0003מועד.\u0004 ושואלים שוב: \u0003ו\u0004אף שור \u0003מועד\u0004 שנגח שלוש פעמים, וכי אפשר לומר עליו ש\u0003דרכו להזיק?\u0004 ומשיבים: \u0003כיון דאייעד\u0004 \u0005[שהועד]\u0006 — \u0003אורחיה\u0004 \u0005[דרכו]\u0006 \u0003הוא,\u0004 וכשם שנזקים אחרים הם דרכם של המזיקים, אף נגיחתו של שור המועד — דרכו היא.","ושואלים על פרט אחר לשיטת רב: אם \"מבעה\" הוא האדם, \u0003ו\u0004כי \u0003אדם דרכו להזיק?\u0004 ומשיבים: מדובר כאן \u0003בישן,\u0004 שהוא מזיק תוך שנתו. ומקשים: ו\u0003ישן דרכו להזיק?\u0004 ומשיבים: \u0003כיון\u0004 שתוך כדי שנתו הוא \u0003כייף ופשיט\u0004 \u0005[כופף ופושט]\u0006 ידיו ורגליו — \u0003אורחיה\u0004 \u0005[דרכו]\u0006 \u0003הוא\u0004 שכל דבר שמצוי בסמוך לו יינזק, ונמצא שדרכו להזיק בלא שיתכוון לכך.","ומקשים עוד: אם \"מבעה\" הוא אדם, וכי יכול אתה לומר \u0003\"ושמירתן עליך\"\u0004 כאילו מוטלת על אדם אחד שמירה על אדם אחר? והרי \u0003אדם שמירת גופו עליו הוא!\u0004","ומשיבים: \u0003ולטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005]\u0006 שאתה תמה על לשון זו ביחס לאדם, \u0003הא דתני\u0004 \u0005[זו ששנה\u0006 החכם\u0005]\u0006 \u0003קרנא\u0004 בגירסת ברייתא: \u0003ארבעה אבות נזיקין, ואדם אחד מהן,\u0004 וגם שם נאמר \"ושמירתן עליך\", הרי אף שם יכול אתה לתהות: והרי \u0003אדם\u0004 — \u0003שמירת גופו עליו הוא! אלא\u0004 יש לומר \u0003כדאמר ליה\u0004 \u0005[כפי שאמר לו]\u0006 \u0003ר' אבהו לתנא\u0004 \u0005[לחוזר המשניות]:\u0006 \u0003תני\u0004 \u0005[שנה]:\u0006 \u0003אדם\u0004 — \u0003שמירת גופו עליו,\u0004 ואכן, מוטלת עליו חובה לשמור על גופו שלא יזיק לאחרים,"],["\u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003תני\u0004 \u0005[שנה]:\u0006 \u0003אדם שמירת גופו עליו.\u0004","על מחלוקת רב ושמואל בפירוש \"מבעה\" שבמשנה \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב מרי:\u0004 אם מפרשים \"מבעה\" רק לפי הדמיון הלשוני, \u0003ואימא\u0004 \u0005[ואמור]:\u0006 \u0003מבעה זה המים\u0004 הנזקים הנגרמים מחמת מים הזורמים או נשפכים, \u0003כדכתיב\u0004 \u0005[כמו שנאמר]\u0006 \u0003\"כקדוח אש המסים מים תבעה אש\"\u0004 (ישעיה סד,א)! ומשיבים: \u0003מי כתיב\u0004 \u0005[האם נאמר]\u0006 בפסוק \u0003\"מים נבעו\"? \"תבעה אש\" כתיב\u0004 \u0005[נאמר],\u0006 כלומר, לא המים הם הפועלים באש, אלא האש מבעה את המים.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב זביד\u0004 בדומה לרב מרי: אם כן, \u0003ואימא\u0004 \u0005[ואמור]\u0006 \u0003מבעה זה האש,\u0004 שהרי הסברנו \u0003דכי כתיב\u0004 \u0005[שכאשר נאמר]\u0006 \u0003\"תבעה\" — באש הוא דכתיב\u0004 \u0005[שנאמר]!\u0006 ומשיבים: דבר זה אינו אפשרי לפי המשנה, כי \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"המבעה וההבער\"\u0004 הכתובים זה עם זה במשנתנו, שמכאן משמע שהמבעה אינו הבער? \u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 \u0003פרושי קמפרש\u0004 \u0005[מפרש\u0006 התנא במשנתנו] את הדברים, ש\"מבעה\" משמעו \"הבער\" — \u0003אי הכי\u0004 \u0005[אם כך],\u0006 האם יש לשנות \u0003\"ארבעה\u0004 אבות נזיקין\"? הלוא רק \u0003שלשה הוו\u0004 \u0005[הם]!\u0006","\u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003תנא\u0004 \u0005[שנה\u0006 במשנה\u0005]\u0006 \u0003שור דאית ביה תרתי\u0004 \u0005[שיש בו שנים]\u0006 גם שן וגם רגל, והרי הם בסך הכל ארבעה אבות נזיקין יחד עם הבור והאש, מכל מקום עדיין קשה מצד אחר: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 אם מפרשים שמבעה הוא אש, הלוא בהמשך המשנה נאמר לגבי מבעה ושור \u0003\"לא זה וזה שיש בהן רוח חיים\",\u0004 \u0003אש מאי\u0004 \u0005[מה]\u0006 \u0003רוח חיים אית ביה\u0004 \u0005[יש בו]?\u0006 \u0003ותו\u0004 \u0005[ועוד\u0006 קשה]: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 המשך הדברים שם \"לא זה וזה — השור והמבעה — \u0003כהרי האש\",\u0004 אם אומרים שהמבעה הוא האש? ולכן אין מקום לפירוש זה.","לאחר שביררנו לפי שתי השיטות את מנין אבות הנזיקין שבמשנה, מביאים שיטות אחרות ושונות של מנין אבות הנזיקין. \u0003תני\u0004 \u0005[שנה]\u0006 \u0003רב אושעיא: שלשה עשר אבות נזיקין,\u0004 כלומר שלושה עשר אופנים הם שאדם חייב לשלם בנזיקין, ואלו הם: ארבעה שומרים: \u0003שומר חנם\u0004 שהתרשל (\"פשע\") בשמירת הדבר שקיבל לשמירתו, \u0003והשואל\u0004 שהדבר ששאל מת או אבד, \u0003נושא שכר\u0004 (שומר שכר, המקבל שכר על השמירה) שחייב באחריותו על גניבה ואבידה וכן \u0003השוכר\u0004 דבר מחבירו לעבוד בו. חמשה סוגי תשלום של אדם שהזיק לחבירו: \u0003נזק\u0004 פחת שגורם לגופו, \u0003צער\u0004 תשלום על הכאב, \u0003ו\u0004דמי \u0003ריפוי, שבת\u0004 דמי ביטול ממלאכה, \u0003ובושת\u0004 אם גרם גם בושת לחבירו בנזק זה. \u0003וארבעה\u0004 אבות \u0003דמתניתין\u0004 \u0005[של משנתנו] —\u0006 \u0003הא תליסר\u0004 \u0005[הרי שלושה עשר].\u0006","ושואלים: \u0003ותנא דידן מאי טעמא לא תני הני\u0004 \u0005[והתנא שלנו,\u0006 במשנה, \u0005מה טעם לא שנה את אלה]\u0006 ומנה רק ארבעה? \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003שמואל\u0004 ש\"מבעה\" זה השן, אפשר לומר שלשיטתו — \u0003בנזקי ממון\u0004 שממונו של אדם הזיק \u0003קמיירי\u0004 \u0005[עוסק\u0006 במשנה\u0005],\u0006 ואילו \u0003בנזקי גופו\u0004 של אדם עצמו שהזיק \u0003לא קמיירי\u0004 \u0005[אינו עוסק].\u0006 ולכן אין מקום למנות את אלו. \u0003אלא ל\u0004שיטת \u0003רב\u0004 ש\"מבעה\" הוא האדם, \u0003ליתני\u0004 \u0005[שישנה\u0006 גם את אלה\u0005]!\u0006 ומשיבים: לשיטתו של רב \u0003תנא\u0004 \u0005[שנה]\u0006 במשנה \u0003אדם ו\u0004כלל בו \u0003כל מילי\u0004 \u0005[הדברים]\u0006 שהם נזקים הנגרמים על ידי \u0003אדם\u0004 ולא פירט.","ושואלים: \u0003ולר' אושעיא נמי\u0004 \u0005[גם כן]\u0006 \u0003הא תנא ליה\u0004 \u0005[הרי כבר שנה]\u0006 \u0003אדם\u0004 במשנה! ומשיבים: לשיטתו יש להבחין בין \u0003תרי גווני\u0004 \u0005[שני סוגים]\u0006 של נזקי \u0003אדם.\u0004 ולכן רב אושעיא \u0003תנא\u0004 \u0005[שנה]\u0006 \u0003אדם דאזיק\u0004 \u0005[שהזיק]\u0006 \u0003אדם\u0004 והם הדברים שמנה רב אושעיא, \u0003ותנא\u0004 \u0005[ושנה]\u0006 \u0003אדם דאזיק\u0004 \u0005[שהזיק]\u0006 \u0003שור\u0004 כלומר, הזיק רכוש של אחר, בעלי חיים או חפצים אחרים, ולא לאדם. שהוא מה שהוזכר במשנתנו כ\"מבעה\".","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 אתה מחלק בפרטי המזיקים, \u0003שור נמי\u0004 \u0005[גם כן]\u0006 \u0003ליתני תרי גווני\u0004 \u0005[שישנה שני סוגי]\u0006 \u0003שור\u0004 אפילו בנזקי קרן, באופן זה: \u0003ליתני\u0004 \u0005[שישנה]\u0006 נזק \u0003שור דאזיק\u0004 \u0005[שהזיק]\u0006 \u0003שור, וליתני\u0004 \u0005[ושישנה]\u0006 נזקי \u0003שור דאזיק\u0004 \u0005[שהזיק]\u0006 \u0003אדם!\u0004","ודוחים: \u0003האי מאי\u0004 \u0005[זו מה היא]?\u0006 כלומר, אין מקום לקושיה זו כלל, שכן \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003אדם דאזיק\u0004 \u0005[שהזיק]\u0006 \u0003שור\u0004 — \u0003נזק\u0004 בלבד \u0003הוא שמשלם\u0004 על הזיקו, ואילו \u0003אדם דאזיק\u0004 \u0005[שהזיק]\u0006 \u0003אדם — משלם\u0004 נוסף לזה \u0003ארבעה דברים\u0004: צער, ריפוי, שבת ובושת. ונמצא שאלו הם שני סוגים שונים של חיובים. \u0003אלא שור\u0004 המזיק, \u0003מה לי שור דאזיק\u0004 \u0005[שהזיק]\u0006 \u0003שור, מה לי שור דאזיק\u0004 \u0005[שהזיק]\u0006 \u0003אדם, אידי ואידי\u0004 \u0005[זה וזה] —\u0006 \u0003נזק\u0004 בלבד \u0003הוא\u0004 ש\u0003משלם\u0004 ולא יותר. ואם כן, אין מקום לחלק ביניהם ולמנותם בנפרד.","ומקשים: אם אומר אתה שרב אושעיא לא הוסיף על האמור במשנה אלא נזקי אדם באדם \u0003והא\u0004 \u0005[והרי]\u0006 \u0003שומר חנם והשואל, נושא שכר והשוכר,\u0004 שאף הם בגדר \u0003אדם דאזיק\u0004 \u0005[שהזיק]\u0006 \u0003שור הוא,\u0004 שהרי הזיק חפץ (או שור) ומשלם רק את הנזק בלבד, \u0003ו\u0004בכל זאת \u0003קתני\u0004 \u0005[ושנה\u0006 אותם\u0005]\u0006 רב אושעיא בנפרד!","ומשיבים: יש מקום לחלוקה נוספת, אף בנזקי אדם בשור: \u0003תני הזיקא\u0004 \u0005[שנה\u0006 במשנה היזק] שנעשה\u0003 בידים\u0004 כלומר על ידי פעולה, \u0003וקתני הזיקא\u0004 \u0005[ושנה\u0006 והוסיף בברייתא סוגים של \u0005היזק]\u0006 שבאים \u0003ממילא\u0004 (מעצמם) שהרי השומרים משלמים גם על נזקים שנגרמו מעצמם, שלא הם עשו אותם בידים. עד כאן לבירור שיטת רב אושעיא.","ועוד יש רשימה אחרת של אבות נזיקין אותה \u0003תני\u0004 \u0005[שנה]\u0006 \u0003ר' חייא\u0004 ובה נמנו \u0003עשרים וארבעה אבות נזיקין,\u0004 והם: \u0003תשלומי כפל\u0004 שמשלם הגנב שלא הודה מעצמו בגניבה, \u0003ותשלומי ארבעה וחמשה\u0004 שמשלם מי שגנב וטבח (או מכר) שור או שה, \u0003וגנב\u0004 המודה מעצמו בגניבה, \u0003ו\u0004כן \u0003גזלן\u0004 (שודד), \u0003ועדים זוממין\u0004 שהעידו באדם עדות שקר, ומשלמים כפי הסכום שניסו לחייב בו את הנאשם,","\u0003והאונס והמפתה,\u0004 שנותנים חמשים סלעים, \u0003ומוציא שם רע\u0004 על אשתו שנבעלה לאחר בהיותה מאורסת, שנותן מאה סלעים, \u0003והמטמא\u0004 תרומה של חבירו ופוסלה על ידי כך מאכילה, \u0003והמדמע\u0004 (המערב תרומה בחולין) ואוסר בכך את הדבר באכילה למי שאינו כהן, \u0003והמנסך\u0004 יין של חבירו לעבודה זרה, ועל ידי כך אוסר את היין בהנאה. \u0003והני תליסר\u0004 \u0005[ואותם שלושה עשר]\u0006 שמנה רב אושעיא — \u0003הא\u0004 \u0005[הרי]\u0006 \u0003עשרים וארבעה\u0004 בסך הכל.","ושואלים: \u0003ור' אושעיא מאי טעמא לא תני הני\u0004 \u0005[מה טעם לא שנה את אלה]?\u0006 ומשיבים: \u0003בממונא\u0004 \u0005[ב\u0006תשלומי \u0005ממון]\u0006 שאדם משלם כפי הממון שהזיק וחיסר מחבירו \u0003קמיירי\u0004 \u0005[הוא עוסק],\u0006 \u0003בקנסא לא קמיירי\u0004 \u0005[ב\u0006תשלומי \u0005קנס אינו עוסק].\u0006","ושואלים: \u0003גנב וגזלן, דממונא\u0004 \u0005[ש\u0006תשלום \u0005ממון]\u0006 \u0003הוא, ליתני\u0004 \u0005[שישנה\u0006 אותם\u0005]\u0006 ר' אושעיא, שהרי אף שם משלם רק מה שנטל בלי תוספת קנס! ומשיבים: \u0003הא תנא ליה\u0004 \u0005[הרי\u0006 כבר \u0005שנה]\u0006 \u0003שומר חנם והשואל,\u0004 ששומר חינם הטוען במרמה שהפקדון נגנב ממנו בעוד שהוא עצמו לקחו — חייב לשלם כגנב. ואם כן, הריהו כגנב לענין זה.","ושואלים: \u0003ור' חייא נמי\u0004 \u0005[גם כן]\u0006 \u0003הא תנא ליה\u0004 \u0005[הרי\u0006 כבר \u0005שנה]\u0006 \u0003שומר חנם והשואל,\u0004 ומדוע שנה גם גנב וגזלן שאין בהם חידוש? ומשיבים: שנה אותם משום חילוק אחר שיש ביניהם: \u0003תני ממונא דאתא לידיה בהיתירא\u0004 \u0005[שנה\u0006 דין \u0005ממון שבא לידו בהיתר]\u0006 שהרי מתחילה בא הממון — הפקדון לידי שומרים אלה בהיתר גמור, אף שאחר כך שלחו בו יד וגנבוהו. \u0003וקתני ממונא דאתא לידיה באיסורא\u0004 \u0005[ושנה\u0006 גם כן ממון שבא לידו באיסור] כגון הגנב והגזלן."],["ועוד שואלים: חיובם של \u0003עדים זוממים דממונא\u0004 \u0005[ש\u0006תשלום \u0005ממון]\u0006 \u0003הוא\u0004 שהרי הם משלמים בדיוק כפי הסכום שזממו לגרום למי שהעידו עליו להוציא, ולא יותר, \u0003ליתני\u0004 \u0005[שישנה]\u0006 גם כן בברייתא של ר' אושעיא, שהרי אין דינו כקנס שהוא תשלום יותר ממה שמזיק בפועל! ומשיבים: \u0003סבר לה\u0004 \u0005[סבור הוא]\u0006 כשיטת \u0003ר' עקיבא\u0004 ש\u0003אמר: אין\u0004 עדים זוממים \u0003משלמין\u0004 ממון \u0003על פי\u0004 הודאת \u0003עצמן\u0004 ששיקרו בעדותם, ומכאן שתשלום זה שמשלמים עדים זוממים הוא מדיני קנסות, שאין אדם משלם קנס על פי הודאת עצמו.","ושואלים: \u0003אי סבר לה\u0004 \u0005[אם סבור הוא\u0006 תנא זה\u0005]\u0006 \u0003כ\u0004שיטת \u0003ר' עקיבא\u0004 אם כן \u0003ליתני תרי גווני\u0004 \u0005[שישנה\u0006 בברייתא שני מיני] \u0003שור\u0004 שר' עקיבא מחלק בדיניהם: \u0003ליתני\u0004 \u0005[שישנה\u0006 דין\u0005]\u0006 \u0003שור דאזיק [שהזיק]\u0004 \u0003שור,\u0004 \u0003וליתני\u0004 \u0005[ושישנה\u0006 דין\u0005]\u0006 \u0003שור דאזיק\u0004 \u0005[שהזיק]\u0006 \u0003אדם,\u0004","\u0003דתנן\u0004 \u0005[ש\u0006כך \u0005שנינו\u0006 במשנה\u0005],\u0006 \u0003ר' עקיבא אומר: אף\u0004 שור \u0003תם שחבל באדם\u0004 וחבל אותו אדם בשור — \u0003משלם\u0004 בעל השור \u0003במותר\u0004 (בעודף הנזק שנגרם לאדם על הנזק שנגרם לשור) \u0003נזק שלם,\u0004 ומכאן ששור שהזיק אדם נחשב כמועד תמיד, ויש לו איפוא דין מיוחד לעצמו!","ומשיבים: מכאן אין להקשות, \u0003הא תבריה\u0004 \u0005[הרי\u0006 כבר שבר] \u0003ר' עקיבא לגזיזיה\u0004 [את אגרופו] כלומר, ר' עקיבא עצמו אינו משווה שור שחבל באדם לשאר מזיקים, \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא], \u0003ר' עקיבא אומר: יכול אף תם שחבל באדם ישלם מן העלייה\u0004 (ממיטב ממונו ולא מגוף המזיק) כשאר אבות נזיקין — \u0003תלמוד לומר\u0004 בשור הנוגח אדם \"כמשפט הזה \u0003יעשה לו\"\u0004 (שמות כא, לא) לומר: \u0003מגופו\u0004 של המזיק \u0003משלם, ואינו משלם מן העלייה\u0004 ואם כן אין מקום למנותו בין אבות הנזיקין שבברייתא, שנאמר עליהם להלן שבכולם משלם ממיטב כספו, ולא מן המזיק.","ועוד מקשים: \u0003האונס והמפתה והמוציא שם רע דממונא\u0004 \u0005[שממון]\u0006 \u0003הוא\u0004 שמשלם, \u0003ליתני\u0004 \u0005[שישנה\u0006 אותם\u0005]\u0006 בברייתא של ר' אושעיא!","ומשיבים: \u0003מה נפשך\u0004 \u0005[רצונך]\u0006 \u0003כלומר, בכל דרך שתרצה, מכל צד שתבין בנושא זה — לא היה מקום לשנות דבר זה, שהרי\u0004 \u0003אי\u0004 \u0005[אם]\u0006 מדובר בחלק ה\u0003נזק\u0004 שמשלם בכל אלה — הלוא כבר \u0003תנא ליה\u0004 \u0005[שנה לו]\u0006 לחוד נזק, \u0003אי\u0004 \u0005[אם]\u0006 \u0003צער\u0004 הוא משלם — \u0003תנא ליה\u0004 \u0005[שנה אותו],\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003בשת\u0004 משלם — \u0003תנא ליה\u0004 \u0005[שנה אותו],\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003פגם\u0004 הוא משלם — \u0003היינו\u0004 \u0005[זהו]\u0006 \u0003נזק\u0004 שהרי תשלום \"פגם\" שמשלם לאנוסה הוא תשלום הנזק שנגרם לה עקב האונס. \u0003מה אית לך למימר\u0004 \u0005[מה יש לך\u0006 עוד לומר] שמשלם האונס והמפתה? \u0003קנסא\u0004 \u0005[קנס],\u0006 אולם כפי שהסברנו \u0003בקנסא לא קמיירי\u0004 \u0005[בקנסות אינו עוסק]\u0006 אלא מונה רק נזקים שיש בהם תשלום ממון בלבד.","ועוד שואלים: \u0003המטמא והמדמע והמנסך, דממונא\u0004 \u0005[שממון]\u0006 \u0003הוא\u0004 שמשלם שהרי משלם רק את התמורה לנזקים שגרם, \u0003ליתני\u0004 \u0005[שישנה]!\u0006","ומשיבים: \u0003מה נפשך\u0004 \u0005[רצונך],\u0006 \u0003אי\u0004 \u0005[אם]\u0006 סבור הוא ש\u0003היזק שאינו ניכר\u0004 ומוחש, כגון אלה שהנזק שבהם אינו נראה לעין, שאף שגרם במעשיו שבכך יפסלו וייאסרו לגמרי, \u0003שמיה\u0004 \u0005[שמו]\u0006 \u0003היזק — הא תנא ליה\u0004 \u0005[הרי שנה]\u0006 \u0003נזק,\u0004 ובכלל זה גם נזק שאינו נראה לעיניים, ואין הבדל בין המטמא לבין השורף. ו\u0003אי\u0004 \u0005[אם]\u0006 סבור הוא כי \u0003היזק שאינו ניכר לא שמיה\u0004 \u0005[לא שמו,\u0006 אינו נחשב\u0005]\u0006 \u0003נזק,\u0004 אם כן מה שמשלם המזיק \u0003הוה ליה קנסא\u0004 \u0005[הרי הוא קנס],\u0006 \u0003ובקנסא לא קמיירי\u0004 \u0005[ובקנס אינו עוסק].\u0006","על סמך הדברים הללו מנסים להציע: \u0003לימא קסבר\u0004 \u0005[האם לומר שסבור]\u0006 \u0003ר' חייא היזק שאינו ניכר — לא שמיה\u0004 \u0005[אין שמו,\u0006 אינו נחשב\u0005]\u0006 \u0003היזק,\u0004 \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003שמיה\u0004 \u0005[שמו,\u0006 נחשב\u0005]\u0006 \u0003היזק — הא תנא ליה\u0004 \u0005[הרי\u0006 כבר \u0005שנה]\u0006 \u0003נזק,\u0004 וכיון שמונה נזק לעצמו וגם אלה לעצמם, משמע שסבור שנזקים כגון אלה שאינם ניכרים באמת אינם כלל נזק! ודוחים: מכאן אין הוכחה, \u0003תנא היזקא דמינכרא\u0004 \u0005[שנה\u0006 לחוד \u0005היזק שניכר]\u0006 \u0003ותנא היזקא דלא מינכרא\u0004 \u0005[ושנה\u0006 לחוד היזק שאינו ניכר] אבל אפשר לומר כי סבור שכל אלה הם נזק ממש, ולא קנס.","ועוד שואלים בהשוואת הנוסח במניינים השונים של אבות הנזיקין. \u0003בשלמא לתנא דידן\u0004 \u0005[נניח לתנא שלנו,\u0006 של משנתנו\u0005]\u0006 \u0003תנא מניינא\u0004 \u0005[שנה מנין]\u0006 (של ארבעה אבות) במשנה, שיש בכך הדגשה \u0003למעוטי\u0004 \u0005[למעט]\u0006 את המנויים בברייתא של \u0003ר' אושעיא,\u0004 ולהדגיש שאין הם בכלל רשימה זו, \u0003ו\u0004אף \u0003ר' אושעיא תנא\u0004 \u0005[שנה]\u0006 בברייתא שלו \u0003מניינא\u0004 \u0005[מנין]\u0006 כדי \u0003למעוטי\u0004 \u0005[למעט]\u0006 אותם שנמנו בברייתא של \u0003ר' חייא\u0004. \u0003אלא מניינא\u0004 \u0005[המניין]\u0006 של \u0003ר' חייא למעוטי מאי\u0004 \u0005[למעט מה\u0006 הוא בא]? די היה לו אם היה רק מפרט את אבות הנזיקין בלא למנות את מספרם!","ומשיבים: אף הוא בא \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003מוסר\u0004 (מלשין), \u0003ומפגל,\u0004 כהן המקריב קרבן של אדם אחר ואומר שיהא לשם קרבן אחר, ועל ידי כך מזיק לבעל הקרבן, שצריך לשוב ולהקריב קרבן אחר. ונזקים אלה אינם כלולים אף במניינו של ר' חייא.","ושואלים: ובאמת מדוע לא חשבם? \u0003וליתני\u0004 \u0005[ושישנה]\u0006 גם את אלה! ומסבירים את השאלה: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003מפגל\u0004 אפשר לומר בתשובה לשאלתנו כי \u0003בקדשים לא קמיירי\u0004 \u0005[אינו עוסק]\u0006 כשדן בהלכות נזיקין, אלא רק בדברי חולין. \u0003אלא מוסר מאי טעמא לא תני\u0004 \u0005[מה טעם לא שנה]?\u0006 ומשיבים: \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003מוסר דדיבורא\u0004 \u0005[שדיבור]\u0006 בלבד הוא שגורם לנזק, \u0003ובדיבורא לא קמיירי\u0004 \u0005[ובדיבור אינו עוסק]\u0006 אלא בנזקים שנגרמו על ידי פעולה ממשית.","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003מוציא שם רע\u0004 \u0003דדיבורא\u0004 \u0005[ש\u0006אף הוא \u0005דיבור]\u0006 \u0003הוא וקתני\u0004 \u0005[ושנה אותו]!\u0006 ומשיבים: \u0003דיבורא דאית ביה\u0004 \u0005[דיבור שיש בו]\u0006 \u0003מעשה הוא,\u0004 שהרי דין מוציא שם רע חל רק במי שנשא אשה ובא עליה ואחר כך מעליל עליה, ונמצא שיש בכך גם צד של מעשה.","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003עדים זוממין דיבורא דלית ביה\u0004 \u0005[דיבור שאין בו]\u0006 \u0003מעשה הוא,\u0004 שהרי אינם אלא מעידים עדות שקר, \u0003וקתני\u0004 \u0005[ושנה\u0006 אותו\u0005]!\u0006 ומשיבים: \u0003התם, אף על גב דלית ביה\u0004 \u0005[שם, אף על פי שאין בו]\u0006 \u0003מעשה,\u0004 \u0003רחמנא קרייה\u0004 \u0005[התורה קראה אותו]\u0006 \u0003מעשה,\u0004 \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"ועשיתם לו כאשר זמם לעשות לאחיו\"\u0004 (דברים יט, יט) משמע שעדות זאת נחשבת לו כנסיון לעשות מעשה.","ועוד בבירור והשוואת השיטות, \u0003בשלמא לתנא דידן\u0004 \u0005[נניח ל\u0006שיטת \u0005התנא שלנו]\u0006 של משנתנו, \u0003תנא\u0004 \u0005[שנה]\u0006 \u0003אבות\u0004 — \u0003מכלל דאיכא\u0004 \u0005[שיש]\u0006 \u0003תולדות\u0004 וצריכות פירוש לעצמן, \u0003אלא לר' חייא ולר' אושעיא,\u0004 הרי אם אומר אתה \u0003אבות — מכלל דאיכא\u0004 \u0005[שיש]\u0006 \u0003תולדות, תולדותיהן מאי ניהו\u0004 \u0005[מה הן],\u0006 שלכאורה מנו את כל סוגי הנזקים, כולם!","\u0003אמר ר' אבהו:\u0004 משמעות הביטוי \"אבות\" כאן אינה לומר שיש להם תולדות, אלא לומר: \u0003כולן,\u0004 כל המנויים ברשימה — דינם \u0003כאבות,\u0004 האמורים במשנתנו, \u0003לשלם ממיטב \u0004שחייב המזיק בכל אלה לשלם מן המיטב שבנכסיו.","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]\u0006 כלומר, כיצד נלמדת הלכה זו? ומשיבים: \u0003אתיא\u0004 \u0005[באה]\u0006 ההלכה על ידי גזירה שווה מן המילים \u0003\"תחת\"\u0004 או \u0003\"נתינה\"\u0004 או \u0003\"ישלם\"\u0004 או \u0003\"כסף\"\u0004 שבכל אחד מסוגי נזיקין אלה כתובה אחת המלים הללו, וממה שמפורש בו למדים על מקומות שנאמרו בהם רק מלים אלה, בדרך גזירה שווה.","שנינו במשנה: \u0003לא הרי השור כהרי המבעה\u0004 וכו'. ושואלים: \u0003מאי קאמר\u0004 \u0005[מה\u0006 הוא אומר] כלומר, מה טעם היה לומר את כל הדיון הזה של \"לא הרי\"? שלכאורה אין למדים ממנו דבר נוסף על הידוע לנו מכבר. \u0003אמר רב זביד משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא: הכי קאמר\u0004 \u0005[כך\u0006 הוא אומר], יש להבין את המשא והמתן כתשובה לשאלה שלא נזכרה במפורש במשנה עצמה, והיא: מדוע הוצרכו כל אבות הנזיקין להיכתב בתורה? \u0003לכתוב רחמנא חדא\u0004 \u0005[שתכתוב התורה\u0006 רק \u0005אחד\u0006 מהם\u0005]\u0006 מן האבות, \u0003ותיתי אידך מיניה\u0004 \u0005[ויבוא,\u0006 יילמד, \u0005האחר ממנו];\u0006 \u0003הדר\u0004 \u0005[חזר]\u0006 ו\u0003אמר\u0004 התנא בתשובה כי \u0003חדא מחדא\u0004 \u0005[אחת מאחת]\u0006 \u0003לא אתיא\u0004 \u0005[באה],\u0006 כלומר אי אפשר ללמוד אב אחד מחבירו, משום שבכל אחד יש צדדים מיוחדים (\"לא הרי... כהרי\"), ומשום שאי אפשר ללמדם זה מזה, הוצרכו להיכתב כולם.","ובהמשך הדברים במשנה נאמר: \u0003ולא זה וזה שיש בהן רוח חיים,\u0004 ושואלים: \u0003מאי קאמר\u0004 \u0005[מה\u0006 הוא אומר], כלומר, מה צורך בהמשך זה של הדיון? \u0003אמר רב משרשיא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא: הכי קאמר\u0004 \u0005[כך\u0006 הוא אומר], אף כאן יש תשובה לשאלה נוספת שלא נתפרשה במשנה, והיא:"],["\u0003לכתוב רחמנא תרתי ותיתי אידך מינייהו\u0004 \u0005[שתכתוב התורה שנים\u0006 מן האבות \u0005ויבואו,\u0006 יילמדו, \u0005האחרים מהם]\u0006 ולא יצטרכו להיכתב כולם. ולכן \u0003הדר\u0004 \u0005[חזר]\u0006 ו\u0003אמר\u0004 במשנה בתשובה לשאלה זו כי \u0003חדא מתרתי לא אתי\u0004 \u0005[אחת משתים אינה באה],\u0006 אינה ניתנת להילמד, כי יש הבדל בין כל שנים מן האבות ובין אב נזיקין נוסף, שיש בו צד להקל.","\u0003אמר רבא\u0004 והעיר על כך: \u0003וכולהו\u0004 \u0005[וכולם],\u0006 כל האבות הללו שבמשנה \u0003כי שדית\u0004 \u0005[כאשר תטיל,\u0006 תצרף\u0005]\u0006 \u0003בור בינייהו\u0004 \u0005[ביניהם],\u0006 כלומר, לבין כל אחד מן האבות האחרים, \u0003אתיא כולהו\u0004 \u0005[יבואו,\u0006 יילמדו, \u0005כולם]\u0006 \u0003ב\u0004דרך הלימוד של \u0003מה הצד.\u0004 \u0003לבר\u0004 \u0005[מחוץ]\u0006 \u0003מ\u0004אב הנזיקין של \u0003קרן,\u0004 שאין ללמוד אותו רק מצירוף שני אבות נזיקין אחרים, ואף לא מבור ואב נוסף, \u0003משום דאיכא למיפרך\u0004 \u0005[שיש\u0006 מקום \u0005להקשות]:\u0006 \u0003מה\u0004 לצד השווה \u0003לכולהו\u0004 \u0005[לכולם]\u0006 — \u0003שכן מועדין\u0004 שדרכם להזיק \u0003מתחילתן.\u0004 ואילו בנזק קרן, מתחילה השור הוא תם, ורק לאחר שהעידו בו שחזר והזיק כמה פעמים נעשה מועד.","\u0003ו\u0004עוד, \u0003למאן דאמר\u0004 \u0005[ול\u0006דעת \u0005מי שאומר]\u0006 כי \u0003אדרבה, קרן עדיפא\u0004 \u0005[עדיפה],\u0006 שהחיוב בתשלום עבורה ברור יותר, אף שאינה מועדת מתחילתה לפי \u0003שכוונתו להזיק,\u0004 אם כן \u0003אפילו קרן נמי אתיא\u0004 \u0005[גם כן באה\u0006 יכולה להילמד\u0005],\u0006 משאר אבות.","ושואלים: \u0003אלא\u0004 אם כן, שיכולה היתה התורה לכתוב רק אב נזיקין אחד ובור, ואת חובת התשלום בשאר אבות הנזיקין אפשר ללמוד מהם בדרך \"מה הצד\", \u0003למאי הלכתא כתבינהו רחמנא\u0004 \u0005[למה\u0006 לצורך איזו \u0005הלכה כתבתם התורה]?\u0006 ומשיבים: הרי זה \u0003להלכותיהן,\u0004 שאף שאינם צריכים להיכתב ללמדנו את עצם חובת התשלום על נזקים אלה, מכל מקום נחוץ הדבר כדי לפרט את ההלכות המיוחדות לכל אב נזיקין, לפי שהלכות אלה שונות בכל אחד מאבות הנזיקין, שבכל אב יש דינים נבדלים:","\u0003קרן\u0004 נכתבה — כדי \u0003לחלק\u0004 בה \u0003בין תמה למועדת.\u0004","\u0003שן ורגל\u0004 נכתבו — כדי \u0003לפוטרן ברשות הרבים.\u0004","\u0003בור\u0004 נכתב — כדי \u0003לפטור בו את הכלים,\u0004 שאין בעל הבור חייב באחריות על כלים שנפלו לבור ונשברו בו. ושואלים: \u0003ול\u0004שיטת \u0003ר' יהודה\u0004 ש\u0003מחייב\u0004 אף \u0003על נזקי כלים בבור,\u0004 מדוע נכתב דין בור? ומשיבים: \u0003לפטור בו את האדם,\u0004 שאף ר' יהודה מודה שאין בעל הבור חייב בתשלומים על מות אדם שנפל לבור, שכן אדם יכול להיזהר, ולכן נכתב אב נזיקין זה לעצמו.","ומדוע נכתב אב הנזיקין \u0003אדם\u0004 (שהוא לדעת רב \"מבעה\" שבמשנה) — כדי \u0003לחייבו בארבעה דברים\u0004 נוסף לתשלום עצם הנזק, והם: צער, ריפוי, בושת, ושבת.","ו\u0003אש\u0004 נכתבה כי יש בה הלכה מיוחדת — \u0003לפטור בו את הטמון.\u0004 שלדעת רוב החכמים, אם היה דבר טמון בתוך הקמה (או שאר דברים שנשרפו), באופן שאין מקום להניח שהוא מצוי שם, אם כילתה אותו האש — אין המזיק חייב לשלם. ושואלים: \u0003ול\u0004דעת \u0003ר' יהודה\u0004 ש\u0003מחייב\u0004 אף \u0003על נזקי טמון באש,\u0004 \u0003לאתויי מאי\u0004 \u0005[להביא,\u0006 להוסיף את \u0005מה]\u0006 את איזו הלכה מיוחדת, נתפרט אב נזיקין זה?"],["ומשיבים: \u0003לאתויי\u0004 \u0005[להביא,\u0006 להוסיף\u0005]\u0006 שחייב על אש גם אם \u0003ליחכה\u0004 (חרכה) את \u0003נירו\u0004 (שדהו החרוש) של חבירו, \u0003ו\u0004כן אם \u0003סכסכה\u0004 (הבהבה) את \u0003אבניו,\u0004 שאף שאין זה נזק המכלה את גוף הדברים, מכל מקום חייב לשלם גם עבור נזק זה.","שנינו במשנה כי \u0003הצד השוה שבהן\u0004 שדרכן לילך ולהזיק וכו'. ושואלים \u0003לאתויי מאי\u0004 \u0005[להביא,\u0006 להוסיף את \u0005מה],\u0006 כלומר, אלו דברים נוספים למדים על ידי צד שווה זה? \u0003אמר אביי: לאתויי\u0004 \u0005[להביא]\u0006 \u0003אבנו\u0004 או \u0003סכינו\u0004 או \u0003משאו, שהניחן בראש גגו, ונפלו\u0004 על ידי \u0003רוח מצויה, והזיקו\u0004 שאף על אלה חייב\u0003.\u0004","ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אי בהדי דקא אזלי קא מזקי\u0004 \u0005[אם בזמן שהולכים,\u0006 נופלים, \u0005הם\u0006 \u0005מזיקים]\u0006 \u0003היינו\u0004 \u0005[הרי זה]\u0006 ממש נזק \u0003אש,\u0004 כי","\u0003מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה\u0006 במה מוגדר\u0005]\u0006 נזק \u0003אש\u0004 — שהוא דבר ש\u0003כח אחר\u0004 (רוח) \u0003מעורב בו, ו\u0004הוא עצמו \u0003ממונך, ושמירתו\u0004 מוטלת \u0003עליך.\u0004 ואולם \u0003הני\u0004 \u0005[אלה],\u0006 אבנו וסכינו ומשאו, \u0003נמי\u0004 \u0005[גם כן]\u0006 נכללים באותה הגדרה, שכן \u0003כח אחר מעורב בהן\u0004 (שנפלו מחמת הרוח), \u0003ו\u0004הם \u0003ממונך, ושמירתן\u0004 מוטלת \u0003עליך!\u0004","\u0003ואלא\u0004 יש לומר שנפלו אלה מן הגג תחילה, ו\u0003בתר דנייחי\u0004 \u0005[אחר שנחו]\u0006 על הקרקע ניזוק בהם אדם. ושוב נברר כיצד בדיוק היה הדבר: \u0003אי דאפקרינהו\u0004 \u0005[אם שהפקיר אותם]\u0006 לאחר שנפלו, אם כן \u0003בין לרב בין לשמואל היינו\u0004 \u0005[הרי\u0006 נזק \u0005זה]\u0006 קרוי \u0003בור,\u0004 כי","\u0003מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה\u0006 במה מוגדר\u0005]\u0006 \u0003בור\u0004 — \u0003שכן תחילת עשייתו לנזק, וממונך, ושמירתן\u0004 מוטלת \u0003עליך! הני\u0004 \u0005[אלה],\u0006 אבנו וסכינו ומשאו, \u0003נמי\u0004 \u0005[גם כן]\u0006 נכללים באותה הגדרה, שכן \u0003תחילת עשייתן לנזק\u0004 שכיון שהניחם בראש הגג מסתבר שיפלו ויזיקו, \u0003ו\u0004הם \u0003ממונך, ושמירתן עליך!\u0004","\u0003אלא\u0004 צריך לומר שמדובר באופן ש\u0003לא אפקרינהו\u0004 \u0005[הפקירם]\u0006 ועדיין הוא שומר את בעלותו עליהם. ומעתה, \u0003ל\u0004דעת \u0003שמואל\u0004 ש\u0003אמר\u0004 שכל התקלות \u0003כולם\u0004 \u0003מבורו למדנו\u0004 — אם כן \u0003היינו\u0004 \u0005[הרי זה]\u0006 אב הנזיקין של \u0003בור,\u0004 ועדיין יש לשאול: מה נוסף ב\"צד השווה\" שבמשנתנו?","ומשיבים: \u0003לעולם\u0004 תאמר \u0003דאפקרינהו\u0004 \u0005[שהפקיר אותם]\u0006 לאחר שנפלו על הקרקע, והזיקו. ומכל מקום לא ניתן ללומדם אלא ב\"צד השווה\", משום \u0003דלא דמו\u0004 \u0005[שאינם דומים]\u0006 לגמרי \u0003לבור,\u0004 כי \u0003מה לבור שכן אין כח אחר מעורב בו,\u0004 אלא הנזק נגרם על ידי הבור עצמו, \u0003תאמר בהני\u0004 \u0005[באלה]\u0006 \u0003שכח אחר מעורב בהן,\u0004 שלולא הרוח שהביאה את הדברים לאותו מקום לא היה קורה דבר אחרי כן.","ואם כן צריכים אנו לומר כי \u0003אש תוכיח\u0004 שכח אחר מעורב בה, וחייב בנזקיה.","אלא שמצד שני יש להקשות: \u0003מה לאש שכן דרכו לילך ולהזיק,\u0004 מה שאין כן באבנו וסכינו שאינם הולכים ומזיקים — ועל כן אפשר לענות כי","\u0003בור תוכיח\u0004 שאין דרכו לילך ולהזיק וחייב עליו. אולם על דימוי זה לנזק בור אפשר לשוב ולהקשות כפי שכבר הקשינו, שאין הדבר דומה לגמרי לבור, \u0003וחזר הדין,\u0004 כלומר, אנו חוזרים שוב לדיון הראשון, ולכן צריך ללמוד הלכה זו משני הדינים יחד בצד השווה שהביאה המשנה.","\u0003רבא אמר:\u0004 \"הצד השווה\" שבמשנה בא \u0003לאתויי\u0004 \u0005[להביא]\u0006 אופן נזק אחר, והוא \u0003בור המתגלגל ברגלי אדם וברגלי בהמה,\u0004 כלומר, דבר תקלה שהניח אדם, ולא הזיק במקומו, אלא שנתגלגל ברגלי אדם ובהמה ממקום למקום, ושם גרם לנזק.","ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אי דאפקרינהו\u0004 \u0005[אם שהפקירם]\u0006 את החפצים שגרמו לתקלה, אם כן, \u0003בין ל\u0004דעת \u0003רב בין ל\u0004דעת \u0003שמואל היינו\u0004 \u0005[הרי זה]\u0006 \u0003בור,\u0004 כי","\u0003מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה,\u0006 במה מיוחד ומוגדר\u0005]\u0006 \u0003בור\u0004 — \u0003שכן תחילת עשייתו לנזק, ושמירתו עליך\u0004 — \u0003הני נמי\u0004 \u0005[אלה גם כן]\u0006 \u0003תחילת עשייתן לנזק, ושמירתן עליך!\u0004","\u0003אלא\u0004 תאמר כי מדובר באופן ש\u0003לא אפקרינהו\u0004 \u0005[הפקירם] —\u0006 אם כן \u0003לשמואל\u0004 ש\u0003אמר כולם מבורו למדנו היינו\u0004 \u0005[הרי זה]\u0006 \u0003בור!\u0004","ומשיבים: \u0003לעולם\u0004 יש לומר \u0003דאפקרינהו\u0004 \u0005[שהפקירם],\u0006 \u0003ו\u0004בכל זאת יש ללומדם ב\"צד השווה\" משום שאין הם בכלל בור, שכן \u0003לא דמי\u0004 \u0005[אינו דומה]\u0006 \u0003לבור;\u0004 \u0003מה לבור שכן מעשיו\u0004 של החופר בלבד \u0003גרמו לו\u0004 שיזיק, \u0003תאמר בהני\u0004 \u0005[באלה]\u0006 בבור המתגלגל \u0003שאין מעשיו גרמו לו,\u0004 שהרי הבור (התקלה) לא הזיק במקום שבו הניחו, אלא במקום אליו גילגלוהו אחרים, אנשים או בהמות.","ואם כן יש לומר כי \u0003שור יוכיח,\u0004 שהרי אף נזק השור נעשה מכח השור ולא מכח בעליו וחייב לשלם.","ויש לדחות: \u0003מה לשור\u0004 — \u0003שכן דרכו לילך ולהזיק,\u0004 מה שאין כן תקלה שאינה הולכת מעצמה ומזיקה — \u0003בור תוכיח\u0004 שאין הולך ומזיק וחייב בתשלומים.","\u0003וחזר הדין,\u0004 כלומר, אנו שבים לנקודה הראשונה, \u0003לא ראי זה כראי זה\u0004 אין דומה בור לשור, ומן הצד השווה שבמשנה למדים שאף בור המתגלגל הוא בכלל נזיקין.","\u0003רב אדא בר אהבה אמר:\u0004 \"הצד השווה\" במשנה בא \u0003לאתויי\u0004 \u0005[להביא]\u0006 \u0003הא דתניא\u0004 \u0005[זו ששנינו]:\u0006 \u0003כל אלו\u0004 המקרים \u0003שאמרו\u0004 חכמים, והם: אנשים ה\u0003פותקין\u0004 (פותחים) את \u0003ביבותיהן\u0004 (ביבים של שופכין) לרשות הרבים, או \u0003גורפין\u0004 החוצה אל רשות הרבים את \u0003מערותיהן\u0004 שכינסו בהן מים סרוחים, ש\u0003בימות החמה אין להם רשות\u0004 לעשות זאת, לפי שהם הופכים להיות תקלה ברשות הרבים, ו\u0003בימות הגשמים\u0004 שיש בין כה וכה מים ובוץ ברשות הרבים — \u0003יש להם רשות.\u0004 ו\u0003אף על פי ש\u0004בימות הגשמים \u0003ברשות\u0004 הם עושים, \u0003אם הזיקו\u0004 על ידי מים אלה — \u0003חייבים לשלם.\u0004","ונברר, \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אי בהדי דקאזלי מזקי\u0004 \u0005[אם בזמן שהם הולכים,\u0006 כששפך אותם, הם \u0005מזיקים]\u0006 אם כן \u0003כחו הוא,\u0004 והרי זה \"מבעה\" המפורש במשנה לדעת רב, ולדעת שמואל הוא מפורש במשנה הבאה, ואין זה בכלל הנלמד מ\"הצד השווה\".","\u0003אלא\u0004 יש לומר שהיה זה \u0003בתר דנייח\u0004 \u0005[לאחר שנחו]\u0006 במקום. ונברר \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אי דאפקרינהו\u0004 \u0005[אם שהפקיר אותם],\u0006 אם כן \u0003בין ל\u0004שיטת \u0003רב בין ל\u0004שיטת \u0003שמואל היינו\u0004 \u0005[הרי זה]\u0006 \u0003בור,\u0004 כי \u0003מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה]\u0006 \u0003בור\u0004 — שכן \u0003תחילת עשייתו לנזק, וממונך, ושמירתו עליך, הני נמי\u0004 \u0005[אלה לגם כן],\u0006 השופכין — \u0003תחילת עשייתן לנזק, וממונך, ושמירתן עליך!\u0004","\u0003אלא\u0004 תאמר ש\u0003לא אפקרינהו\u0004 \u0005[הפקירם].\u0006 אם כן, \u0003לשמואל\u0004 ש\u0003אמר כולם מבורו למדנו\u0004 — \u0003היינו\u0004 \u0005[הרי זה]\u0006 \u0003בור!\u0004","ומשיבים: \u0003לעולם\u0004 תפרש \u0003דאפקרינהו\u0004 \u0005[שהפקירם],\u0006 ובכל זאת אין הם בכלל בור וצריך ללומדם ב\"צד השווה\", שכן \u0003ולא דמי\u0004 \u0005[ואינו דומה]\u0006 \u0003לבור,\u0004 כי \u0003מה לבור שכן\u0004 עשאו ברשות הרבים \u0003שלא ברשות, תאמר בהני\u0004 \u0005[באלה]\u0006 ש\u0003ברשות\u0004 עשה אותם,"],["\u0003שור יוכיח\u0004 שברשות הוא מהלך ברשות הרבים, ובכל זאת חייבים על נזקיו.","ויש לטעון כנגד זה: \u0003מה לשור שכן דרכו לילך ולהזיק.\u0004","ויש להשיב: \u0003בור תוכיח\u0004 שאינו מהלך ומזיק, וחייב על מה שהזיק. \u0003וחזר הדין,\u0004 ומן הצד השווה שבשניהם, והוא האמור במשנה, למדנו שחייב על אופן נזק זה.","\u0003רבינא אמר:\u0004 הצד השווה שבמשנתנו בא ללמדנו אופן נזק אחר, והוא \u0003לאתויי\u0004 \u0005[להביא]\u0006 \u0003הא דתנן\u0004 \u0005[זו ששנינו\u0006 במשנה אחרת\u0005]:\u0006 \u0003הכותל והאילן שנפלו לרשות הרבים\u0004 מעצמם, \u0003והזיקו\u0004 — \u0003פטור\u0004 בעליהם \u0003מלשלם,\u0004 לפי שהוא אנוס. ואולם אם קודם לכן \u0003נתנו לו\u0004 בית דין \u0003זמן לקוץ\u0004 (לקצוץ) \u0003האילן\u0004 או \u0003לסתור\u0004 את \u0003הכותל\u0004 משום שראו שיש בהם סכנה, והוא לא עשה כן, אם \u0003נפלו\u0004 \u0003בתוך הזמן\u0004 הקצוב \u0003והזיקו\u0004 — \u0003פטור,\u0004 ואם נפלו \u0003לאחר הזמן\u0004 הקצוב והזיקו — \u0003חייב.\u0004","ונברר, \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אי דאפקרה\u0004 \u0005[אם שהפקירו\u0006 את הדבר שהזיק\u0005],\u0006 \u0003בין ל\u0004שיטת \u0003רב בין ל\u0004שיטת \u0003שמואל היינו\u0004 \u0005[הרי זה]\u0006 \u0003בור,\u0004 כי \u0003מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה,\u0006 מיוחד ומוגדר\u0005]\u0006 \u0003בור\u0004 — ש\u0003הזיקו מצוי, ושמירתו עליך\u0004 — \u0003הני נמי\u0004 \u0005[אלה גם כן]\u0006 \u0003הזיקן מצוי, ושמירתן עליך.\u0004","\u0003אי\u0004 \u0005[אם]\u0006 ש\u0003לא אפקרינהו\u0004 \u0005[הפקירם],\u0006 \u0003ל\u0004דעת \u0003שמואל\u0004 ש\u0003אמר: כולם,\u0004 כל מיני תקלה, \u0003מבורו למדנו\u0004 — \u0003היינו\u0004 \u0005[הרי זה]\u0006 \u0003בור!\u0004","ומשיבים: \u0003לעולם\u0004 יש לומר \u0003דאפקרינהו\u0004 \u0005[שהפקירם]\u0006 \u0003ו\u0004בכל זאת \u0003לא דמי\u0004 \u0005[אינו דומה]\u0006 \u0003לבור,\u0004 כי יש לחלק: \u0003מה לבור שכן תחילת עשייתו לנזק,\u0004 שהרי מתחילתו כשנחפר יש בו סכנה, \u0003תאמר בהני\u0004 \u0005[באלה]\u0006 \u0003שאין תחילת עשייתן לנזק,\u0004 שכן כשעמדו במקומם לא היו מתחילה עשויים לנזקין.","לכך יש לומר: \u0003שור יוכיח\u0004 שאף הוא אין תחילתו לנזק, וחייב על נזקיו.","ואולם גם השוואה זו יש לדחות: \u0003מה לשור\u0004 — \u0003שכן דרכו לילך ולהזיק,\u0004 מה שאין כן העץ והכותל שנפלו שאין דרכם בכך.","לכך נאמר: \u0003בור תוכיח\u0004 שאינו הולך ומזיק ובכל זאת חייב בתשלומי הנזק. \u0003ו\u0004הרי \u0003חזר הדין\u0004 ולמדים מן \"הצד השווה\" שבמשנה.","שנינו במשנה ש\u0003כשהזיק חב המזיק.\u0004 ותוהים על לשון זו: מדוע אמר \u0003\"חב המזיק\"? \"חייב המזיק\" מיבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005],\u0006 שכך היא הלשון המתוקנת! \u0003אמר רב יהודה אמר רב: האי תנא\u0004 \u0005[תנא זה]\u0006 ששנה את משנתנו \u0003ירושלמי הוא, דתני לישנא קלילא\u0004 \u0005[ששנה\u0006 ב\u0005לשון קלה],\u0006 שכך היו מדברים בירושלים בלשון קצרה.","שנינו במשנה שהמזיק חייב \u0003לשלם תשלומי נזק\u0004 במיטב. ביטוי זה דורש ביאור, ולכך מביאים את מה ש\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: נאמר בתשלומי נזיקין \u0003\"מיטב שדהו ומיטב כרמו ישלם\"\u0004 (שמות כב, ד), ונחלקו תנאים בפירוש הדברים; \u0003מיטב שדהו\u0004 — \u0003של ניזק, ומיטב כרמו\u0004 — \u0003של ניזק,\u0004 אלו \u0003דברי ר' ישמעאל.\u0004 כלומר, המזיק משלם לפי ערכו של הטוב שבנכסיו של הניזק, אף שמה שהזיק היה פחות בערכו.","\u0003ר' עקיבא אומר:\u0004 אינו כן, שלדעתו מעריכים את הנזק לפי מה שהזיק, ו\u0003לא בא הכתוב\u0004 (\"מיטב\") \u0003אלא לגבות לנזקין מן העידית,\u0004 שאם משלם המזיק לא בכסף אלא בקרקע — אינו משלם מפחותה שבקרקעותיו, אלא מן העידית = המובחרת שבהן, \u0003וקל וחומר להקדש.\u0004 ומבררים תחילה את דברי ר' ישמעאל שבכל מקרה משלם המזיק לפי הטוב שבנכסי הניזק.","\u0003ור' ישמעאל,\u0004 אף שמובן לשיטתו כי כאשר \u0003אכל\u0004 המזיק ערוגה \u0003שמינה\u0004 (משובחת) \u0003משלם שמינה,\u0004 וכי ניתן לומר שגם אם \u0003אכל כחושה\u0004 (גרועה) \u0003משלם שמינה?\u0004 הלא אין צדק בדבר!","\u0003אמר רב אידי בר אבין: הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003כגון שאכל\u0004 המזיק \u0003ערוגה בין הערוגות,\u0004 \u0003ולא ידעינן\u0004 \u0005[ואין אנו יודעים]\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003כחושה אכל, אי\u0004 \u0005[אם]\u0006 \u0003שמינה אכל,\u0004 וגזרה התורה שבמקרה כזה \u0003ישלם שמינה.\u0004","\u0003אמר רבא:\u0004 אין דבר זה מתקבל על הדעת, שכן \u0003ומה\u0004 \u0003אילו ידעינן\u0004 \u0005[היינו\u0006 \u0005יודעים]\u0006 בבירור ש\u0003כחושה אכל,\u0004 הרי ודאי \u0003לא\u0004 \u0003משלם אלא כחושה, השתא דלא ידעינן\u0004 \u0005[עכשיו שאין אנו יודעים]\u0006 בבירור אם \u0003כחושה אכל או שמינה אכל, משלם שמינה?!\u0004 הלא כלל הוא בידינו: \u0003המוציא מחבירו עליו הראיה,\u0004 ואם הניזק רוצה להוציא מן המזיק דמי ערוגה שמינה, הרי עליו מוטלת חובת ההוכחה שאכן ערוגה כזו הזיקה פרתו, ומדוע ישלם המזיק בכל מקרה דווקא מן העידית?","\u0003אלא\u0004 יש לדחות הבנה זו בדברי ר' ישמעאל ולומר הסבר אחר. \u0003אמר רב אחא בר יעקב: הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003כגון שהיתה עידית\u0004 של ה\u0003ניזק\u0004 גרועה, והיתה שווה כמו ה\u0003זיבורית\u0004 של ה\u0003מזיק,\u0004 ויש למזיק גם עידית.","\u0003ובהא פליגי\u0004 \u0005[וב\u0006ענין \u0005זה נחלקו],\u0006 \u0003ר' ישמעאל סבר\u0004 \u0005[סבור]:\u0006 \u0003ב\u0004של ה\u0003ניזק שיימינן\u0004 \u0005[אנו שמים,\u0006 מעריכים\u0005]\u0006 ונותן לו המזיק את סכום הנזק המדוייק מקרקע טובה כמו העידית של הניזק (שהוא זיבורית של המזיק). \u0003ור' עקיבא סבר\u0004 \u0005[סבור]:\u0006 \u0003ב\u0004של ה\u0003מזיק שיימינן\u0004 \u0005[אנו שמים,\u0006 מעריכים\u0005],\u0006 שגזרה התורה שצריך לשלם לו ממיטב שדהו שלו.","ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' ישמעאל?\u0004 שהוא מפרש כך: \u0003נאמר \"שדה\" למטה\u0004 (בסוף הפסוק) \"מיטב שדהו ישלם\" \u0003ונאמר \"שדה\" למעלה\u0004 (בתחילת הפסוק) \"וביער בשדה אחר\", ללמוד זה מזה: \u0003מה שדה האמור למעלה\u0004 מדובר בשדה של ה\u0003ניזק, אף שדה האמור למטה\u0004 לענין תשלומים כוונתו מיטב של ה\u0003ניזק.\u0004","\u0003ור' עקיבא\u0004 סבור כי המשמעות הפשוטה של הכתוב \u0003\"מיטב שדהו ומיטב כרמו ישלם\"\u0004 כוונתה: \u0003דהאיך דקא משלם\u0004 \u0005[של זה שמשלם]\u0006 כלומר, המזיק, ולא של הניזק.","ושואלים: \u0003ור' ישמעאל\u0004 מה הוא משיב על כך, וכי אין זו משמעותו הפשוטה של הכתוב? ומסבירים: \u0003אהני\u0004 \u0005[הועילה]\u0006 \u0003גזרה שוה ואהני קרא\u0004 \u0005[והועיל הכתוב\u0006 המפורש\u0005]\u0006 ואנו למדים משניהם. כיצד, \u0003אהני\u0004 \u0005[הועילה]\u0006 \u0003גזרה שוה\u0004 — \u0003כדקאמינא\u0004 \u0005[כפי שאמרנו]\u0006 ללמדנו שמשלמים מקרקע השווה בטיבה לעידית של הניזק.","\u0003ואהני קרא\u0004 \u0005[והועיל הכתוב]\u0006 \u0003כגון\u0004 במקרה \u0003דאית ליה\u0004 \u0005[שיש לו]\u0006 \u0003למזיק\u0004 גם \u0003עידית ו\u0004גם \u0003זיבורית, ו\u0004יש \u0003עידית\u0004 בלבד \u0003לניזק, וזיבורית\u0004 של \u0003מזיק לא שויא\u0004 \u0005[שווה]\u0006 \u0003כעידית\u0004 של ה\u0003ניזק,\u0004 שבאופן כזה \u0003משלם ליה\u0004 \u0005[לו]\u0006 המזיק \u0003ממיטב דידיה\u0004 \u0005[שלו],\u0006","\u0003דלא מצי אמר ליה\u0004 \u0005[שאינו יכול לומר לו]:\u0006 \u0003תא את גבי\u0004 \u0005[בוא אתה\u0006 ו\u0005גבה]\u0006 \u0003מזיבורית\u0004 וגם אם העידית שלו שווה יותר מן העידית של ניזק, \u0003אלא גבי\u0004 \u0005[גובה]\u0006 הניזק \u0003ממיטב\u0004 נכסי המזיק.","שנינו בברייתא ש\u0003ר' עקיבא אומר: לא בא הכתוב אלא לגבות לניזקין מן העידית, וקל וחומר להקדש.\u0004 על ביטוי אחרון זה תוהים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"קל וחומר להקדש\"\u0004 ובאיזה מקרה מדובר כאן:","\u0003אילימא\u0004 \u0005[אם תאמר]\u0006 במקרה \u0003דנגח תורא דידן\u0004 \u0005[שנוגח שור שלנו,\u0006 של ישראל\u0005]\u0006 \u0003לתורא\u0004 \u0005[לשור]\u0006 של \u0003הקדש,\u0004 הרי \u0003\"\u0004וכי יגוף שור איש את \u0003שור רעהו\"\u0004 (שמות כא, לה) \u0003אמר רחמנא\u0004 \u0005[אמרה התורה],\u0006 ומכאן נלמד כי הלכות אלו של תשלומי נזיקין נוגעות לשור רעהו דווקא, \u0003ולא\u0004 ל\u0003שור של הקדש,\u0004 ואין צורך לקל וחומר לענין זה!","\u0003אלא\u0004 תאמר כי יש להבין זאת לא לענין נזיקין, כי אם \u0003לאומר \"הרי עלי מנה\u0004 (מאה דינרים) \u0003לבדק הבית\"\u0004 ונותן מנה זה מן הקרקע, שבא קל וחומר זה לומר \u0003דאתי\u0004 \u0005[שבא]\u0006 ה\u0003גזבר ושקיל\u0004 \u0005[ולוקח]\u0006 \u0003מעידית\u0004 שבנכסי המקדיש.","על כך יש להקשות: \u0003לא יהא\u0004 הגזבר \u0003אלא בעל חוב\u0004 סתם, הגובה חובו מנכסי הלווה,"],["\u0003ו\u0004הרי \u0003בעל חוב\u0004 גובה \u0003בבינונית\u0004 ולא בעידית!","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 ש\u0003סבר\u0004 \u0005[סבור]\u0006 \u0003ר' עקיבא\u0004 כי כל \u0003בעל חוב נמי\u0004 \u0005[גם כן]\u0006 \u0003בעידית\u0004 הוא גובה, בכל זאת \u0003איכא למיפרך\u0004 \u0005[יש\u0006 מקום \u0005לפרוך]\u0006 ולהוכיח שאין כח ההקדש יפה בזה ככח בעל חוב סתם, כי \u0003מה לבעל חוב שכן יפה כחו בנזקין,\u0004 שהרי הדיוט שניזק מקבל עבור נזקו מעידית, \u0003תאמר בהקדש שהורע כחו בנזקין,\u0004 שהרי אמרנו שאין ההקדש שניזוק מקבל כל תשלום! ואם כן לא ניתן להעמיד את מחלוקת ר' עקיבא ור' ישמעאל במי שנתחייב כסף להקדש.","אלא, \u0003לעולם\u0004 כך תפרש את מחלוקתם, במקרה ש\u0003נגח תורא דידן\u0004 \u0005[שור שלנו]\u0006 \u0003לתורא\u0004 \u0005[לשור]\u0006 של \u0003הקדש,\u0004 ובזה אמר ר' עקיבא: קל וחומר להקדש שיגבה מן העידית של המזיק. \u0003ודקא קשיא\u0004 \u0005[ו\u0006זה \u0005שקשה]\u0006 \u0003לך\u0004 מה שדרשו חכמים: \u0003\"שור רעהו\" אמר רחמנא\u0004 \u0005[אמרה התורה]\u0006 ומכאן יש לדייק: \u0003ולא שור של הקדש\u0004 שאינו משלם כלל תשלומי נזיקין להקדש — אין הכל מפרשים כך את הדברים, ואפשר לומר כי \u0003ר' עקיבא סבר לה\u0004 \u0005[סבור\u0006 בענין \u0005זה]\u0006 \u0003כ\u0004שיטת \u0003ר' שמעון בן מנסיא,\u0004","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' שמעון בן מנסיא אומר: שור של הקדש שנגח שור של הדיוט\u0004 הרי ההקדש \u0003פטור,\u0004 ואילו \u0003שור של הדיוט שנגח שור של הקדש, בין\u0004 שהנוגח היה שור \u0003תם בין\u0004 שהנוגח היה שור \u0003מועד\u0004 — \u0003משלם נזק שלם.\u0004","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 אתה מפרש את שיטת ר' עקיבא, אם כן, \u0003ר' ישמעאל ור' עקיבא ממאי\u0004 \u0005[ממה,\u0006 מניין\u0005]\u0006 יודע אתה ש\u0003בעידית\u0004 של \u0003ניזק וזיבורית\u0004 של \u0003מזיק פליגי\u0004 \u0005[חלוקים\u0006 הם\u0005]?\u0006 \u0003דלמא\u0004 \u0005[שמא]\u0006 נפרש את מחלוקתם באופן אחר, \u0003דכולי עלמא\u0004 \u0005[שלדעת הכל]\u0006 \u0003ב\u0004נכסי ה\u0003ניזק שיימינן\u0004 \u0005[אנו שמים,\u0006 מעריכים\u0005],\u0006 \u0003והכא\u0004 \u0005[וכאן]\u0006 \u0003בפלוגתא\u0004 \u0005[במחלוקת]\u0006 של \u0003ר' שמעון בן מנסיא ורבנן\u0004 \u0005[וחכמים]\u0006 \u0003קמפלגי\u0004 \u0005[חלוקים\u0006 הם\u0005],\u0006 ובאופן זה:","\u0003ר' עקיבא סבר\u0004 \u0005[סבור]\u0006 \u0003כ\u0004שיטת \u0003ר' שמעון בן מנסיא,\u0004 שהמזיק את ההקדש משלם עבור כל הנזק, וזהו \"קל וחומר להקדש\", \u0003ור' ישמעאל סבר כרבנן\u0004 \u0005[סבור כחכמים]\u0006 שאין הקדש שהוזק בכלל נזקי שור!","ודוחים: \u0003אם כן\u0004 אתה מפרש, \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 הביטוי \u0003\"לא בא הכתוב\u0004 אלא לגבות לנזקין מן העידית","\u0003\"\u0004שאינו שייך לבעיה זו. \u0003ועוד, מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 הביטוי \u0003\"קל וחומר להקדש\"\u0004 שאמר ר' עקיבא, והרי לשיטתו אין דין הקדש כדין הדיוט!","\u0003ועוד, הא\u0004 \u0005[הרי]\u0006 \u0003אמר רב אשי, תניא בהדיא\u0004 \u0005[שנויה\u0006 ברייתא \u0005במפורש]\u0006 ומסבירה את מחלוקתם: \u0003מיטב שדהו ומיטב כרמו\u0004 \u0005(שמות כב, ד)\u0006, \u0003מיטב שדהו של ניזק, ומיטב כרמו של ניזק,\u0004 אלו \u0003דברי ר' ישמעאל, ר' עקיבא אומר: מיטב שדהו של מזיק, ומיטב כרמו של מזיק.\u0004 ואם כן מפורש שבזה היתה המחלוקת.","כיון שהזכרנו את הכתוב בענין תשלומי נזקים, דנים בנושא זה מצד אחר. \u0003רמי ליה\u0004 \u0005[השליך לו,\u0006 הראה סתירה\u0005]\u0006 \u0003אביי לרבא: כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"מיטב שדהו ומיטב כרמו ישלם\"\u0004 (שמות כב, ד) משמע: \u0003מיטב\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003מידי אחרינא\u0004 \u0005[דבר אחר]\u0006 — \u0003לא\u0004 יתן,","\u0003והתניא\u0004 \u0005[והרי\u0006 מצד אחר \u0005שנויה\u0006 ברייתא\u0005]:\u0006 נאמר \"בעל הבור ישלם כסף ישיב לבעליו\" (שמות כא, לד), וכיון שנאמר \"ישלם\" הרי המלה \"ישיב\" מיותרת ומה באה ללמדנו? אלא \u0003\"ישיב\"\u0004 בא \u0003לרבות\u0004 תשלום הנזק בכל דבר שהוא \u0003שוה כסף ואפילו סובין\u0004 (פסולת התבואה לאחר טחינתה) שהם כשלעצמם פחותי ערך!","ותירץ לו רבא: \u0003לא קשיא\u0004 \u0005[אינו קשה],\u0006 \u0003כאן\u0004 בברייתא שלמדנו שיכול להחזיר לו כל דבר — הרי זה כאשר המזיק משלם מרצונו ו\u0003מדעתו,\u0004 שבא מעצמו לפצות את הניזק, ואז יכול הוא לשלם בכל דבר. \u0003כאן בעל כרחו,\u0004 לאחר שהוגשה תביעה בפני בית דין, שכיון שהטריחו המזיק לניזק — מכריחים את המזיק שישלם לו ממיטב.","\u0003אמר עולא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב עילאי: דיקא נמי\u0004 \u0005[מדוייק גם כן]\u0006 הדבר בלשון הכתוב, \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"\u0004מיטב שדהו... \u0003ישלם\"\u0004 ולא נאמר \"ישיב\", משמע \u0003בעל כרחו,\u0004 שחייבוהו בכך.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי:\u0004 דיוק זה אינו מוכיח, כי \u0003מי כתיב\u0004 \u0005[האם נאמר]\u0006 \u0003\"ישולם\"\u0004 ומשמע: בלי קשר לרצונו של המשלם? \u0003\"ישלם\" כתיב\u0004 \u0005[נאמר],\u0006 וזה — אף \u0003מדעתו משמע\u0004 וללמדנו שאף כשבא המזיק לשלם מרצונו אין הוא משלם אלא ממיטב, ולא תורצה איפוא הסתירה.","\u0003אלא אמר אביי:\u0004 יש לפרש זאת \u0003כדמר\u0004 \u0005[כפי ש\u0006אמר \u0005אדוני,\u0006 רבי\u0005]\u0006 (החכם רבה) בענין אחר. \u0003דתניא\u0004 \u0005[ששנינו בברייתא]\u0006: \u0003הרי שהיו לו\u0004 לאדם \u0003בתים שדות וכרמים,\u0004 והרי הוא אמנם עשיר \u0003ו\u0004אולם \u0003אינו מוצא\u0004 אפשרות \u0003למוכרן\u0004 בשוויין, ולפי שעה אין לו מה לאכול — הרי \u0003מאכילין אותו מעשר עני עד מחצה\u0004 עד שווי מחצית רכושו, שהרי בשעה זו עני הוא.","\u0003והוי בה מר\u0004 \u0005[והיה מתקשה בה אדוני\u0006 בבעיה זו\u0005]:\u0006 \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אי הוזל ארעתא דכולי עלמא ודידיה נמי זל בהדייהו\u0004 \u0005[אם הוזלו הקרקעות של הכל, ו\u0006קרקעותיו \u0005שלו גם כן הוזלו יחד איתן],\u0006 אם כן \u0003אפילו טובא נמי ליספי ליה\u0004 \u0005[יותר\u0006 ממחצית רכושו \u0005גם כן יתנו לו],\u0006 \u0003דהא זול דכולי עלמא נמי\u0004 \u0005[שהרי הוזלו\u0006 הקרקעות \u0005של הכל גם כן],\u0006 ואם כן נמצא שאין עכשיו בידו סכום מספיק כדי מחייתו, ועני הוא.","\u0003אלא\u0004 צריך לומר \u0003דאוקיר ארעתא דכולי עלמא\u0004 \u0005[שהתייקרו,\u0006 עלו מחירי \u0005הקרקעות של הכל],\u0006 \u0003ו\u0004אילו \u0003דידיה, איידי דעייל ונפיק אזוזי\u0004 \u0005[ושלו על ידי\u0006 זה \u0005ש\u0006הוא \u0005נכנס ויוצא על כספים],\u0006 כלומר, דשהכל יודעים שהוא דחוק ומשתדל להשיג כספים \u0003זל ארעיה\u0004 \u0005[הוזלו קרקעותיו],\u0006 שמאחר שיודעים שהוא דחוק בממונו רוצים אנשים לנצל את דוחקו ואין הם רוצים לקנות ממנו אלא במחיר מוזל."],["\u0003אפילו פורתא נמי\u0004 \u0005[מעט גם כן]\u0006 \u0003לא ליספו ליה\u0004 \u0005[יאכילו אותו],\u0006 ממעשר עני, שהרי קרקעותיו מצד עצמן שוות דיין כדי שייחשב כעשיר.","\u0003ואמר מר עלה\u0004 \u0005[אדוני,\u0006 רבה, \u0005עליה]:\u0006 \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 הלכה זו של \"עד מחצה\" אלא במקרה מיוחד, \u0003דביומי\u0004 \u0005[שבימי]\u0006 \u0003ניסן יקרא ארעתא\u0004 \u0005[מתייקרות הקרקעות],\u0006 לפי שמאז והלאה יש סיפק בידי הקונה להכשירן לזריעה ויכול להשתמש בהן לשנה הבאה, \u0003וביומי\u0004 \u0005[ובימי]\u0006 \u0003תשרי זל ארעתא\u0004 \u0005[מוזלות הקרקעות]\u0006 לפי שאז אין הקונה מספיק לעבד את הקרקע כראוי לקראת עונת הזריעה, וצריך לפעמים להמתין חודשים רבים.","\u0003דכולי עלמא נטרי\u0004 \u0005[שהכל מחכים]\u0006 \u0003עד ניסן ומזבני\u0004 \u0005[ומוכרים]\u0006 אז, \u0003והאי, הואיל ואצטריכא ליה זוזי, זבין כדהשתא\u0004 \u0005[וזה, הואיל והוצרכו לו כספים, מוכר כמו\u0006 המחיר \u0005של עכשיו,\u0006 בחודש תשרי\u0005],\u0006 ובמקרה כזה, \u0003עד פלגא\u0004 \u0005[חצי\u0006 השווי\u0005]\u0006 — \u0003אורחיה למיזל\u0004 \u0005[דרכו להוזיל],\u0006 \u0003טפי\u0004 \u0005[יותר\u0006 מזה\u0005]\u0006 — \u0003לאו אורחיה למיזל\u0004 \u0005[אין דרכו להוזיל],\u0006 ולכן אומדים את ערך הרכוש של אדם בכדי מחצית שוויו הרגיל.","\u0003והכא נמי גבי\u0004 \u0005[וכאן גם כן אצל]\u0006 \u0003נזקין,\u0004 לפי פתרון זה של רבה אפשר ליישב את הסתירה בין הנלמד מהכתוב שחובה על המזיק לשלם ממיטב שדהו, לבין הנאמר בברייתא ש\"ישיב\" בכל דבר; \u0003דיניה\u0004 \u0005[דינו]\u0006 של המזיק שהוא משלם מן ה\u0003עידית,\u0004 והם עומדים כעת בחודש תשרי,","\u0003ואי אמר ליה איהו\u0004 \u0005[ואם אומר לו הוא,\u0006 הניזק\u0005]:\u0006 \u0003הב\u0004 \u0005[תן]\u0006 \u0003לי בינונית טפי פורתא\u0004 \u0005[מעט יותר]\u0006 ולא אטול מן העידית, \u0003אמר ליה\u0004 \u0005[\u0006יכול המזיק \u0005לומר לו]:\u0006 \u0003אי שקלת\u0004 \u0005[אם\u0006 רוצה \u0005אתה לקחת]\u0006 \u0003כדינך\u0004 מן העידית — \u0003שקול כדהשתא\u0004 \u0005[קח כפי\u0006 המחיר \u0005של עכשיו],\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא,\u0004 ורצונך לקבל יותר מבינונית — \u0003שקיל כי יוקרא דלקמיה\u0004 \u0005[קח לפי היוקר שיבוא\u0006 בעתיד\u0005]\u0006 בחודש ניסן. ובאופן זה מיושבת הסתירה, שאם רוצה הניזק לקבל שווה כסף (ולא ממיטב) הריהו מקבל לפי הערך הגבוה.","\u0003מתקיף לה\u0004 \u0005[מקשה על\u0006 הסבר \u0005זה]\u0006 \u0003רב אחא בר יעקב: אם כן הורעת כחן של נזקין אצל\u0004 קרקע \u0003בינונית וזיבורית\u0004 (גרועה) שבאלה מקבל הניזק פחות ממחיר הנזק, \u0003דרחמנא אמר\u0004 \u0005[שהתורה אמרה]\u0006 \u0003ממיטב, ואת אמרת\u0004 \u0005[ואתה אומר]\u0006 \u0003מבינונית וזיבורית נמי\u0004 \u0005[גם כן]\u0006 \u0003לא,\u0004 שאינו יכול לקחת מאלה בשוויים!","\u0003אלא אמר רב אחא בר יעקב: אי איכא לדמויי\u0004 \u0005[אם יש לדמות]\u0006 את דברי רבה לענין הניזוק ממעשר עני — \u0003לבעל חוב\u0004 הגובה את חובו מנכסי החייב \u0003מדמינן ליה\u0004 \u0005[מדמים אנו אותו].\u0006 ובאופן זה: \u0003בעל חוב\u0004 עיקר \u0003דיניה\u0004 \u0005[\u0006\u0005דינו]\u0006 \u0003בבינונית, ואי אמר ליה\u0004 \u0005[ואם אומר לו]\u0006 בעל החוב לחייב: \u0003הב לי\u0004 \u0003זיבורית טפי פורתא\u0004 \u0005[מעט יותר],\u0006 \u0003אמר ליה\u0004 \u0005[\u0006יכול הלווה \u0005לומר\u0006 \u0005לו]:\u0006 \u0003אי שקלת\u0004 \u0005[אם לוקח אתה]\u0006 \u0003כדינך\u0004 מן הבינונית — \u0003שקול כדהשתא\u0004 \u0005[קח כפי\u0006 המחיר \u0005של עכשיו],\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 — \u0003שקיל כיוקרא דלקמיה\u0004 \u0005[קח לפי יוקר\u0006 המחיר \u0005של העתיד\u0006 לבוא\u0005].\u0006","\u0003מתקיף לה\u0004 \u0005[מקשה עליה]\u0006 על סברתו של רב אחא בר יעקב \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב איקא: אם כן\u0004 אתה עושה, הרי \u0003נעלת דלת בפני לוין.\u0004 שאם מרעים את תנאי הפירעון, יגרום הדבר שלא ירצו אנשים להלוות, \u0003דאמר ליה\u0004 \u0005[ש\u0006הרי \u0005יאמר לו]\u0006 המלווה ללווה: \u0003אילו הוו\u0004 \u0005[היו]\u0006 \u0003לי זוזי\u0004 \u0005[זוזים,\u0006 כסף\u0005]\u0006 כעת, שלא הייתי מלווה לך בשעתו — \u0003הוה שקלי כדהשתא\u0004 \u0005[הייתי לוקח,\u0006 קונה בזול, \u0005כפי\u0006 המחיר \u0005של עכשיו],\u0006 \u0003השתא דזוזי גבך, אשקול כיוקרא דלקמיה\u0004 \u0005[עכשיו שהכסף אצלך, אקח לפי היוקר שיהיה\u0006 בעתיד\u0005]?!\u0006 ואם כן נמצא שהמלווה נזקק לשלם משלו עבור כסף שהילווה!","\u0003אלא אמר רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב איקא: אי איכא לדמויי\u0004 \u0005[אם יש\u0006 מקום \u0005לדמות\u0006 את הענין\u0005]\u0006 שאמר רבה הרי \u0003לכתובת אשה מדמינן\u0004 \u0005[מדמים אנו\u0006 אותו\u0005],\u0006 \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003כתובת אשה\u0004 עיקר \u0003דינה\u0004 שגובה \u0003בזיבורית, ואי אמרה ליה איהי\u0004 \u0005[ואם אומרת לו היא,\u0006 האשה, לבעל\u0005]:\u0006 \u0003הב לי בינונית\u0004 \u0003בציר פורתא\u0004 \u0005[קצת פחות],\u0006 \u0003אמר\u0004 \u0005[\u0006יכול הוא \u0005לומר]\u0006 \u0003לה אי שקלת\u0004 \u0005[אם את לוקחת]\u0006 \u0003כדינך\u0004 — \u0003שקול כדהשתא\u0004 \u0005[קחי כ\u0006מחיר \u0005של עכשיו]\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 — \u0003שקלי כיוקרא דלקמיה\u0004 \u0005[קחי כיוקר שיהיה\u0006 בעתיד\u0005].\u0006","ומעירים, \u0003מכל מקום\u0004 לענין הניזקין \u0003קשיא\u0004 \u0005[קשה]\u0006 הסתירה בין הכתובים, שהרי בכתוב אחד נאמר שמשלם המזיק ממיטב, ובשני נאמר שמשלם בכל דבר!","\u0003אמר רבא\u0004 כך יש לומר: \u0003כל\u0004 מה \u0003דיהיב ליה\u0004 \u0005[שנותן לו]\u0006 — \u0003ממיטב ליתיב ליה\u0004 \u0005[יתן לו],\u0006 כלומר, שמכל סוג שנותן יתן לו המיטב שבאותו סוג. ולכן אם משלם בקרקע, צריך לתת לו ממיטב — מעידית שבשדהו, ואם נותן לו מן הסובין — שיתן ממיטב שבסובין.","ומקשים על הסבר זה: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"מיטב שדהו\" כתיב\u0004 \u0005[נאמר],\u0006 ומשמע דווקא מיטב שבשדה, ולא מיטב אחר!","\u0003אלא כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב פפא ורב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע מבי רב\u0004 \u0005[מבית\u0006 המדרש של \u0005רבם]\u0006 \u0003פרשוה\u0004 כך: \u0003כל מילי\u0004 \u0005[דבר]\u0006 \u0003מיטב הוא\u0004 קרוי, ואף אם אינו מן המשובח ביותר, ואפילו סובין, \u0003דאי לא מזדבן הכא\u0004 \u0005[שאם איננו נמכר כאן]\u0006 — הרי הוא \u0003מזדבן במתא אחריתי\u0004 \u0005[נמכר בעיר אחרת],\u0006 \u0003לבר מארעא\u0004 \u0005[חוץ מקרקע],\u0006 מאחר שאי אפשר להעבירה למקום אחר, הדין הוא \u0003דליתיב ליה\u0004 \u0005[שיתן לו]\u0006 המזיק לניזק \u0003ממיטב\u0004 שבקרקע בלבד, \u0003כי היכי דלקפוץ עלה זבינא\u0004 \u0005[כדי שיקפוץ עליה הקונה]\u0006 ויזכה הניזק בסכום המגיע לו.","\u0003בעא מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003רב שמואל בר אבא מ\u0004העיר \u0003אקרוניא מר' אבא: כשהן,\u0004 בית הדין, \u0003שמין,\u0004 כלומר, מעריכים ונוטלים שדה לצורך גביית דמי הנזיקין, האם \u0003בשלו,\u0004 לפי הטובה שבשדותיו, \u0003הן שמין, או בשל עולם,\u0004 במה שנחשב עידית בשוק \u0003הן שמין?\u0004","ומעירים: \u0003אליבא\u0004 \u0005[על פי שיטתו]\u0006 של \u0003ר' ישמעאל לא תבעי\u0004 \u0005[תישאל]\u0006 \u0003לך\u0004 שאלה זו, שהרי הוא \u0003אמר בדניזק שיימינן\u0004 \u0005[בשל הניזק אנו מעריכים]\u0006 ולא בשל אחרים.","\u0003כי תבעי\u0004 \u0005[כאשר תישאל]\u0006 \u0003לך\u0004 השאלה הרי זה \u0003אליבא\u0004 \u0005[על פי שיטתו]\u0006 של \u0003ר' עקיבא,\u0004 ש\u0003אמר\u0004 כי \u0003בדמזיק שיימינן\u0004 \u0005[בשל המזיק אנו מעריכים]\u0006 יש לשאול,","\u0003מאי\u0004 \u0005[מה]\u0006 נאמר כאן? האם \u0003\"מיטב שדהו\" אמר רחמנא\u0004 \u0005[אמרה התורה]\u0006 \u0003למעוטי\u0004 \u0005[למעט\u0006 את \u0005זה]\u0006 של ה\u0003ניזק\u0004 אבל מעריכים לפי שדות אחרים, \u0003או דלמא למעוטי דעלמא נמי\u0004 \u0005[שמא למעט\u0006 שדות \u0005של הכל גם כן]?\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' אבא: \u0003רחמנא אמר\u0004 \u0005[התורה אמרה]\u0006 \u0003\"מיטב שדהו\" ואת אמרת\u0004 \u0005[ואתה אומר]\u0006 \u0003בשל עולם הן שמין?!\u0004 אלא ודאי לפי שדהו של המזיק שמים.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 מברייתא ששנינו בה: \u0003אין לו\u0004 לאדם \u0003אלא עידית\u0004 ולא קרקעות אחרים, \u0003כולם\u0004 בין הניזקין, בין בעלי חוב, ובין לצורך כתובת אשה — \u0003גובין מן העידית.\u0004 אם היתה קרקעו רק \u0003בינונית\u0004 — \u0003כולם גובין בינונית,\u0004 היתה כולה \u0003זיבורית\u0004 — \u0003כולם גובין זיבורית.\u0004","אם \u0003היו לו עידית ובינונית וזיבורית\u0004 גובים באופן זה: ה\u0003נזקין\u0004 — גובים מן ה\u0003עידית, ובעל חוב\u0004 — מן ה\u0003בינונית, וכתובת אשה\u0004 — גובה מן ה\u0003זיבורית.\u0004 היו לו רק \u0003עידית ובינונית,\u0004 ה\u0003נזקין\u0004 — גובים מן ה\u0003עידית,\u0004 ו\u0003בעל חוב וכתובת אשה\u0004 — \u0003בבינונית.\u0004 היו לו רק \u0003בינונית וזיבורית, נזקין ובעל חוב\u0004 — \u0003בבינונית, וכתובת אשה\u0004 — מן ה\u0003זיבורית\u0004."],["היו לו רק \u0003עידית וזיבורית\u0004 — \u0003נזקין\u0004 גובים \u0003בעידית, ובעל חוב וכתובת אשה בזיבורית,\u0004 עד כאן הברייתא.","ומדייק רב שמואל בר אבא: \u0003קתני מיהא מציעא\u0004 \u0005[שנה\u0006 התנא \u0005על כל פנים\u0006 ב\u0005אמצעה\u0006 של הברייתא\u0005]\u0006 קטע זה: היו לו \u0003בינונית וזיבורית, נזקין ובעל חוב\u0004 גובים \u0003בבינונית, וכתובת אשה בזיבורית. ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 כי \u0003בשלו הן שמין,\u0004 שמעריכים לפי קרקעותיו של המזיק, אם כן \u0003תעשה בינונית שלו כעידית,\u0004 שהרי זה הוא מיטב נכסיו, \u0003וידחה בעל חוב אצל זיבורית,\u0004 שיכול בעל השדה לומר לבעל חובו: הבינונית היא העידית שבנכסיי!","ודוחים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003כגון שהיתה לו\u0004 בזמן ההלוואה, כאשר נשתעבדו קרקעותיו, קרקע \u0003עידית, ו\u0004אחר כך \u0003מכרה,\u0004 ובמקרה זה, שכבר נשתעבדה כבינונית לבעל החוב, אינו יכול לומר שהיא עידית שלו, ויידחה את בעל החוב לזיבורית.","ומעירים: \u0003וכן אמר רב חסדא\u0004 בפירוש הדבר: \u0003כגון שהיתה לו עידית ומכרה.\u0004","ומעירים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר]\u0006 לומר מדבר נוסף — \u0003מדקתני אחריתי\u0004 \u0005[מ\u0006מה \u0005ששנה\u0006 בברייתא \u0005אחרת]\u0006 הלכה שונה: היו לו רק \u0003בינונית וזיבורית\u0004 — \u0003הנזקין\u0004 גובים מן ה\u0003בינונית,\u0004 ו\u0003בעל חוב וכתובת אשה\u0004 מן ה\u0003זיבורית.\u0004 ואם כן \u0003קשיין אהדדי\u0004 \u0005[קשות הן זו על זו],\u0006 שהרי בברייתא הראשונה שנינו שאף בעל חוב גובה מן הבינונית, ובברייתא זו שנינו שגובה מזיבורית!","\u0003אלא לאו שמע מינה\u0004 \u0005[האם לא תלמד מכאן],\u0006 כדרך ליישב את הסתירה ביניהן: \u0003כאן\u0004 בברייתא הראשונה מדובר \u0003שהיתה לו עידית\u0004 בזמן ההלוואה \u0003ומכרה\u0004 ולכן גובה בעל חוב מן הבינונית, \u0003כאן\u0004 שגובה מזיבורית — מדובר \u0003שלא היתה לו עידית ומכרה,\u0004 הרי הבינונית שיש לו היא עידית של נכסיו, וזיבורית שיש לו היא כבינונית, ולכן בעל החוב גובה ממנה.","\u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 הסבר אחר לסתירה בין הברייתות: \u0003אידי ואידי\u0004 \u0005[זה וזה],\u0006 כלומר, שתי הברייתות, מדברות במקרה \u0003שלא היתה לו עידית\u0004 \u0003ומכרה, ולא קשיא\u0004 \u0005[ואינה קשה]\u0006 סתירה זו, כי \u0003הא\u0004 \u0005[זה]\u0006 בברייתא השניה שגובה בעל חוב מן הזיבורית, מדובר במקרה \u0003דשויא\u0004 \u0005[ששווה]\u0006 \u0003בינונית שלו\u0004 \u0003כעידית דעלמא\u0004 \u0005[של הכל]\u0006 ולכן אין בעל החוב גובה ממנה. \u0003וכאן\u0004 בברייתא הראשונה שגובה בעל חוב מן הבינונית, מדובר ש\u0003לא שויא\u0004 \u0005[שווה]\u0006 ה\u0003בינונית שלו כעידית דעלמא\u0004 \u0005[של הכל]\u0006 אלא כבינונית אחרת.","\u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 הסבר נוסף להבדל בין הברייתות, \u0003אידי ואידי\u0004 \u0005[זו וזו]\u0006 מדברות \u0003כגון שהיתה בינונית שלו כבינונית דעלמא\u0004 \u0005[של הכל]\u0006 \u0003והכא בהא פליגי\u0004 \u0005[וכאן\u0006 באמת \u0005ב\u0006נושא \u0005זה\u0006 הם \u0005חלוקים];\u0006 \u0003מר סבר\u0004 \u0005[חכם זה סבור]:\u0006 \u0003בשלו הן שמין,\u0004 וכיון שבינונית זו היא המובחרת שבקרקעותיו הריהי כעידית, ולכן גובה בעל חוב מזיבורית. \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 בברייתא הראשונה, \u0005סבור]\u0006 \u0003בשל עולם הן שמין,\u0004 ולכן אף שאין לו טובה ממנה, הריהי כבינונית לכל ענין, וגובה ממנה בעל חוב.","\u0003רבינא אמר\u0004 הסבר אחר בסתירה בין הברייתות הללו: שתיהן \u0003ב\u0004דבר שאמר \u0003עולא פליגי\u0004 \u0005[חלוקות\u0006 הן\u0005].\u0006 ש\u0003אמר עולא: דבר תורה,\u0004 כלומר, מעיקר הדין הכתוב בתורה \u0003בעל חוב\u0004 גובה \u0003בזיבורית, שנאמר: \"בחוץ תעמד והאיש אשר אתה נשה בו יוציא אליך את העבוט החוצה\"\u0004 (דברים כד, יא), והרי \u0003מה דרכו של אדם להוציא לחוץ\u0004 כשרוצה לתת לעבוט — \u0003פחות שבכלים,\u0004 משמע שאין בעל חוב מקבל בפרעון חובו אלא מן הפחות, מן הזיבורית. \u0003ומה טעם אמרו\u0004 חכמים \u0003בעל חוב\u0004 גובה מן ה\u0003בינונית\u0004 — \u0003כדי שלא תנעול דלת בפני לוין,\u0004 על מנת שלא יימנעו אנשים מלהלוות לעניים, ולכן היטיבו חכמים את תנאי הגבייה של החובות.","\u0003מר אית ליה תקנתא\u0004 \u0005[חכם זה\u0006 בברייתא הראשונה \u0005יש לו,\u0006 מקבל, את \u0005תקנת]\u0006 \u0003עולא\u0004 שיש לדאוג לטובת המלווה, ולכן גובה בעל חוב מבינונית, אף כשאין לו ללווה אלא בינונית וזיבורית בלבד. \u0003ומר\u0004 \u0005[והחכם\u0006 האחר בברייתא השניה\u0005]\u0006 \u0003לית ליה\u0004 \u0005[אין לו,\u0006 אינו מקבל\u0005]\u0006 את \u0003תקנתא\u0004 \u0005[התקנה]\u0006 של \u0003עולא\u0004 ובעל חוב נוטל כדינו בזיבורית.","ועוד דנים בנושא הגבייה בהתאם לטיבם של נכסים. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בתוספתא: \u0003מכר לאחד או לשלשה בני אדם כאחד\u0004 (ביחד) — \u0003כולן,\u0004 כל הקונים, \u0003נכנסו תחת הבעלים,\u0004 כלומר, כל ההתחייבויות שנשתעבדו להן הקרקעות הללו בגלל הבעלים הקודמים — לניזקין, לבעל חוב ולכתובת אשה — חלות עליהם, והם צריכים לשלם ממה שקנו — בהתאם לטיב הקרקע שקנו, ואחר כך יבואו ויגבו מבעל הקרקע הראשון.","אם מכר את קרקעותיו \u0003בזה אחר זה\u0004 — \u0003כולן,\u0004 כל אלה, שיש להם טענות ותביעות על בעל הקרקעות הראשון — \u0003גובין מן,\u0004 משל, \u0003האחרון,\u0004 שהרי כאשר מכר לראשון הניח מקום לגבות חובות מן הקרקע שנשארה, והשיעבוד חל על הקרקע הפנויה שטרם נמכרה, וכן הלאה. ולפיכך השיעבוד נשאר בקרקע האחרונה שנמכרה אצל הקונה האחרון בלא קשר לטיב הקרקע שקנה. אם \u0003אין לו\u0004 לאחרון כדי פרעון כל החוב — \u0003גובה משלפניו,\u0004 כלומר, מזה שקנה קודם, \u0003אין לו\u0004 — \u0003גובה משלפני פניו,\u0004 כלומר, מזה שקנה ראשון.","ועתה מבררים את תוכן הברייתא: \u0003מכרן לאחד היכי דמי\u0004 \u0005[כיצד בדיוק מדובר כאן]?\u0006","\u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שמכר את כל הקרקעות לאיש אחד \u0003בבת אחת,\u0004 אם כן יש לשאול: \u0003השתא\u0004 \u0005[עכשיו\u0006 הרי\u0005]\u0006 כשמכר \u0003לשלשה,\u0004 \u0003דאיכא למימר\u0004 \u0005[שיש\u0006 מקום \u0005לומר]\u0006 \u0003חד מינייהו\u0004 \u0003קדים\u0004 \u0005[אחד מהם קודם],\u0006 שהרי מסתבר שמכר לשלושה לא בבת אחת ממש, ואף שמכרן ביום אחד — יש ביניהם קודם ומאוחר יותר, ובכל זאת \u0003אמרת\u0004 \u0005[אומר אתה]\u0006 \u0003כולן נכנסו תחת הבעלים,\u0004 שאין מדקדקים בכך, אלא כולם כאחד אחראים, \u0003מכרן לאחד\u0004 שהדברים נעשו בבת אחת ממש \u0003מיבעיא\u0004 \u0005[נצרכה\u0006 לומר\u0005]?\u0006","\u0003אלא פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שמדובר כאן שמכר לאחד את הקרקעות \u0003בזה אחר זה\u0004 בתאריכים שונים, האחד מוקדם לאחר.","ואם כן יש לשאול: \u0003ומאי שנא\u0004 \u0005[ו\u0006ב\u0005מה שונה]\u0006 אם מכר ל\u0003שלשה\u0004 בזה אחר זה, ש\u0003כל חד וחד\u0004 \u0005[אחד ואחד]\u0006 מהשניים הראשונים \u0003אמר ליה\u0004 \u0005[יכול לומר לו]:\u0006 מדוע לוקח אתה ממני? הרי \u0003הנחתי לך מקום לגבות ממנו,\u0004 שיכול אתה לגבות חובך ממי שקנה מאוחר יותר.","ואולם \u0003האי נמי\u0004 \u0005[זה גם כן]\u0006 הלוקח האחד, מדוע אומרת הברייתא שנכנס תחת הבעלים ומשלם לכל אחד כראוי לו, עידית לניזקין וכו'? \u0003אכל חד וחד\u0004 \u0005[על כל אחד ואחד]\u0006 שבא לגבות ממנו את החוב — \u0003לימא ליה\u0004 \u0005[שיאמר לו]:\u0006 \u0003הנחתי לך מקום לגבות ממנו\u0004 את חובך מהמוכר שהוא בעל חובך. וקרקע אחרונה שקניתי ממנו זיבורית היתה, וגבה מן הזיבורית!","ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 במקרה מיוחד — \u0003כגון שלקח\u0004 (קנה) אותו קונה \u0003עידית\u0004 של הנכסים \u0003באחרונה.\u0004 ונוח לו לקונה שלא יעמוד על דינו ויטען שהניח קרקע לא קנויה לפרעון החובות (שהרי היא עידית), אלא שיכנס תחת הבעלים וישלם לבעל חוב או לכתובת אשה מן הבינונית או הזיבורית. \u0003וכן אמר רב ששת\u0004 בפירוש הדברים: \u0003כגון שלקח עידית באחרונה.\u0004","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שעידית לקח באחרונה — \u0003ליתו כולהו וליגבו\u0004 \u0005[שיבואו כולם ויגבו]\u0006 \u0003מעידית,\u0004 שהרי יכולים הם לומר: קרקע זו קנית אחרונה, ועל קרקע זו נשארו כל השיעבודים!","ומשיבים: \u0003משום\u0004 שיכול אותו אדם \u0003דאמר להו\u0004 \u0005[שיאמר להם]:\u0006 \u0003אי שתקיתו ושקליתו כדינייכו\u0004 \u0005[אם תשתקו ותקחו כדינכם]\u0006 שבעל חוב יקח מבינונית והכתובה מזיבורית — \u0003שקליתו\u0004 \u0005[תקחו],\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 תרצו, ותעמדו על שלכם שאתם רוצים לקחת מן הקרקע האחרונה העידית — \u0003מהדרנא שטרא\u0004 \u0005[אחזיר אני\u0006 את \u0005שטר]\u0006 ה\u0003זיבורית למריה\u0004 \u0005[לבעליו]\u0006 כלומר, אחזיר את הזיבורית למוכר שאתם באים לגבות ממנו, \u0003ושקליתו כולכו\u0004 \u0005[ותקחו כולכם]\u0006 \u0003מזיבורית,\u0004 שהרי במקום שיש לחייב קרקעות שלא נמכרו — ודאי שמהם לוקחים, גם דאם הם זיבורית.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שמפני טענה זו אין גובים מעידית,"],["\u0003בנזקין\u0004 כשיבוא ניזק לגבות מעידית \u0003נמי נימא הכי\u0004 \u0005[גם כן שיאמר\u0006 לו \u0005כך]:\u0006 אם אין אתה, הניזק, רוצה לקחת מן הבינונית — אחזיר את שטר הזיבורית לבעליו, ותקבל זיבורית בעל כרחך! והרי אמרנו בברייתא שכל אחד נוטל כדינו!","אם כן, ודאי אין מדובר כאן במקום שיכול לטעון טענה כזו, \u0003אלא הכא במאי עסקינן\u0004 \u0005[כאן המה אנו עוסקים]\u0006 — \u0003ביתמי\u0004 \u0005[ביתומים],\u0006 במקרה שבו החייב, שמכר את הקרקעות מת, שאף אם יחזיר להם את הקרקעות שקנה מאביהם — לא ניתן לגבות מהם. \u0003דלאו\u0004 \u0005[ש\u0006יתומים \u0005אינם]\u0006 \u0003בני\u0004 חובת \u0003פרעון נינהו\u0004 \u0005[הם]\u0006 שאם לא הניח אביהם קרקעות אין דרך לגבות מהם את חובות אביהם, \u0003ו\u0004לכן \u0003שיעבודא דיליה עליה דידיה רמיא\u0004 \u0005[השיעבוד שלו עליו,\u0006 על הקונה \u0005עצמו,\u0006 הוא \u0005מוטל].\u0006","והואיל ומדובר במקרה שהבעלים כבר מת, \u0003הלכך ליכא למימר הכי\u0004 \u0005[לכן אי אפשר לומר כך]\u0006 שכל אחד גובה מן הקונה כדינו, ולא מן העידית שקנה באחרונה משום שיכול לאיים שיחזיר את השטר לבעליו.","\u0003אלא\u0004 מטעם אחר — \u0003משום דאמר להו\u0004 \u0005[\u0006שיכול הוא \u0005לומר להם]:\u0006 \u0003טעמא מאי אמור רבנן\u0004 \u0005[מה טעם אמרו חכמים]\u0006 הלכה זו ש\u0003אין נפרעין מנכסין משועבדים\u0004 שנמכרו לאחרים \u0003במקום שיש\u0004 לחייב עצמו \u0003בני חורין\u0004 — \u0003משום תקנתא דידי\u0004 \u0005[תקנה שלי],\u0006 כלומר, עשו תקנה לטובת הקונה. ומשום תקנה זו עצמה נפרעים תחילה מן הקרקע שקנה אחרונה, שהרי היתה היא בת חורין בשעה שנמכרו כבר השאר. ואולם \u0003אנא בהא תקנתא\u0004 \u0005[אני בתקנה זו]\u0006 \u0003לא ניחא\u0004 \u0005[נוח]\u0006 \u0003לי\u0004 ומוטב לי שתגבו כל אחד מן הקרקע כדינו.","ומעירים: ודבר זה, שיכול אדם לומר שאין ברצונו בתקנה שנתקנה למענו, הוא \u0003כ\u0004דברי \u0003רבא.\u0004 ש\u0003אמר רבא: כל האומר אי אפשי\u0004 (אין רצוני) \u0003בתקנת חכמים כגון זו\u0004 — \u0003שומעין לו.\u0004 שבכל מקום שתיקנו חכמים תקנה לטובת אדם מסויים, יכול הוא לומר: אין אני רוצה בתקנה, ואני מוותר על הזכויות שתקנה זו מעניקה לי.","ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"כגון זו\"?\u0004 מה היא אותה תקנה אליה רמז רבא בקובעו את הכלל?","ומשיבים: זו היא \u0003כ\u0004\u0003ד\u0004ברי \u0003רב הונא,\u0004 ש\u0003אמר רב הונא:\u0004 אף על פי שהבעל מתחייב בכתובה לזון את אשתו, ותמורת זו תיקנו חכמים שיהא שכר עבודתה של האשה לבעלה, מכל מקום \u0003יכולה אשה שתאמר לבעלה: איני ניזונית\u0004 על חשבונך, \u0003ואיני עושה\u0004 עבודה למענך, אלא שכר עבודתי יהא שלי ואין אתה צריך לפרנסני. שרשאית האשה שלא לקבל תקנה כגון זו שנעשתה לטובתה, וכן בכל תקנות דומות לה.","ועוד בעיה באותו מקרה, בו מכר החייב את קרקעותיו המשועבדות לאדם אחד, והאחרונה שבהן היתה עידית, אלא שכאן מדובר במקרה שאותו קונה חזר ומכר מאותן קרקעות לאדם אחר. \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005],\u0006 שאם \u0003מכר\u0004 ה\u0003לוקח\u0004 (הקונה) את ה\u0003בינונית ו\u0004את ה\u0003זיבורית\u0004 שהיו משועבדות, \u0003ושייר עידית לפניו\u0004 שהוא עצמו מחזיק בה — \u0003ליתו כולהו וליגבו\u0004 \u0005[יבואו כולם ויגבו]\u0006 \u0003מעידית\u0004 שברשות הלוקח,","\u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003אחרונה היא\u0004 בין קרקעותיו של הלווה, ועליה חל השיעבוד מתחילה, \u0003ובינונית וזיבורית ליתנהו גביה\u0004 \u0005[אינן\u0006 מצויות \u0005אצלו]\u0006 \u0003דמצי למימר להו\u0004 \u0005[שיוכל לומר להם]:\u0006 \u0003גבו מבינונית\u0004 (לבעל חוב) \u0003וזיבורית\u0004 (לכתובה) ש\u0003לא ניחא\u0004 \u0005[נוח]\u0006 \u0003לי בתקנתא דרבנן\u0004 \u0005[בתקנת חכמים].\u0006 שהרי במקרה כזה הקונים ממנו, שגם לטובתם נתקנה תקנה זו, אכן רוצים בתקנה על מנת שלא יטרפו מהם את מה שקנו ממנו.","\u0003אבל\u0004 אם \u0003מכר\u0004 הלוקח הראשון את ה\u0003עידית\u0004 שקנה אחרונה \u0003ושייר\u0004 אצלו \u0003בינונית וזיבורית, מאי\u0004 \u0005[מה\u0006 יהא הדין\u0005]?\u0006","\u0003סבר אביי למימר\u0004 \u0005[לומר]:\u0006 \u0003אתו כולהו\u0004 \u0005[באים כולם]\u0006 כל בעלי החוב \u0003גבו\u0004 \u0005[\u0006ו\u0005גובים]\u0006 \u0003מעידית\u0004 שמכר לאחרים, שהרי עליה היה השיעבוד מתחילה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא:\u0004 במקרה כזה יש ללכת אחרי הכלל: אדם הקונה דבר מחבירו \u0003מה מכר ראשון לשני\u0004 — \u0003כל זכות שתבא לידו\u0004 בדבר שמכר לו. \u0003וכיון\u0004 ש\u0003אילו אתו גבי\u0004 \u0005[\u0006היו \u0005באים אצל]\u0006 ה\u0003לוקח\u0004 ה\u0003ראשון\u0004 בעוד כל הקרקעות בידו, \u0003מצי אגבי להו\u0004 \u0005[\u0006היה \u0005יכול להגבות להם]\u0006 \u0003מבינונית\u0004 (לבעל חוב) \u0003וזיבורית\u0004 (לכתובה). \u0003ואף על פי דכי זבני\u0004 \u0005[שכאשר קנה]\u0006 \u0003בינונית וזיבורית אכתי\u0004 \u0005[עדיין]\u0006 \u0003עידית בני חורין הואי\u0004 \u0005[היתה]\u0006 \u0003ו\u0004לכאורה \u0003אין נפרעין מנכסים משועבדים כל זמן דאיכא\u0004 \u0005[שיש]\u0006 \u0003בני חורין,\u0004 מכל מקום \u0003מצי אמר להו\u0004 \u0005[יכול לומר להם]:\u0006 \u0003לא ניחא\u0004 \u0005[נוח]\u0006 \u0003לי בהאי תקנה\u0004 \u0005[בתקנה זו]\u0006 של חכמים וקחו לכם כפי הראוי בדינכם.","אם כן, כיון שלוקח ראשון יכול היה לסלקם מן העידית ולתת להם כדינם, \u0003לוקח שני נמי מצי אמר להו\u0004 \u0005[גם כן יכול לומר להם]:\u0006 \u0003גבי\u0004 \u0005[גבו]\u0006 מן ה\u0003בינונית וזיבורית\u0004 ולא מן העידית. \u0003דכי זבין\u0004 \u0005[שכאשר קונה]\u0006 ה\u0003לוקח\u0004 ה\u0003שני,\u0004 הרי \u0003אדעתא\u0004 \u0005[על דעת]\u0006 ש\u0003כל זכותא דהוה ליה\u0004 \u0005[הזכויות שהיו לו]\u0006 \u0003לראשון בגוה זבין\u0004 \u0005[בתוכה קונה],\u0006 ובתוכן גם את הזכות שלא לשלם תחילה מן העידית.","ובענין דומה \u0003אמר רבא: ראובן שמכר כל שדותיו לשמעון, והלך שמעון ומכר שדה אחת ללוי, ובא בעל חוב\u0004 של \u0003ראובן\u0004 שהיו כל קרקעות ראובן משועבדות לו לגבות הקרקע בחובו, \u0003רצה\u0004 — \u0003מזה\u0004 (משמעון) \u0003גובה, רצה\u0004 — \u0003מזה\u0004 (מלוי) \u0003גובה,\u0004 ואין לוי יכול לומר לו לגבות דווקא משמעון שקדם לו, כיון שקרקע זו כבר היתה משועבדת כשקנה אותה. \u0003ולא אמרן\u0004 \u0005[אמרנו]\u0006 הלכה זו \u0003אלא דזבן\u0004 \u0005[כאשר קנה]\u0006 לוי מן ה\u0003בינונית,\u0004","\u0003אבל\u0004 אם \u0003זבן\u0004 \u0005[קנה]\u0006 לוי \u0003עידית ו\u0004כן \u0003זיבורית\u0004 — \u0003לא\u0004 יוכל המלווה לגבות ממנו, משום \u0003דאמר ליה\u0004 \u0005[ש\u0006יכול לוי \u0005לומר לו]:\u0006 \u0003להכי דייקי וזבני\u0004 \u0005[משום כך דייקתי וקניתי]\u0006 דווקא \u0003עידית וזיבורית\u0004 ולא בינונית, \u0003ארעא דלא חזיא\u0004 \u0005[קרקע שאינה ראויה]\u0006 \u0003לך,\u0004 שהרי בעל חוב גובה מבינונית.","\u0003ואפילו זבן\u0004 \u0005[קנה]\u0006 לוי \u0003בינונית נמי\u0004 \u0005[גם כן]\u0006 \u0003לא אמרן\u0004 \u0005[אמרנו]\u0006 שגובה מלוי \u0003אלא\u0004 במקרה ש\u0003לא שייר בינונית דכוותיה\u0004 \u0005[כיוצא בו]\u0006 אצל שמעון, הלוקח הראשון, \u0003דלא מצי אמר ליה\u0004 \u0005[שאינו יכול\u0006 אז לוי \u0005לומר לו]:\u0006 \u0003הנחתי לך מקום לגבי\u0004 \u0005[אצל]\u0006 \u0003שמעון\u0004 שתגבה ממנו. \u0003אבל\u0004 אם \u0003שייר בינונית דכוותיה גבי\u0004 \u0005[כיוצא בו\u0006 אצל\u0005]\u0006 \u0003שמעון\u0004 — \u0003לא גבי מיניה\u0004 \u0005[גובה ממנו]\u0006 מלוי, משום \u0003דמצי אמר ליה\u0004 \u0005[שיכול\u0006 לוי \u0005לומר לו]\u0006 לבעל חוב: \u0003הנחתי לך מקום לגבות ממנו.\u0004","ובנושא כעין זה \u0003אמר אביי: ראובן שמכר שדה לשמעון באחריות,\u0004 כלומר, שקיבל ראובן על עצמו להחזיר לשמעון את דמי השדה אם יגבה אותו בעל חוב של ראובן, \u0003ו\u0004אחר כך \u0003אתא\u0004 \u0005[בא]\u0006 \u0003בעל חוב\u0004 של \u0003ראובן\u0004 \u0003וטרף\u0004 (גבה בחובו) את השדה \u0003משמעון,\u0004 לפי שהיה משועבד לו. \u0003דינא\u0004 \u0005[\u0006מן \u0005הדין]\u0006 \u0003הוא דאזיל\u0004 \u0005[שילך]\u0006 \u0003ראובן ומשתעי דינא בהדיה\u0004 \u0005[וידבר,\u0006 יעשה \u0005דין איתו],\u0006 עם בעל החוב שלו, באשר לחוב או לערך הקרקע, או ינסה להגיע איתו לידי הסדר על מנת שיחזיר את השדה. \u0003ולא מצי אמר ליה\u0004 \u0005[ואינו יכול\u0006 בעל החוב \u0005לומר לו]\u0006 לראובן: \u0003לאו\u0004 \u0005[לא]\u0006 \u0003בעל דברים דידי את\u0004 \u0005[שלי אתה],\u0006 כלומר, אינך צד בענין, שהרי הקרקע שהיתה משועבדת לי נמצאת אצל שמעון, ואם יש לשמעון טענות — שיבוא הוא ויטען, ואתה שוב אינך צד בדבר. וזאת משום \u0003דאמר ליה\u0004 \u0005[ש\u0006יכול \u0005לומר לו]\u0006 ראובן לבעל חובו: אני נוגע בדבר, משום ש\u0003אי מפקת מיניה\u0004 \u0005[אם אתה מוציא ממנו,\u0006 משמעון, את השדה\u0005]\u0006 \u0003עלי\u0004 הוא \u0003הדר\u0004 \u0005[חוזר]\u0006 ודורש את כספו שאיבד בגללי.","\u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]:\u0006 ש\u0003אפילו\u0004 במקרה שמכר ראובן לשמעון את השדה \u0003שלא באחריות,\u0004 שלא קיבל עליו לפצות את שמעון, במקרה כזה \u0003נמי\u0004 \u0005[גם כן]\u0006 יכול ראובן להתדיין עם בעל חובו. \u0003דאמר ליה\u0004 \u0005[ש\u0006יכול הוא \u0005לומר לו]:\u0006 \u0003לא ניחא\u0004 \u0005[נוח]\u0006 \u0003לי דתהוי\u0004 \u0005[שתהיה]\u0006 \u0003לשמעון תרעומת עלי\u0004 שנטלתי ממנו כסף עבור שדה שאיבד בגללי, ולכן אני נוגע בדין זה.","\u0003ו\u0004עוד בענין מכירת שדה \u0003אמר אביי: ראובן שמכר שדה לשמעון שלא באחריות,\u0004"],["\u0003ויצאו עליה עסיקין,\u0004 שבאו אנשים לערער על תקפותה של מכירה זו, וטוענים ששדה זה מעולם לא היה שייך לראובן המוכר, \u0003עד שלא החזיק בה\u0004 שמעון — \u0003יכול\u0004 הוא \u0003לחזור בו\u0004 ולומר שהוא מוותר על הקניה, לפי שאינו רוצה להיכנס לקטטות, \u0003משהחזיק בה\u0004 — \u0003אין יכול לחזור בו.\u0004","\u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]\u0006 — \u0003דאמר ליה\u0004 \u0005[\u0006שיכול \u0005לומר לו,\u0006 ראובן המוכר\u0005]:\u0006 \u0003חייתא דקטרי\u0004 \u0005[שק קשור]\u0006 שאין אתה יודע מה בתוכו \u0003סברת וקבלת\u0004 \u0005[ידעת והסכמת לקבל],\u0006 שכיון שקנית שדה שלא באחריות, ידעת מראש שעלולות להיות בעיות ביחס לקנין זה, וכשם שהבאת בחשבון שאולי השדה ממושכן לאחרים ולא תפוצה מידי על השדה אם יילקח ממך על ידי בעל החוב שלי, אף ערעור זה על בעלות השדה הוא בכלל הבעיות שקבלת על עצמך.","ומבררים: \u0003מאימת הואי\u0004 \u0005[ממתי היא]\u0006 \u0003חזקה\u0004 לענין זה — \u0003מכי דייש אמצרי\u0004 \u0005[משעה ש\u0006הוא \u0005דורך\u0006 עובר \u0005על מצרי\u0006 גבולות השדה\u0005]\u0006 לראות ולבדוק מה נעשה בשדה.","ומעירים: \u0003ו\u0004זה \u0003דוקא\u0004 כשקנה \u0003שלא באחריות, אבל\u0004 אם קנה \u0003באחריות\u0004 — \u0003לא,\u0004 ויכול הקונה לחזור בו אפילו לאחר שהחזיק אם יצאו על השדה עוררים, שהרי לא קנה על דעת כן.","\u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]:\u0006 \u0003אפילו\u0004 כשקנה \u0003באחריות נמי\u0004 \u0005[גם כן]\u0006 אינו יכול לחזור בו, משום \u0003דאמר ליה\u0004 \u0005[\u0006שיכול \u0005לומר לו]\u0006 המוכר לקונה: \u0003אחוי\u0004 \u0005[הראה]\u0006 לי תחילה את \u0003טירפך\u0004 \u0005[שטר הטריפה שלך]\u0006 שכתבו בית דין שטר שנטלו ממך את השדה בדין, לפי שנתברר שהשדה שייך לאחרים, \u0003ואשלם לך\u0004 אז. ואף שיש עכשיו מערערים על בעלות השדה, כל עוד לא הוכרע הדבר אין אני צריך להחזיר.","ושוב חוזרים אנו לבעיה הראשונה, מה משלם המזיק, האם ממיטב הארץ דווקא או כל דבר. \u0003רב הונא אמר:\u0004 יכול המזיק לתת לניזק \u0003או כסף או מיטב\u0004 קרקעותיו.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רב נחמן לרב הונא,\u0004 הלא שנינו: \u0003\"ישיב\"\u0004 — \u0003לרבות שוה כסף, אפילו סובין,\u0004 משמע שיכול לתת לא כסף ולא מיטב, אלא שווה כסף!","השיב רב הונא: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003בדלית ליה\u0004 \u0005[ב\u0006זמן \u0005שאין לו]\u0006 דבר אחר אלא סובין. ומקשים: \u0003אי דלית ליה\u0004 \u0005[אם שאין לו]\u0006 — \u0003פשיטא\u0004 \u0005[\u0006\u0005פשוט\u0006 הדבר\u0005],\u0006 שהרי אינו יכול לשלם אלא ממה שיש לו! ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 כי \u0003אמרינן ליה\u0004 \u0005[אומרים אנו לו]:\u0006 \u0003זיל\u0004 \u0005[לך]\u0006 \u0003טרח זבין ואייתי ליה\u0004 \u0005[מכור\u0006 את הסובין \u0005והבא לו]\u0006 \u0003כסף\u0004 ואינך יכול לשלם בשווה כסף, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאם אין לו כסף יכול לשלם בשווה כסף.","ועוד מביאים, \u0003אמר רב אסי: כספים הרי הן כקרקע.\u0004 ושואלים: \u0003למאי הלכתא\u0004 \u0005[למה,\u0006 לאיזו \u0005הלכה]\u0006 אמר את הדבר? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003לענין מיטב,\u0004 שהנותן כסף הרי זה כנותן ממיטב הארץ — \u0003היינו\u0004 \u0005[הרי הוא]\u0006 מה שאמר \u0003רב הונא\u0004 שהובאו דבריו מקודם, ומה מקום להביא את דברי רב אסי כדעה נוספת בענין זה?","\u0003אלא,\u0004 הכוונה בדברי רב אסי היא \u0003ל\u0004מקרה של \u0003שני אחים שחלקו\u0004 ירושתם בנכסי אביהם, \u0003ונטל אחד\u0004 מהם \u0003קרקע ואחד\u0004 מהם \u0003כספים, ובא בעל חוב\u0004 של אביהם \u0003ונטל קרקע\u0004 שהיתה משועבדת לו, \u0003דאזיל האי\u0004 \u0005[שהולך זה\u0006 שנטלו קרקעותיו\u0005]\u0006 \u0003ושקיל פלגא\u0004 \u0005[ולוקח חצי]\u0006 \u0003בכספים\u0004 של הירושה \u0003בהדיה\u0004 \u0005[יחד עימו,\u0006 עם האח השני\u0005].\u0006","ותוהים: \u0003פשיטא, האי ברא והאי לאו ברא\u0004 \u0005[פשוט\u0006 הדבר, וכי \u0005זה בן וזה איננו בן]?!\u0006 וכיון שאף הוא בן — בוודאי חייב גם הוא לפרוע את חוב אביו!","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 שלא כך היתה התמיהה, אלא \u0003אדרבה\u0004 \u0005[היפך\u0006 הדבר\u0005],\u0006 \u0003לאידך גיסא\u0004 \u0005[לצד האחר]:\u0006 \u0003דאמר ליה\u0004 \u0005[שאומר לו]\u0006 האח שנטל כסף בירושתו לאח שנטל קרקע: \u0003להכי שקלי\u0004 \u0005[משום כך לקחתי]\u0006 \u0003כספים\u0004 וקיבלתי על עצמי סיכון, \u0003דאי מגנבי\u0004 \u0005[שאם ייגנבו]\u0006 — \u0003לא משתלמנא מינך\u0004 \u0005[אינני מקבל תשלום ממך],\u0006 \u0003ולהכי שקלת ארעא\u0004 \u0005[ולכך נטלת קרקע]\u0006 וקבלת על עצמך סיכון אחר — \u0003דאי מטרפא לא משתלמא לך מידי מינאי\u0004 \u0005[שאם תיטרף\u0006 על ידי בעלי חוב \u0005לא תקבל כל\u0006 תשלום \u0005ממני].\u0006 ואין איפוא להסביר את דברי רב אסי בדרך זו, המוקשה מכל צד.","\u0003אלא\u0004 יש לומר שנתכוון \u0003ל\u0004ענין \u0003שני אחים שחלקו\u0004 קרקע אביהם בירושה \u0003ובא בעל חוב\u0004 של אביהם \u0003ונטל\u0004 קרקע מ\u0003חלקו של אחד מהן\u0004 בלבד, וזה שנטלו חלקו תובע מאחיו שיחזור ויתחלק איתו בקרקע הנותרת. ולענין זה אמר רב אסי שאינו צריך לתת לו דווקא קרקע ויכול לתת לו חלקו בכספים כמו בקרקע.","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 כבר \u0003אמרה רב אסי\u0004 את ההלכה הזו \u0003חדא זימנא\u0004 \u0005[פעם אחת],\u0006 \u0003דאיתמר\u0004 \u0005[שנאמר]\u0006 שנחלקו בבעיה זו: \u0003האחים שחלקו\u0004 ביניהם את רכוש אביהם שמת והניחו להם בירושה \u0003ובא בעל חוב ונטל\u0004 את כל \u0003חלקו של אחד מהן, רב אמר: בטלה מחלוקת\u0004 (חלוקה) ראשונה וחוזרים ומתחלקים בחלקו של השני. \u0003ושמואל אמר:\u0004 אותו אח שנטלו ממנו — \u0003ויתר,\u0004 איבד את חלקו בירושה. \u0003ורב אסי אמר:\u0004 האח שנטלו ממנו \u0003נוטל רביע בקרקע,\u0004 כלומר, חצי מקרקעו של האח שקיבל מחצית הירושה, \u0003ו\u0004עוד נוטל \u0003רביע במעות,\u0004 כדי להשלים את חלקו במחצית הירושה.","ומסבירים את שיטותיהם, \u0003רב אמר: בטלה מחלוקת, קסבר\u0004 \u0005[סבור\u0006 הוא\u0005]:\u0006 \u0003האחים\u0004 אף \u0003שחלקו\u0004 מכל מקום \u0003כיורשים\u0004 שעדיין לא חלקו \u0003הוו\u0004 \u0005[הם\u0006 נחשבים\u0005]\u0006 וחוב אביהם מוטל על שניהם כאחד לפרוע, ואם נטל בעל החוב מאחד — הריהם חוזרים ומתחלקים.","\u0003ושמואל אמר: ויתר\u0004 (איבד), \u0003קסבר\u0004 \u0005[סבור\u0006 הוא\u0005]:\u0006 \u0003האחים שחלקו\u0004 הרי הם \u0003כלקוחות,\u0004 שכאילו קנו את השדות שברשותם זה מזה, \u0003וכלוקח שלא באחריות דמי\u0004 \u0005[נחשב\u0006 הוא\u0005]\u0006 והקונה שלא באחריות, אם טרפו ממנו — אינו יכול לחזור על המוכר. ואף כאן האח שנטרף חלקו אינו יכול לתבוע דבר מאחיו.","\u0003ורב אסי אמר: נוטל רביע בקרקע ורביע במעות.\u0004 וטעמו — \u0003מספקא ליה\u0004 \u0005[מסופק לו,\u0006 בעיניו\u0005]\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003כיורשין דמו\u0004 \u0005[\u0006הם \u0005נחשבים]\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003כלקוחות דמו\u0004 \u0005[\u0006הם \u0005נחשבים],\u0006 וכיון שיש ספק בדבר — \u0003הלכך נוטל\u0004 \u0005[לוקח]\u0006 \u0003רביע\u0004 אחד \u0003בקרקע,\u0004 על צד שהוא יורש. \u0003ו\u0004ה\u0003רביע\u0004 הנוסף רשאי אחיו לתיתו \u0003במעות,\u0004 כאילו היה לוקח באחריות, שחייב המוכר לפצותו על השדה שנטרף ממנו, שלענין זה כספים הריהם כקרקע. ואם כן נמצא שכבר אמר רב אסי את ההלכה הזו במפורש!","\u0003אלא\u0004 יש לחזור ולהסביר: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"הרי הן כקרקע\"\u0004 — \u0003לענין מיטב\u0004 של תשלום נזקין.","\u0003אי הכי\u0004 \u0005[אם כך]\u0006 חוזרים אנו שוב לשאלה: \u0003היינו\u0004 \u0005[זו היא]\u0006 ממש הלכתו של \u0003רב הונא!\u0004 ומתקנים, \u0003אימא\u0004 \u0005[אמור,\u0006 תקן\u0005]\u0006 ונסח זאת: \u0003וכן אמר רב אסי,\u0004 שלא הביאה הגמרא את דברי רב אסי, אלא כדי לומר שהם כדברי רב הונא.","\u0003אמר ר' זירא אמר רב הונא: במצוה\u0004 נותן \u0003עד שליש.\u0004","ושואלים: \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003שליש,\u0004 כלומר, מה כוונת הדבר?"],["\u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שנותן עבור מצוה \u0003שליש ביתו,\u0004 כלומר, שליש רכושו. \u0003אלא מעתה, אי איתרמי ליה תלתא מצותא\u0004 \u0005[אם מזדמנות לו שלוש מצוות]\u0006 \u0003ליתיב לכוליה ביתא\u0004 \u0005[יתן את כל ביתו]\u0006 ורכושו?! ובוודאי לא לכך מתכוונים.","\u0003אלא,\u0004 כך יש לומר, \u0003אמר ר' זירא: בהידור מצוה\u0004 — \u0003עד שליש במצוה.\u0004 שאם רוצה אדם להדר במצוה מסויימת ולהוסיף בטיב או בנוי — מוסיף עד שליש מן המחיר הקבוע לאותו דבר, ויותר מכן אינו מחוייב אפילו לשם הידור.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב אשי:\u0004 כיצד מחשבים שליש זה? האם הוא \u0003שליש מלגיו\u0004 \u0005[מבפנים]\u0006 שמחשב ומוסיף שליש על המחיר הנמוך, \u0003או שליש מלבר\u0004 \u0005[מבחוץ]\u0006 שליש מן הסכום שצריך לשלם על החפץ היקר, שמוסיף חצי מן המחיר הזול? בעיה זו לא נפתרה, ולכן \u0003תיקו\u0004 \u0005[תעמוד\u0006 במקומה\u0005].\u0006","\u0003במערבא אמרי משמיה\u0004 \u0005[בארץ ישראל היו אומרים משמו]\u0006 של \u0003ר' זירא:\u0004 \u0003עד שליש\u0004 שמוסיף בהידור מצוה — מוסיף \u0003משלו,\u0004 כלומר, כשאר מצוות שמוציא משלו, והקדוש ברוך הוא נותן שכרו לעתיד לבוא. \u0003מכאן ואילך,\u0004 אם מוסיף בהידור מצוה — \u0003משל הקדוש ברוך הוא,\u0004 שיקבל שכר תוספת זו עוד בעולם הזה, שיפרע לו הקדוש ברוך הוא.","ועוד כללים בדין תשלומי נזיקין: \u0003כל\u0004 דבר \u0003שחבתי בשמירתו,\u0004 שמוטלת עלי חובה לשמור אותו — \u0003הכשרתי את נזקו,\u0004 כלומר, מוטלת עלי החובה לטפל בכל הנזקים שגרם. כל מקרה ש\u0003הכשרתי במקצת נזקו,\u0004 שאם יש עלי חובה או אחריות על מקצת הנזק — \u0003חבתי בתשלומי נזקו כהכשר כל נזקו.\u0004 כלומר, כיון שאדם אחראי עבור דבר מסויים ונזקיו, הרי מאותה שעה חייב הוא על כל הנזקים שנגרמו על ידו, ואינו יכול לומר שאחריותו היא רק לאותו חלק שהוא טיפל בו, וכאשר יבואר במפורט בגמרא.","ועוד כלל אמרו: מה הם הדברים שחייבים לשלם אם הזיק להם — \u0003נכסים שאין בהן מעילה,\u0004 כלומר, שאינם שייכים להקדש. \u0003נכסים שהן של בני ברית\u0004 (יהודים), \u0003נכסים המיוחדים,\u0004 שיש להם בעלים מוגדרים, שאינם הפקר.","\u0003ו\u0004כן חייבים על הנזקים שנעשו \u0003בכל מקום, חוץ מרשות המיוחדת למזיק\u0004 שאין לניזק רשות להיכנס שם,","\u0003ורשות\u0004 המשותפת של \u0003הניזק והמזיק.\u0004","ועוד כלל: בכל אלה שאחראי להם, \u0003כשהזיק חב\u0004 (חייב) \u0003המזיק לשלם תשלומי נזק במיטב הארץ.\u0004","הלכות אלה שבמשנה נתבררו בברייתא: \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003כל שחבתי בשמירתו הכשרתי את נזקו, כיצד? שור ובור שמסרן ל\u0004שמירה ביד \u0003חרש שוטה וקטן\u0004 שכל אלה אין בהם דעת, \u0003והזיק\u0004 — \u0003חייב לשלם, מה שאין כן באש.\u0004","ומבררים: \u0003במאי עסקינן\u0004 \u0005[במה אנו עוסקים]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שמדובר כאן \u0003בשור קשור ובור מכוסה\u0004 שמסרם למי שאינו בן דעת, \u0003דכוותה\u0004 \u0003גבי\u0004 \u0005[שכיוצא בו אצל]\u0006 \u0003אש,\u0004 יש להסביר גם כן שמדובר במקרה שמסר \u0003גחלת\u0004 שכשלעצמה אינה מזיקה, למי שאינו בן דעת, ואם כן \u0003מאי שנא הכא ומאי שנא הכא\u0004 \u0005[מה שונה כאן ומה שונה כאן]\u0006 שבשור ובבור חייב, ובאש פטור?","\u0003אלא\u0004 תאמר שמדובר \u0003בשור מותר\u0004 (שאינו קשור) \u0003ובור מגולה, דכוותה גבי\u0004 \u0005[שכיוצא בה אצל]\u0006 \u0003אש\u0004 צריך לומר שמדובר שמסר למי שאינו בן דעת \u0003שלהבת\u0004 בוערת — כיצד יכול אתה לומר \u0003\"מה שאין כן באש\u0004 ש\u0003פטור\"? והא\u0004 \u0005[והרי]\u0006 \u0003אמר ריש לקיש משמיה\u0004 \u0005[משמו]\u0006 של החכם \u0003חזקיה: לא שנו\u0004 שפטור על נזקי אש כשמסר למי שאינו בר דעת — \u0003אלא\u0004 כ\u0003שמסר לו גחלת ו\u0004זה שאינו בר דעת \u0003ליבה\u0004 את הגחלת מעצמו והזיקה האש, \u0003אבל\u0004 מסר לו \u0003שלהבת\u0004 והזיק — הרי המוסר \u0003חייב, מאי טעמא\u0004 \u0005[מה הטעם]\u0006 — \u0003דהא ברי הזיקא\u0004 \u0005[שהרי הנזק ברור]\u0006 שהלא ודאי ייגרם נזק על ידי כך! ואם כן איך נבין את ההבדל בדינים שבברייתא?","ומשיבים: \u0003לעולם\u0004 תפרש שמדובר \u0003בשור קשור ובור מכוסה, ודכוותה גבי\u0004 \u0005[ושכיוצא בה אצל]\u0006 \u0003אש\u0004 — \u0003גחלת. ודקא אמרת\u0004 \u0005[וזה שאתה אומר]\u0006 \u0003מאי שנא הכא ומאי שנא הכא\u0004 \u0005[מה שונה כאן ומה שונה כאן]\u0006 — יש הבדל:","\u0003שור\u0004 — \u0003דרכיה לנתוקי\u0004 \u0005[דרכו לנתק]\u0006 את החבל שהוא קשור בו, \u0003בור\u0004 — \u0003דרכיה לנתורי\u0004 \u0005[דרכו שיפול\u0006 מכסהו\u0005],\u0006 שמסתבר שבמשך הזמן יוכל הדבר לגרום לנזק, והשומר אינו בן דעת ואינו יכול לשמור. ואילו \u0003גחלת\u0004 להיפך, \u0003כמה דשביק\u0004 \u0005[שמניח]\u0006 \u0003לה מעמיא עמיא ואזלא\u0004 \u0005[היא מתעממת והולכת]\u0006 ואין הנזק ברור כלל. ואם ליבה השומר חסר הדעת את האש — אין זה דבר שהמוסר אחראי לו.","ושואלים: \u0003ול\u0004שיטת \u0003ר' יוחנן,\u0004 ש\u0003אמר\u0004 ש\u0003אפילו\u0004 כאשר \u0003מסר לו שלהבת נמי\u0004 \u0005[גם כן]\u0006 \u0003פטור, דכוותה הכא\u0004 \u0005[כיוצא בו כאן]\u0006 מדובר \u0003בשור מותר ובור מגולה,\u0004 ואם כן \u0003מאי שנא הכא ומאי שנא הכא\u0004 \u0005[מה שונה כאן ומה שונה כאן]\u0006 שחייב על נזקי שור ובור ואינו חייב על נזקי אש?","ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 באש \u0003צבתא\u0004 \u0005[האחיזה]\u0006 של ה\u0003חרש קא גרים\u0004 \u0005[היא שגרמה],\u0006 שהחרש מדעתו הוא נוטל ומוליך את האש ממקום למקום, והוא שעשה את עיקר פעולת ההיזק, ואילו \u0003הכא\u0004 \u0005[כאן]\u0006 בשור ובור — \u0003לא צבתא\u0004 \u0005[האחיזה]\u0006 של ה\u0003חרש קא גרים\u0004 \u0005[היא שגרמה],\u0006 שהרי החרש עצמו לא גרם נזק, אלא שאינו ברדעת לשמור, והאחריות לנזק מוטלת על המוסר לו.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 יש \u0003חומר\u0004 (חומרה) \u0003בשור מבבור\u0004 בדברים מסויימים, וכן יש \u0003חומר\u0004 \u0003בבור מב\u0004דין \u0003שור.\u0004","ומפרטים: \u0003חומר בשור מבבור — שהשור\u0004 שהרג אדם \u0003משלם\u0004 בעליו \u0003את הכופר\u0004 למשפחת ההרוג, אם היה יהודי, \u0003וחייב\u0004 בעל השור \u0003ב\u0004תשלום \u0003שלשים\u0004 סלע \u0003של עבד\u0004 כנעני שהרג שורו, \u0003נגמר דינו\u0004 של השור למיתה בבית הדין אחרי שהרג אדם כלשהו — הרי הוא \u0003אסור בהנאה.\u0004 \u0003ו\u0004כן מצד תכונותיו לגבי נזיקין יש בשור חומרה — \u0003דרכו לילך ולהזיק. מה שאין כן\u0004 כל הדברים אלה \u0003בבור,\u0004 שאם נהרג אדם בבור, אין בעל הבור משלם עליו כופר, או שלושים סלע על מיתת עבד כנעני בבורו, ואין הבור שנהרג בו אדם נאסר בהנאה, וכן אין דרכו של בור לילך ולהזיק. ומצד אחר \u0003חומר בבור מבשור,\u0004 מצד נזקו — \u0003שהבור תחילת עשייתו לנזק, ומועד מתחילתו\u0004 שאין צורך להזהיר את בעל הבור (כמו שמזהירים בבעל שור שנגח) אלא בעל הבור הרי הוא כמועד מתחילת עשייתו, \u0003מה שאין כן בשור\u0004."],["\u0003חומר בשור,\u0004 כלומר, בנזקי קרן \u0003מבאש, חומר באש מבשור.\u0004","כיצד \u0003חומר בשור מבאש?\u0004 — \u0003שהשור\u0004 שהרג אדם \u0003משלם\u0004 בעליו \u0003כופר, וחייב בשלשים\u0004 סלעים \u0003של עבד\u0004 שמשלם לאדוניו אם הרגו שורו. \u0003נגמר דינו\u0004 למיתה — \u0003אסור בהנאה.\u0004 ועוד, אם \u0003מסרו לחרש שוטה וקטן\u0004 — \u0003חייב, מה שאין כן באש\u0004 שאין בה כל אלו החיובים. \u0003חומר באש מבשור\u0004 — \u0003שהאש מועדת מתחילתה, מה שאין כן בשור.\u0004","ועוד, \u0003חומר באש מבבור, וחומר בבור מבאש;\u0004","\u0003חומר בבור מבאש\u0004 — \u0003שתחילת עשייתו\u0004 של הבור \u0003לנזק, מסרו לחרש שוטה וקטן\u0004 שישמרוהו — \u0003חייב, מה שאין כן באש.\u0004 ומצד אחר \u0003חומר באש מבבור ש\u0004כן \u0003האש דרכה לילך\u0004 ממקומה \u0003ולהזיק, ו\u0004היא \u0003מועדת לאכול\u0004 (לשרוף) \u0003בין דבר הראוי לה\u0004 כגון חומרים העשויים להישרף, \u0003ובין דבר שאינו ראוי לה.\u0004 שגם אם גרמה האש נזק לדברים שאין דרכם להישרף — חייב בעל האש עליהם, \u0003מה שאין כן בבור\u0004 שאינו הולך ממקומו ומזיק, ובעל הבור אחראי לתשלומי נזקי הבור רק על דברים מסויימים, ולא על הכל.","ושואלים, \u0003וליתני\u0004 \u0005[ושישנה]\u0006 עוד הבדל: \u0003חומר בשור מבבור\u0004 — \u0003שהשור חייב בו\u0004 שישלם בעליו \u0003את\u0004 ערך \u0003הכלים\u0004 שהזיק לבעליהם, \u0003מה שאין כן בבור\u0004 שאינו חייב לשלם על כלים שנפלו וניזוקו בבור!","ודוחים: \u0003הא מני\u0004 \u0005[\u0006ברייתא \u0005זו\u0006 כשיטת \u0005מי היא]\u0006 — כשיטת \u0003ר' יהודה היא,\u0004 שהוא \u0003מחייב\u0004 בתשלומים אף \u0003על נזקי כלים בבור.\u0004","על כך מקשים: \u0003אי\u0004 \u0005[אם]\u0006 דעת \u0003ר' יהודה\u0004 היא — \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה]\u0006 של הברייתא: \u0003חומר באש מבבור\u0004 — \u0003שהאש דרכה לילך ולהזיק, ומועד לאכול בין דבר הראוי לה ובין דבר שאינו ראוי לה, מה שאין כן בבור.\u0004 ומעתה נברר את הענין: \u0003דבר הראוי לה מאי נינהו\u0004 \u0005[מה הוא]\u0006 — \u0003עצים\u0004 וכיוצא בהם, \u0003דבר שאין ראוי לה מאי נינהו\u0004 \u0005[מה הם]\u0006 — \u0003כלים,\u0004 ונאמר בברייתא על כך \u0003מה שאין כן בבור.\u0004 ומעתה, \u0003אי\u0004 \u0005[אם]\u0006 כשיטת \u0003ר' יהודה היא\u0004 — \u0003הא אמרת\u0004 \u0005[הרי אומר אתה]\u0006 ש\u0003מחייב היה ר' יהודה על נזקי כלים בבור!\u0004","\u0003אלא לעולם\u0004 תפרש שברייתא זו כשיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003היא\u0004 הפוטרים נזקי כלים בבור. ובתשובה לשאלה מדוע לא שנה גם הבדל זה של נזקי כלים בין בור ושור, יש לומר כי \u0003תנא\u0004 \u0005[שנה]\u0006 \u0003ושייר\u0004 דברים אחדים, שלא פירש התנא את כל ההבדלים הקיימים. ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 \u0003שייר\u0004 עוד שאומר אתה \u0003דהאי\u0004 \u0005[ש\u0006את \u0005זה]\u0006 \u0003שייר,\u0004 כלומר, אינך יכול לטעון שהתנא נותן רשימה שאינה מלאה רק בגלל דבר אחד, ואם כן מהו הנוסף עליו? ומשיבים: \u0003שייר טמון,\u0004 שבנזקי אש אינו חייב על נזקים של מה שהיה טמון ולא נראה לעין בשעה שהדליקו את האש — מה שאין כן באבות נזיקין אחרים שאין מחלקים בכך, וחייב אף על הטמון.","ותירוץ אחר לשאלה: \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]:\u0006 \u0003לעולם\u0004 הברייתא כשיטת \u0003ר' יהודה\u0004 היא, אלא \u0003דבר שאין ראוי לה\u0004 ששנוי אצל האש שחייב, ופטור בבור, \u0003לאו לאתויי\u0004 \u0005[לא להביא,\u0006 לרבות\u0005]\u0006 \u0003כלים, אלא לאתויי\u0004 \u0005[להביא]\u0006 דבר אחר — \u0003ליחכה\u0004 האש את \u0003נירו\u0004 (שדהו) \u0003וסכסכה\u0004 (חרכה) את \u0003אבניו\u0004 שעל כך הוא חייב, ומה ששנו \"מה שאין כן בבור\" — שלא שייך דבר זה בבור.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב אשי\u0004 על תירוץ זה שהברייתא כר' יהודה, ולא שייר בה דבר: הלא יש הבדל נוסף בין שור ובור, ואפשר \u0003ליתני\u0004 \u0005[שישנה]\u0006 כך: \u0003חומר בשור מבבור\u0004 — \u0003שהשור חייב בו שור פסולי המוקדשין\u0004 שהוא שור שהוקדש לקרבן ואחר כך נפל בו מום ונפסל מהקרבה, ונפדה, שאף לאחר פדיונו יש בו צד קדושה, ושור כזה, אם נגחו שור אחר — חייב לשלם לבעל השור, \u0003מה שאין כן בבור,\u0004 ששור פסולי המוקדשים שנפל בבור — אין בעל הבור חייב עליו!","\u0003אי אמרת בשלמא רבנן\u0004 \u0005[נניח אם אומר אתה\u0006 שברייתא זו כשיטת \u0005חכמים]\u0006 \u0003היא\u0004 — \u0003איידי\u0004 \u0005[מתוך]\u0006 ש\u0003שייר הך\u0004 \u0005[את זו],\u0006 נזקי כלים — \u0003שייר נמי הך\u0004 \u0005[גם\u0006 את \u0005זו],\u0006 את בהמת פסולי המוקדשים. \u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 שהברייתא כשיטת \u0003ר' יהודה\u0004 היא, \u0003מאי\u0004 \u0005[מה]\u0006 \u0003שייר\u0004 עוד \u0003דהאי\u0004 \u0005[ש\u0006את \u0005זה]\u0006 גם \u0003שייר?\u0004","ומשיבים: \u0003שייר\u0004 גם את המקרה של \u0003דש\u0004 (דרס) \u0003בנירו,\u0004 שהשור דרס בכוונה על גבי שדה חרוש. שנזק זה אינו נחשב תולדה של רגל, משום שאינו כדרכו, שאין דרכו לדוש מקום שדורך בו, אלא כתולדה של קרן, שהשור רוצה להזיק על ידי דריסה וחייב בעליו בתשלומי הנזק. מה שאין כן בבור — שהרי אין שייך דבר זה בבור. ומקשים: \u0003אי\u0004 \u0005[אם]\u0006 \u0003משום דש בנירו\u0004 \u0003לאו שיורא\u0004 \u0005[לא שיור]\u0006 \u0003הוא, דהתנא\u0004 \u0005[שהרי\u0006 כבר \u0005שנה]\u0006 בשור באופן כללי: \u0003שכן דרכו לילך ולהזיק,\u0004 ודבר זה הוא חלק מדרכי הנזק של שור, שחמור הוא בזה כשאר נזקים. ואם כן יש לחזור לשיטה שברייתא זו היא כשיטת חכמים.","שנינו במשנה: \u0003הכשרתי במקצת נזקו\u0004 וכו'.","ומביאים ברייתא בה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 דין זה בביאור ובהרחבה: \u0003הכשרתי מקצת נזקו\u0004 — \u0003חבתי בתשלומי נזקו כהכשר כל נזקו. כיצד\u0004 הוא דין זה? \u0003החופר בור\u0004 שעומקו \u0003תשעה\u0004 טפחים, \u0003ובא\u0004 אדם \u0003אחר\u0004 וחפר בו טפח נוסף \u0003והשלימו לעשרה\u0004 טפחים, שהוא שיעור בו לחיוב במיתה — \u0003האחרון חייב\u0004 על כל הנזקים שנגרמו בבור זה, הרי שאף שהכשיר ועשה רק מקצת נזקו, חייב כאילו עשאו כולו.","ומעירים: \u0003ו\u0004דבר זה ש\u0003לא כ\u0004שיטת \u0003רבי\u0004 שאינו סבור כן. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003החופר בור\u0004 שעומקו \u0003תשעה\u0004 טפחים \u0003ובא אחר והשלימו לעשרה\u0004 — ה\u0003אחרון חייב\u0004 בכל, בין בנזקים בין במיתה. \u0003רבי אומר:\u0004 יש לחלק; \u0003אחר אחרון למיתה,\u0004 שאחריותו של האחרון היא במקרה שנפלה שם בהמה ומתה, אולם \u0003אחר שניהם,\u0004 שהאחריות חלה על שניהם \u0003ל\u0004ענין \u0003נזקין\u0004 אם הוזקה הבהמה ולא מתה, שהרי גם מי שחפר בור תשעה חייב על נזקיו.","\u0003רב פפא אמר:\u0004 באמת יש לפרש את מה ששנינו שהמכשיר מקצת הנזק חייב בכל לענין \u0003מיתה\u0004 שנגרמה בבור, \u0003ו\u0004אז תהיה \u0003דברי הכל,\u0004 גם כדעת רבי.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 שמועה זו בסגנון אחר. שכך שאלו: \u0003לימא\u0004 \u0005[האם לומר]\u0006 שברייתא זו היא ש\u0003לא כ\u0004שיטת \u0003רבי?\u0004 \u0003אמר רב פפא:\u0004 אפשר לפרש שכאן מדובר רק \u0003ל\u0004ענין \u0003מיתה, ו\u0004אם כן הרי היא כ\u0003דברי הכל.\u0004","על הברייתא שפירשה את משנתנו בבור שהשלימו לעשרה, \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003ר' זירא: ותו ליכא\u0004 \u0005[ו\u0006האם \u0005אין עוד]\u0006 מקרים שאדם שהכשיר מקצת הנזק חייב כאילו הכשיר כל הנזק? \u0003והא איכא\u0004 \u0005[והרי יש]\u0006 מקרה כגון זה: \u0003מסר שורו לחמשה\u0004 \u0003בני אדם ופשע בו\u0004 (התרשל בשמירתו) \u0003אחד מהן\u0004 מן השומרים, והלך השור \u0003והזיק\u0004 — הרי שומר זה \u0003חייב,\u0004 ונמצא שאף ששומר זה היה רק אחד מן החבורה ולא הכשיר אלא מקצת הנזק, הרי זה חייב על הכל.","קושיה זו דוחים, שכן יש לברר: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]:\u0006 \u0003אילימא דבלאו איהו\u0004 \u0005[אם תאמר שבלעדיו]\u0006 \u0003לא הוה מינטר\u0004 \u0005[היה\u0006 השור \u0005נשמר]\u0006 וצריך חמישה אנשים לשומרו, אם כן \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שחייב, \u0003דאיהו קעביד\u0004 \u0005[ש\u0006הרי \u0005הוא עשה]\u0006 וגרם את הנזק במה שנתרשל בשמירה, שהלא בלעדיו אין השור נשמר, והרי זה כמכשיר כל נזקו. \u0003אלא\u0004 תאמר \u0003דבלאו איהו נמי מינטר\u0004 \u0005[שבלעדיו גם כן נשמר]\u0006 ואין צורך בחמישה — אם כן \u0003מאי קעביד\u0004 \u0005[מה\u0006 הוא \u0005עשה]\u0006 בכך שהתרשל בשמירתו? והרי בלעדיו גם כן נשמר השור, ואם כן באמת לא הכשיר אפילו מקצת נזקו. ואם כן דוגמה זו שהביא ר' זירא אינה שייכת לנושא שדובר בו.","כדרך שעשה ר' זירא \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 על הברייתא שנקטה דווקא דוגמא אחת \u0003רב ששת\u0004 באופן אחר: \u0003והא איכא\u0004 \u0005[והרי יש]\u0006 עוד מקרה של מכשיר מקצת נזקו, והוא ה\u0003מרבה בחבילה,\u0004 אם אדם מוסיף עצים למדורה ועל ידי זה גורם שתיווצר דליקה ששרפה שדה אחר!","ואף קושיה זו דוחים, שכן יש לברר: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006"],["\u0003אי דבלאו איהו\u0004 \u0005[אם שבלעדיו],\u0006 בלי החבילה שהוסיף \u0003לא אזלא\u0004 \u0005[היתה הולכת]\u0006 האש ושורפת שדה אחר — \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שהוא חייב, שהרי הוא שגרם לנזק. \u0003אלא דבלאו איהו אזלא\u0004 \u0005[שבלעדיו היתה הולכת]\u0006 — אם כן \u0003מאי קא עביד\u0004 \u0005[מה\u0006 הוא \u0005עשה]\u0006 בכך שהוסיף חבילה?","וכן \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 על הברייתא \u0003רב פפא\u0004 מדין אחר: \u0003והא איכא הא\u0004 \u0005[והרי יש\u0006 דבר \u0005זה]\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003חמשה שישבו על ספסל אחד ולא שברוהו, ובא אחד\u0004 נוסף \u0003וישב עליו ושברו\u0004 — \u0003האחרון חייב. ואמר\u0004 על כך \u0003רב פפא:\u0004 כאן מדובר שאותו אדם נוסף היה \u0003כגון פפא בר אבא\u0004 שהיה שמן ביותר.","ואף קושיה זו דוחים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אילימא דבלאו איהו\u0004 \u0005[אם תאמר שבלעדיו]\u0006 \u0003לא איתבר\u0004 \u0005[היה\u0006 הספסל \u0005נשבר]\u0006 — \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שהוא החייב. \u0003אלא דבלאו איהו נמי איתבר\u0004 \u0005[שבלעדיו גם כן היה נשבר]\u0006 — \u0003מאי קעביד\u0004 \u0005[מה\u0006 כבר \u0005עשה]\u0006 אותו אדם? ואם כן לא ניתן להכניס דבר זה כדוגמא לכלל \"הכשרתי מקצת נזקו חבתי בתשלומי נזקו\" של המשנה.","ושואלים: מכל מקום, \u0003סוף סוף מתניתא\u0004 \u0005[ברייתא]\u0006 זו שהביא רב פפא \u0003היכא מתרצא\u0004 \u0005כיצד\u0006 היא \u0005מיושבת]?\u0006 שהרי קושי זה הוא גם לעצם פסק ההלכה שבברייתא!","ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה],\u0006 לא נאמרה הלכה זו אלא במקרה \u0003דבלאו איהו הוי מיתבר בתרי שעי, והשתא איתבר בחדא שעה\u0004 \u0005[שבלעדיו היה\u0006 הספסל \u0005נשבר בשתי שעות, ועכשיו נשבר בשעה אחת],\u0006 \u0003דאמרי ליה\u0004 \u0005[שיכולים לומר לו]\u0006 חמשת הראשונים לאחרון: \u0003אי לאו את\u0004 \u0005[אם לא אתה]\u0006 — \u0003הוי יתבינן טפי פורתא וקיימין\u0004 \u0005[היינו יושבים קצת יותר\u0006 משעה אחת \u0005וקמים]\u0006 ולא היה קורה דבר, וכיון שבאת אתה נשבר הספסל.","ושואלים: ומדוע יתחייב רק האחרון? \u0003ולימא להו\u0004 \u0005[ושיאמר להם]\u0006 אותו אחרון: \u0003אי לאו אתון\u0004 \u0005[אם לא אתם]\u0006 — \u0003בדידי\u0004 \u0005[בשלי],\u0006 על ידי בלבד \u0003לא הוי מיתבר\u0004 \u0005[היה נשבר\u0006 כלל\u0005]!\u0006","ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא במקרה \u0003דבהדי דסמיך בהו תבר\u0004 \u0005[שבשעה שנשען עליהם,\u0006 על אותם אנשים, \u0005נשבר]\u0006 מיד.","ושואלים: אם כן, \u0003פשיטא\u0004 \u0005[פשוט]\u0006 הוא שהוא חייב, שהרי כוחו הוא שגרם!","ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 \u0003כחו לאו\u0004 \u0005[לא]\u0006 \u0003כגופו דמי\u0004 \u0005[נחשב],\u0006 וכיון שלא גרם נזק לספסל בגופו, אלא בעקיפין, שנשען על האנשים — אינו חייב, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 ש\u0003כחו כגופו דמי\u0004 \u0005[נחשב],\u0006 ש\u0003כל היכא\u0004 \u0005[מקום]\u0006 ש\u0003גופו,\u0004 משקל עצמו, \u0003תבר\u0004 \u0005[שובר]\u0006 — \u0003כחו נמי תבר\u0004 \u0005[גם כן\u0006 נחשב \u0005שובר].\u0006","ושואלים על הברייתא שהובאה למעלה: \u0003ותו ליכא\u0004 \u0005[ואין עוד]\u0006 מקרים שאדם חייב אף שעשה רק מקצת נזק? \u0003והא איכא הא דתניא\u0004 \u0005[והרי יש\u0006 את \u0005זו ששנינו\u0006 בברייתא\u0005]:\u0006 מי ש\u0003הכוהו עשרה בני אדם בעשר מקלות, בין\u0004 שהיכוהו כולם \u0003בבת אחת, בין\u0004 שהיכוהו \u0003בזה אחר זה, ומת\u0004 — \u0003כולן פטורין,\u0004 משום שאי אפשר לחייב את אף אחד מהם בעונש מוות, שהרי לא הוא בלבד הרגו. \u0003ר' יהודה בן בתירא אומר:\u0004 אם היכוהו \u0003בזה אחר זה\u0004 — \u0003האחרון חייב, מפני ש\u0004הוא \u0003קירב את מיתתו\u0004 ביותר!","ודוחים: \u0003בקטלא לא קמיירי\u0004 \u0005[במיתה אינו עוסק]\u0006 בברייתא אלא בנזקים.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 תירוץ אחר: בדבר ששנוי \u0003בפלוגתא לא קמיירי\u0004 \u0005[במחלוקת אינו עוסק\u0006 בברייתא\u0005].\u0006 ושואלים: \u0003ולא?\u0004 וכי אין מפרשים על ידי דבר השנוי במחלוקת? \u0003והא אוקימנן\u0004 \u0005[והרי העמדנו]\u0006 ברייתא זו שהיא ש\u0003לא כ\u0004שיטת \u0003רבי\u0004 ואם כן כבר הסברנו את הברייתא על פי דבר שיש בו מחלוקת! ומשיבים: ש\u0003לא כרבי וכרבנן\u0004 \u0005[וכ\u0006שיטת רוב \u0005החכמים]\u0006 החלוקים עליו \u0003מוקמינן\u0004 \u0005[מעמידים\u0006 מפרשים \u0005אנו],\u0006 לפי שנוח לפרש שהברייתא לפי השיטה המוסכמת. אבל \u0003כ\u0004דעת \u0003ר' יהודה בן בתירא\u0004 שהוא יחיד \u0003ולא כרבנן\u0004 \u0005[כ\u0006שיטת \u0005חכמים]\u0006 \u0003לא מוקמינן\u0004 \u0005[אין אנו מעמידים]\u0006 את הברייתא, ונוח לנו לפרשה לא כדברי יחיד.","שנינו במשנה: \u0003חבתי בתשלומי נזקו.\u0004 ומדייקים: \u0003\"חבתי בנזקו\" לא קתני\u0004 \u0005[שנה]\u0006 \u0003אלא \"\u0004חבתי \u0003בתשלומי נזקו\".\u0004","ומעירים: \u0003תנינא להא\u0004 \u0005[שנינו את\u0006 הדיוק \u0005הזה]\u0006 בברייתא, \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים],\u0006 מה ששנינו במשנה \u0003תשלומי נזק\u0004 שמשמעו: השלמת הנזק, ולא כל הנזק כולו, \u0003מלמד שהבעלים\u0004 של שור שנגחוהו ומת הם \u0003מטפלין\u0004 (מתעסקים) \u0003בנבילה\u0004 למוכרה, ואת יתרת הנזק משלם להם המזיק, ואין משאירים אותה ביד המזיק שישלם עבור הנזק כולו.","ושואלים: \u0003מנא הני מילי\u0004 \u0005[מנין דברים אלה]\u0006 שהבעלים עצמם צריכים לטפל בנבילה? \u0003אמר ר' אמי,\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \"ו \u0003מכה נפש בהמה ישלמנה\"\u0004 (ויקרא כד, יח), \u0003אל תקרי\u0004 \u0005[תקרא]\u0006 \u0003\"ישלמנה\" אלא \"ישלימנה\".\u0004 כלומר, הוא ישלים את ההפסד שגרם, אבל אין המזיק משלם את כל הערך של הבהמה בחוב.","\u0003רב כהנא אמר מהכא\u0004 \u0005[מכאן]\u0006 הוא הלימוד לדין זה, שנאמר בפרשת שומר שכר: \u0003\"אם טרף יטרף יביאהו עד הטרפה לא ישלם\"\u0004 (שמות כב, יב), ודייק כאילו נאמר \u0003\"עד טרפה ישלם\"\u0004 כלומר, את הפרש המחיר שיש בין הבהמה החיה והטרפה ישלם המזיק, אבל \u0003טרפה עצמה לא ישלם.\u0004","\u0003חזקיה אמר:\u0004 המקור לדין זה הוא \u0003מהכא\u0004 \u0005[מכאן],\u0006 שנאמר בשור שנגח שור \u0003\"והמת יהיה לו\"\u0004 (שמות כא, לו) — \u0003לניזק.\u0004","\u0003וכן תנא דבי\u0004 \u0005[שנה\u0006 חכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003חזקיה\u0004 בברייתא: מה שנאמר בכתוב \u0003\"\u0004שלם ישלם שור תחת השור \u0003והמת יהיה לו\"\u0004 — \u0003לניזק.\u0004 וממשיכה הברייתא: \u0003אתה אומר לניזק או אינו אלא למזיק? אמרת: לא כך היה.\u0004","ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש הביטוי \u0003\"לא כך היה\"?\u0004","\u0003אמר אביי,\u0004 כך יש להבין: \u0003אי סלקא דעתך\u0004 \u0005[אם עולה על דעתך]\u0006 לפרש כי \u0003נבילה\u0004 של \u0003מזיק הויא\u0004 \u0005[היא],\u0006 אם כן \u0003ליכתוב רחמנא\u0004 \u0005[שתכתוב התורה]\u0006 \u0003\"\u0004שלם ישלם \u0003שור תחת השור\" ולישתוק\u0004 \u0005[ותשתוק]\u0006 ולא תוסיף דבר, \u0003\"והמת יהיה לו\" למה לי\u0004 לומר? \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שאין זה ממש שור תחת השור, אלא שהמת יהיה \u0003לניזק.\u0004","ומעירים: \u0003וצריכא\u0004 \u0005[ונצרך]\u0006 שייאמרו בתורה כמה כתובים המלמדים דין זה, \u0003דאי כתב רחמנא\u0004 \u0005[שאילו כתבה התורה]\u0006 רק \u0003\"\u0004ו\u0003מכה\u0004 נפש \u0003בהמה ישלמנה\"\u0004 הייתי אומר שלא חייבה תורה את המזיק לטפל בנבילה \u0003משום\u0004 שדבר זה הוא \u0003לא שכיחא\u0004 \u0005[מצוי]\u0006 שיכה אדם בהמה עד שיהרגנה, \u0003אבל טרפה דשכיחא\u0004 \u0005[ש\u0006היא \u0005מצויה]\u0006 — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 ישלם, ויצטרך המזיק (השומר) לטפל בנבילה, על כן \u0003צריכא\u0004 \u0005[נצרכה\u0006 לומר\u0005].\u0006","\u0003ו\u0004מצד שני, \u0003אי אשמועינן\u0004 \u0005[אם היה משמיע לנו]\u0006 רק בענין \u0003טרפה\u0004 הייתי אומר שאין מחייבים את השומר לטפל בנבילה \u0003משום דממילא\u0004 \u0005[ש\u0006נזקה נעשה \u0005מעצמו]\u0006 שהרי שומר הבהמה לא הוא שהזיק, אלא נטרף השור על ידי חיה, \u0003אבל מכה בהמה\u0004 ש\u0003בידים\u0004 הוא הזיקה — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 ייפטר המזיק מן הטיפול בנבילה, על כן הוצרכו שני הדברים.","ועוד, \u0003ואי אשמועינן הני תרתי\u0004 \u0005[ואם היה משמיע לנו את שני אלה]\u0006 בלבד, הייתי אומר: בשני אלה הדין כן, שהבעלים מטפלים בנבילה, \u0003הא\u0004 \u0005[זו]\u0006 במכה בהמה \u0003משום\u0004 ש\u0003לא שכיחא\u0004 \u0005[מצויה]\u0006 \u0003והא\u0004 \u0005[וזו]\u0006 \u0003משום דממילא\u0004 \u0005[ש\u0006היא באה \u0005מעצמה]\u0006 ולא על ידי השומר, \u0003אבל\u0004 ענין זה של \u0003\"והמת יהיה לו\"\u0004 האמור בשור שנגח שור, \u0003דשכיחא\u0004 \u0005[ש\u0006היא \u0005מצויה]\u0006 \u0003ו\u0004כאילו עשה אותו \u0003בידים,\u0004 שהרי השור שלו, המצוי ברשותו ובאחריותו, הוא שהזיק — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא,\u0004 על כן השמיע לנו שגם כאן הבעלים מטפלים בנבילה.","\u0003ואי אשמועינן\u0004 \u0005[ואילו היה משמיע לנו]\u0006 \"ו \u0003המת יהיה לו\"\u0004 בלבד, הייתי אומר שאין בעל השור הנוגח מטפל בנבילה \u0003משום דממונא קא מזיק\u0004 \u0005[שממונו,\u0006 השור שלו, \u0005הוא שהזיק],\u0006 \u0003אבל הכא\u0004 \u0005[כאן]\u0006 (\"מכה בהמה\") \u0003דבגופא\u0004 \u0005[שבגופו]\u0006 \u0003מזיק\u0004 — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 נחייב אותו בדבר, על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 שייאמרו שלושת הפסוקים.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב כהנא לרב: אלא\u0004 לפי מה שאמרנו \u0003טעמא דכתב רחמנא\u0004 \u0005[הטעם,\u0006 דווקא, משום \u0005שכתבה התורה]\u0006 \u0003\"והמת יהיה לו\"\u0004 למדנו כי הנבילה של הניזק, \u0003הא לאו הכי\u0004 \u0005[הרי בלא כך]\u0006 \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 שה\u0003נבילה\u0004 של ה\u0003מזיק הויא\u0004 \u0005[היא]\u0006 והוא צריך לשלם לניזק את מלוא הערך של הבהמה, ואולם דבר זה תמוה, שכן","\u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 \u0003אי אית ליה לדידיה\u0004 \u0005[אם יש לו ל\u0006מזיק \u0005עצמו]\u0006 \u0003כמה טריפות יהיב ליה\u0004 \u0005[נותן לו]\u0006 לניזק לתשלום, ש\u0003אמר מר\u0004 \u0005[החכם]\u0006 \u0003\"ישיב\"\u0004 — \u0003לרבות שוה כסף, ואפילו סובין.\u0004 וכיון שיכול המזיק לשלם לניזק בכל דבר ששווה כסף ואפילו בנבילה, אם כן נבילה \u0003דידיה מבעיא\u0004 \u0005[שלו נצרכה]\u0006 לומר שיכול לשלם? שוודאי, כשם שמשלם לו את נזקו בשאר דברים — יכול לפרוע לו מקצת חובו גם בנבילה זו!","ומשיבים: \u0003לא נצרכא\u0004 \u0005[הוצרכה]\u0006 הלכה זו לעצם דרך התשלום \u0003אלא לפחת נבילה,\u0004 ירידת ערך הנבילה משעה שמת השור עד שעה שנמכר, שפחת זה הוא על חשבון הניזק ואין המזיק משלם על כך.","ושואלים: \u0003לימא\u0004 \u0005[האם לומר]\u0006 כי הלכה זו לגבי \u0003פחת נבילה תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא? דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 מה שנאמר \u0003\"אם טרף יטרף יביאהו עד\"\u0004 (שמות כב, יב), פירושו:"],["\u0003יביא\u0004 השומר \u0003עדים\u0004 שהבהמה \u0003ש\u0004נמסרה לשמירתו \u0003נטרפה באונס,\u0004 ולא מתוך רשלנותו, \u0003ופטור. אבא שאול אומר: יביא\u0004 השומר \u0003עדודה\u0004 (את נבלת הבהמה שנטרפה) \u0003לבית דין,\u0004 ושם יעריכו כמה היא שווה.","\u0003מאי לאו בהא קמיפלגי\u0004 \u0005[האם לא ב\u0006שאלה \u0005זו חלוקים],\u0006 \u0003דמר\u0004 \u0005[שחכם זה,\u0006 אבא שאול\u0005]\u0006 \u0003סבר\u0004 \u0005[סבור]:\u0006 \u0003פחת נבילה\u0004 של ה\u0003ניזק הוי\u0004 \u0005[הוא]\u0006 שמשעה שמתה הריהי ברשותו, ולכן צריך השומר להביא את הנבילה לבית הדין כדי להעריך כמה הורידה המיתה עצמה בערך הבהמה, וישלם את ההפרש. \u0003ומר\u0004 \u0005[וחכם זה],\u0006 התנא של סתם ברייתא, \u0003סבר\u0004 \u0005[סבור]:\u0006 פחת נבילה של ה\u0003מזיק הוי\u0004 \u0005[היא]\u0006 ולכן אין צורך לשום את הנבילה כמה היתה שווה בזמן שנטרפה, בבית הדין?","ודוחים: \u0003לא,\u0004 אין הכרח לפרש כך ואפשר לומר \u0003דכולי עלמא\u0004 \u0005[שלדעת הכל]\u0006 פחת הנבילה הוא של ה\u0003ניזק, והכא\u0004 \u0005[וכאן]\u0006 \u0003בטורח נבילה קמיפלגי\u0004 \u0005[חלוקים\u0006 הם\u0005],\u0006 על מי יוטל הטורח להוציאה ממקומה. שלדעת אבא שאול טירחה זו מוטלת על המזיק, ולדעת התנא הראשון — על הניזק.","\u0003והתניא\u0004 \u0005[ואכן כן שנינו\u0006 בברייתא\u0005]\u0006 שנחלקו חכמים בדבר זה, \u0003אחרים אומרים: מניין שעל בעל הבור\u0004 המזיק \u0003להעלות שור מבורו\u0004 — \u0003תלמוד לומר: \"כסף ישיב לבעליו והמת\"\u0004 (שמות כא, לד), כלומר, גם את השור המת עליו להשיב לבעליו, שטורח הנבילה על המזיק, וכך דעת אבא שאול. ויש חכמים אחרים החולקים, וסבורים שהטורח בטיפול בנבילה מוטל על הניזק, והוא כדעת התנא החולק על אבא שאול.","בבירור ענין זה \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרבא: האי\u0004 \u0005[זה]\u0006 \u0003טורח\u0004 ה\u0003נבילה\u0004 המוטל לדעת אבא שאול ואחרים על המזיק, \u0003היכי דמי\u0004 \u0005[כיצד הוא בדיוק]?\u0006","\u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003דבבירא שויא זוזא ואגודא שויא ארבע\u0004 \u0005[שבבור שווה\u0006 הנבילה \u0005דינר\u0006 אחד \u0005ועל שפת הבור\u0006 אם יוציאו אותה תהיה \u0005שווה ארבעה],\u0006 אם כן \u0003כי טרח בדנפשיה טרח\u0004 \u0005[כאשר\u0006 הוא \u0005טורח,\u0006 הרי \u0005בשלו\u0006 הוא \u0005טורח],\u0006 שצריך לשלם פחות לניזק, ואם כן לא מן הדין אלא מפני הפסד ממונו יטרח המזיק להעלות את הנבילה!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא למקרה \u0003דבבירא שויא זוזא ואגודא נמי שויא זוזא\u0004 \u0005[שבבור\u0006 היא \u0005שווה דינר ועל שפת הבור\u0006 היא \u0005שווה גם כן דינר].\u0006","ושואלים: \u0003ומי איכא כהאי גוונא\u0004 \u0005[והאם יש\u0006 דבר \u0005כגון זה]?\u0006 ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 \u0003דהא אמרי אינשי\u0004 \u0005[שהרי אומרים אנשים]\u0006 בפתגם עממי: \u0003כשורא במתא בזוזא, כשורא בדברא בזוזא\u0004 \u0005[קורה בעיר בדינר, קורה בשדה בדינר],\u0006 כי יש דברים שמחירם שווה בכל מקום ואין טורח הבאתם מפחית מערכם.","\u0003אמר שמואל: אין שמין לא לגנב ולא לגזלן אלא לנזקין.\u0004 כלומר, אין מעריכים את דמי הנבילה או השברים, אלא במזיק, שמחזיר את הנבילה או השברים לניזק ומנכים את ערכם מתשלום הנזק, אבל לא לגנב או לגזלן — שהם משלמים בשלימות את כל מה שגנבו, ואם נשארו בידם שברים — הריהם שייכים להם. \u0003ואני אומר אף לשואל, ואבא\u0004 (רב) \u0003מודה לי.\u0004","ומביאים, \u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005],\u0006 מה היו בדיוק דברי שמואל, האם \u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003אף לשואל שמין\u0004 \u0005[מעריכים]\u0006 כמו לניזקין, \u0003ואבא מודה לי\u0004 שכן הוא. \u0003או דלמא\u0004 \u0003הכי קאמר\u0004 \u0005[שמא כך אמר]:\u0006 \u0003ואני אומר אף לשואל אין שמין,\u0004 ושואל דינו לענין זה כגנב וכגזלן, \u0003ואבא מודה לי\u0004 שכן הוא?","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון שאלה זו ממעשה: \u0003דההוא גברא\u0004 \u0003דשאיל נרגא מחבריה\u0004 \u0005[אדם אחד ששאל גרזן מחבירו],\u0006 \u0003תברה\u0004 \u0005[שבר אותה]\u0006 את הגרזן, \u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003רב, אמר ליה\u0004 \u0005[לו]\u0006 רב: \u0003זיל שלים ליה נרגא מעליא\u0004 \u0005[לך שלם לו גרזן מעולה],\u0006 כלומר, החזר לו גרזן שלם. \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003אין שמין\u0004 לשואל, שהרי לא אמר לו לנכות את דמי הגרזן השבור. וכך יש להבין את דברי שמואל.","ודוחים: \u0003אדרבה,\u0004 היפך הדבר מסתבר, כי לאותו מעשה היה המשך, \u0003מדאמרי ליה\u0004 \u0005[מ\u0006מה \u0005שאמרו לו]\u0006 באותה הזדמנות \u0003רב כהנא ורב אסי לרב: דינא הכי\u0004 \u0005[\u0006וכי \u0005כך הדין]?!\u0006 \u0003ושתיק\u0004 \u0005[ושתק\u0006 רב\u0005],\u0006 משמע שהודה לדבריהם, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי מעיקר הדין \u0003שמין\u0004 לשואל, ובאותו מקרה היתה סיבה מיוחדת שפסק רב שישלם השואל גרזן שלם.","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שחלקו אמוראים בדין זה, \u0003אמר עולא אמר ר' אלעזר: שמין לגנב ולגזלן\u0004 את ערך הדברים שאבדו או נשברו ברשותם, \u0003רב פפי אמר: אין שמין.\u0004 ומסכמים: \u0003והלכתא\u0004 \u0005[וההלכה\u0006 היא\u0005]:\u0006 \u0003אין שמין לא לגנב ולא לגזלן, אבל לשואל שמין כ\u0004דברי \u0003רב כהנא ורב אסי.\u0004","כיון שהזכרנו הלכה שאמר עולא בשם ר' אלעזר מביאים הלכות נוספות שאמר עולא משמו. אשה הרה שהפילה שליה הריהי טמאה טומאת לידה, ומונה ימי טומאה וימי טהרה, לפי שלא יתכן שתהא שליה בלא ולד, אלא שהוולד מת בשלב מסויים. \u0003ואמר עולא אמר ר' אלעזר: שליא שיצתה\u0004 (שיצאה) \u0003מקצתה\u0004 מן האשה \u0003ביום ראשון ומקצתה ביום שני\u0004 ולא נולד ולד, \u0003מונין לה\u0004 ימי טומאה \u0003מן\u0004 היום \u0003הראשון,\u0004 כאילו בו ילדה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא\u0004 לעולא: \u0003מה דעתך\u0004 שאתה פוסק כך, משום שמפני הספק אתה הולך \u0003לחומרא\u0004 (לחומרה)?","אולם דבר זה \u0003חומרא דאתי\u0004 \u0005[הבאה]\u0006 \u0003לידי קולא\u0004 (קולה) \u0003הוא,\u0004 כיצד? \u0003דקא מטהרת לה\u0004 \u0005[שמטהר אתה אותה]\u0006 \u0003מ\u0004יום \u0003ראשון\u0004 שכן לאחר ארבעה עשר יום שהיא מונה לטומאת לידה (לנקבה) הריהי נחשבת כטהורה. ושמא נולד הוולד רק ביום השני, ועדיין אינה טהורה!","\u0003אלא אמר רבא: לחוש\u0004 שמא היתה זו לידה, והיא טמאה מאותו יום — \u0003חוששת\u0004 כבר מן היום הראשון, אולם \u0003מימנא\u0004 \u0005[למנות]\u0006 ימי טומאה הריהי \u0003לא ממניא\u0004 \u0005[מונה]\u0006 \u0003אלא לשני\u0004 (מן היום השני), ועל ידי כך יוצאת ידי כל הספיקות.","ושואלים: \u0003מאי קא משמע לן\u0004 \u0005[מה השמיע לנו]\u0006 עולא בשם ר' אלעזר בכך — ש\u0003אין מקצת שליא בלא ולד,\u0004 שברור שאין שליה מצויה אלא כשהיה שם ולד? אולם דבר זה הלא כבר \u0003תנינא\u0004 \u0005[שנינו אותה]:\u0006 \u0003שליא\u0004 של בהמה \u0003שיצתה מקצתה\u0004 ולא יצאה כולה, ולאחר כך נשחטה הבהמה — \u0003אסורה\u0004 חתיכת השליה שנשארה בגופה \u0003באכילה,\u0004 משום שאנו מניחים שהיה שם ולד שיצא עם מקצת השליה, ולכן אף השליה שבפנים יש עימה חלק מן הוולד, שאינו נחשב עוד כחלק מגופה של הפרה שהותר בשחיטה. וטעם הדבר, כאמור, כי השליה שיצאה היא \u0003סימן ולד באשה\u0004 וכן \u0003סימן ולד בבהמה,\u0004 ואם כן לא הוסיף ר' אלעזר דבר על האמור במשנה!","ומסבירים: \u0003אי ממתניתא הוה אמינא\u0004 \u0005[אם מהמשנה\u0006 לבד \u0005הייתי אומר]\u0006 \u0003ד\u0004"],["יכול להיות ש\u0003יש מקצת שליא בלא ולד, ו\u0004מה שאסרוהו באכילה הוא רק משום \u0003גזירה\u0004 של חכמים שגזרו במקרה שיצא \u0003מקצתה אטו\u0004 \u0005[משום]\u0006 מקרה שיצאה השליה \u0003כולה,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 עולא בשם ר' אלעזר שאין זה משום גזירה, אלא ודאי אין שליה בלא ולד, ואנו חוששים שבכל חלק מן השליה יש מקצת מן הוולד.","\u0003ו\u0004עוד \u0003אמר עולא אמר ר' אלעזר: בכור\u0004 אדם \u0003שנטרף\u0004 (נהרג על ידי חיה או באופן אחר) \u0003בתוך שלשים יום\u0004 להיוולדו — \u0003אין פודין אותו,\u0004 כלומר, אין צורך לפדות אותו כדרך שפודים כל בכור, ואין אומרים שהתחייב האב בתשלום לכהן מיד עם לידת הבן.","\u0003וכן תני\u0004 \u0005[שנה]\u0006 \u0003רמי בר חמא\u0004 ברייתא זו, \u0003מתוך שנאמר: \"פדה תפדה\"\u0004 (במדבר יח, טו), \u0003יכול\u0004 נלמד מריבוי הלשון שיהא הדין כן \u0003אפילו\u0004 אם \u0003נטרף בתוך שלשים יום\u0004 — \u0003תלמוד לומר: \"אך\"\u0004 (במדבר יח, טוד), ובמלה זו \u0003חלק\u0004 ומיעט, לומר שלא בכל מקרה פודים בכור.","\u0003ו\u0004עוד \u0003אמר עולא אמר ר' אלעזר: בהמה גסה,\u0004 כמו פרה וסוס — \u0003נקנית\u0004 לקונה \u0003במשיכה,\u0004 שכאשר מושך את הבהמה אליו — נגמר בזה מעשה הקנין, ובכך היא נעשית שלו.","ושואלים: \u0003והא אנן תנן\u0004 \u0005[והרי אנו שנינו]\u0006 במשנה שבהמה גסה נקנית \u0003במסירה,\u0004 שכאשר מוסר את הרסן לקונה מיד היא נקנית לו! ומשיבים: ר' אלעזר \u0003הוא דאמר\u0004 \u0005[שאומר]\u0006 \u0003כי האי תנא\u0004 \u0005[כ\u0006דעת \u0005תנא זה],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003וחכמים אומרים: זו וזו,\u0004 הן בהמה גסה והן בהמה דקה, נקנית \u0003במשיכה, ר' שמעון אומר: זו וזו בהגבהה.\u0004 ור' אלעזר סבור כחכמים.","\u0003ו\u0004עוד \u0003אמר עולא אמר ר' אלעזר: האחין שחלקו\u0004 את ירושת אביהם, \u0003מה שעליהן\u0004 הבגדים שהם לובשים — \u0003שמין\u0004 (מעריכים) גם כן בתוך חשבון נכסי הירושה, ומחשבים גם את ערכם של אלה. \u0003ו\u0004אולם \u0003מה שעל בניהן ובנותיהן\u0004 — \u0003אין שמין,\u0004 שכיון שאין דרך הילדים לבוא לבית הדין, אין מבזים אותם לבוא לבית הדין כדי לשום את הבגדים שהם לובשים.","\u0003אמר רב פפא: פעמים אף מה שעליהן\u0004 על היורשים עצמם \u0003אין שמין,\u0004 כיצד? \u0003משכחת לה\u0004 \u0005[מוצא אתה\u0006 דוגמה כזו\u0005]\u0006 \u0003בגדול אחי\u0004 \u0005[האחים]\u0006 שמאז מות האב הוא הנושא והנותן בענייני המשפחה, \u0003דניחא להו דלשתמעון מיליה\u0004 \u0005[שנוח להם\u0006 לשאר היורשים \u0005שיישמעו דבריו]\u0006 ולשם כך הוא צריך ללבוש בגדים נאים, והם מוכנים לוותר משלהם, משום שבגדיו אלה מביאים תועלת גם להם.","\u0003ו\u0004עוד \u0003אמר עולא אמר ר' אלעזר: שומר שמסר\u0004 את הדבר שהופקד בידו \u0003לשומר\u0004 אחר — הרי זה \u0003פטור.\u0004 כלומר, כל אותם מקרים שאינו מתחייב בהם אם הוא עצמו שומר (כגון שומר שכר במיתה, או שומר חנם בגניבה) — אף אינו חייב כאשר מסר את הדבר שהופקד בידו לשמירתו של אחר. ומוסיפים: \u0003ולא מיבעיא\u0004 \u0005[נצרכה]\u0006 לומר אם היה זה \u0003שומר חנם שמסר\u0004 את החפץ לשמור \u0003לשומר שכר, דעלויי עלייה\u0004 \u0005[שעילה,\u0006 השביח\u0005]\u0006 את טיב \u0003שמירתו,\u0004 שהרי שומר שכר בוודאי שומר טוב יותר משומר חנם, \u0003אלא אפילו שומר שכר שמסר לשומר חנם\u0004 לשמור, \u0003דהשתא גרועי גרעיה\u0004 \u0005[שעכשיו גרע]\u0006 את טיב \u0003שמירתו,\u0004 מכל מקום \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003פטור, שהרי\u0004 בעיקרו של דבר \u0003מסר לבן דעת\u0004 ואין זו רשלנות בשמירה.","ואילו \u0003רבא אמר: שומר שמסר לשומר\u0004 — הרי זה \u0003חייב\u0004 בכל נזק שאירע. \u0003ולא מיבעיא\u0004 \u0005[נצרכה]\u0006 לומר \u0003שומר שכר שמסר לשומר חנם דגרועי גרעיה\u0004 \u0005[שגרע]\u0006 את טיב \u0003שמירתו, אלא אפילו שומר חנם שמסר לשומר שכר\u0004 גם כן \u0003חייב,\u0004","\u0003דאמר ליה\u0004 \u0005[ש\u0006יכול \u0005לומר לו]\u0006 בעל החפץ לשומר הראשון: \u0003את מהימנת\u0004 \u0005[אתה נאמן]\u0006 \u0003לי בשבועה,\u0004 כגון שאם תישבע שנגנב החפץ ממך אאמין לך, ו\u0003האי\u0004 \u0005[וזה],\u0006 השומר האחר, \u0003לא מהימן\u0004 \u0005[נאמן]\u0006 \u0003לי בשבועה\u0004 ואיני רוצה לסמוך עליו.","\u0003ו\u0004עוד \u0003אמר עולא אמר ר' אלעזר, הלכתא\u0004 \u0005[הלכה]\u0006 היא: \u0003גובין\u0004 חוב \u0003מן העבדים,\u0004 כלומר, לוקחים את העבדים של אדם כדי לגבות ממנו תשלום של חוב.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן לעולא:\u0004 האם \u0003אמר ר' אלעזר\u0004 הלכה זו כדי לומר שגובים מעבדים \u0003אפילו מיתמי\u0004 \u0005[מן היתומים]\u0006 אם מת החייב, כדרך שגובים מקרקעות שהוריש ליתומים? ענה לו עולא: \u0003לא,\u0004 רק \u0003מיניה\u0004 \u0005[ממנו\u0006 בלבד\u0005].\u0006 על כך שואל רב נחמן: אם ר' אלעזר אמר שמדובר שגובה \u0003מיניה\u0004 \u0005[ממנו],\u0006 הלא \u0003אפילו גלימא דעל כתפיה\u0004 \u0005[\u0006מן \u0005הגלימה שעל כתפיו]\u0006 הוא גובה, ובודאי שיכול לגבות מן העבדים שהם רכושו, ומה חידוש בדברי ר' אלעזר?","ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 \u0003שעשאו\u0004 את העבד \u0003אפותיקי,\u0004 כלומר, שמישכן אותו במיוחד לגביית חובו ומכרו, והשמיע לנו ר' אלעזר שיכול בעל החוב לגבות חובו מעבד זה שנמכר לאדם אחר, וזה \u0003כ\u0004דברי \u0003רבא,\u0004 ש\u0003אמר רבא: עשה עבדו\u0004 (הכנעני) \u0003אפותיקי ו\u0004אחר כך \u0003מכרו\u0004 את העבד — \u0003בעל חוב גובה הימנו.\u0004 עשה את \u0003שורו אפותיקי ומכרו\u0004 — \u0003אין בעל חוב גובה הימנו.\u0004","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 ההבדל\u0005]?\u0006 ומשיבים: \u0003הא אית ליה קלא\u0004 \u0005[זה,\u0006 העבד שנמכר, \u0005יש לו קול]\u0006 והקונה יודע שיש שיעבוד המוטל על העבד, \u0003והא לית ליה קלא\u0004 \u0005[וזה\u0006 בשור \u0005אין לו,\u0006 לשיעבוד, \u0005קול]\u0006 ואין הקונה יודע, ולכן תיקנו שלא יפסיד הקונה את ממונו בגלל שיעבוד זה."],["כהמשך לדיון בין עולא ורב נחמן, מסופר: \u0003לבתר דנפק\u0004 \u0005[לאחר שיצא]\u0006 רב נחמן מבית המדרש, \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003עולא\u0004 לחכמים: אין הדבר כפי שהשבתי לרב נחמן, אלא \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר ר' אלעזר:\u0004 גובים את החוב מעבדים \u0003אפילו מיתמי\u0004 \u0005[מיתומים],\u0006 משום שלדעת ר' אלעזר עבדים דינם לכל ענין כקרקעות. לאחר ששמע על כך \u0003אמר רב נחמן: אשתמטין\u0004 \u0005[השתמט ממני]\u0006 \u0003עולא,\u0004 כלומר, אם היה עולא אומר את הדבר בפני הייתי מוכיח לו שאינו צודק, ובדרך זו נשמט וברח ממני.","ומספרים: \u0003הוה עובדא\u0004 \u0005[היה מעשה]\u0006 מעין זה \u0003בנהרדעא\u0004 \u0003ואגבו\u0004 \u0005[והגבו]\u0006 \u0003דייני דנהרדעא\u0004 את החוב מן העבדים שירשו יתומים, שפסקו כעולא בשם ר' אלעזר, וכן \u0003הוה עובדא\u0004 \u0005[היה מעשה]\u0006 כזה \u0003בפומבדיתא ואגביה\u0004 \u0005[והגבה]\u0006 \u0003רב חנא בר ביזנא\u0004 את החוב מן העבדים. \u0003אמר להו\u0004 \u0005[להם\u0006 לדיינים\u0005]\u0006 \u0003רב נחמן: זילו אהדורו\u0004 \u0005[לכו והחזירו]\u0006 את מה שפסקתם שלא כדין, \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 תעשו כן — \u0003מגבינן לכו לאפדנייכו\u0004 \u0005[אגבה אני מבתיכם]\u0006 את החוב, לפי שעשיתם שלא כדין.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לרב נחמן: הא\u0004 \u0005[הרי]\u0006 \u0003עולא, הא\u0004 \u0005[הרי]\u0006 \u0003ר' אלעזר, הא\u0004 \u0005[הרי]\u0006 \u0003דייני נהרדעא והא\u0004 \u0005[והרי]\u0006 \u0003רב חנא בר ביזנא\u0004 שכולם סבורים שעבדים דינם כקרקעות, \u0003מר כמאן סבירא ליה\u0004 \u0005[אדוני כמי הוא סבור]?\u0006 כלומר, כיצד יכול אתה להחזיק בדעתך נגד כל אלה?","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אנא מתניתא ידענא\u0004 \u0005[אני ברייתא אני יודע]\u0006 ועליה אני מסתמך, \u0003דתני\u0004 \u0005[ששנה]\u0006 החכם \u0003אבימי\u0004 ברייתא זו: \u0003פרוזבול,\u0004 שטר הגורם לאישמיטת כספים בשביעית, \u0003חל על הקרקע,\u0004 אם יש ללווה קרקע, שהוא דבר שאפשר לסמוך עליו, \u0003ואינו חל על העבדים\u0004 לפי שאינם כקרקע. וכן \u0003מטלטלין נקנים עם\u0004 (אגב) \u0003הקרקע, ואינן נקנין עם העבדים.\u0004 משמע שהעבדים אינם כקרקע.","ומציעים, \u0003לימא כתנאי\u0004 \u0005[האם לומר\u0006 שנחלקו \u0005כ\u0006מחלוקת \u0005תנאים]\u0006 בשאלה זו.","ששנינו: \u0003מכר לו עבדים וקרקעות, החזיק\u0004 הקונה \u0003בעבדים\u0004 — \u0003לא קנה\u0004 על ידי כך את ה\u0003קרקעות,\u0004 שצריך לעשות בהם מעשה קנין לחוד, וכן אם החזיק \u0003בקרקעות\u0004 — \u0003לא קנה עבדים.\u0004 קנה \u0003קרקעות ומטלטלין,\u0004 כיון ש\u0003החזיק בקרקע\u0004 — \u0003קנה מטלטלין\u0004 עמהן, החזיק \u0003במטלטלין\u0004 — \u0003לא קנה קרקע.\u0004 קנה \u0003עבדים ומטלטלין, החזיק בעבדים\u0004 — \u0003לא קנה מטלטלין,\u0004 החזיק \u0003במטלטלין\u0004 — \u0003לא קנה עבדים.\u0004","\u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא אחרת\u0005]:\u0006 \u0003החזיק בעבדים\u0004 — \u0003קנה מטלטלין.\u0004","\u0003מאי לאו בהא קמפלגי\u0004 \u0005[האם לא ב\u0006שאלה \u0005זו נחלקו]\u0006 \u0003דמר סבר\u0004 \u0005[שחכם זה,\u0006 בברייתא השניה, \u0005סבור]:\u0006 \u0003עבדים כמקרקעי דמי\u0004 \u0005[כקרקעות נחשבים]\u0006 ומשום כך המחזיק בהם קנה מיטלטלים עימם, כפי שהקונה קרקע יכול לקנות אגב כך גם מיטלטלים. \u0003ומר סבר\u0004 \u0005[וחכם זה\u0006 בברייתא הראשונה, \u0005סבור]:\u0006 \u0003עבדים כמטלטלין דמי\u0004 \u0005[נחשבים],\u0006 ולכן אינו קונה מיטלטלים אחרים על ידם, שאין מיטלטלים נקנים על ידי מיטלטלים?","את ההצעה הזו דוחים, \u0003אמר רב איקא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אמי: דכולי עלמא\u0004 \u0005[לדעת הכל]:\u0006 \u0003עבדים כמקרקעי דמי\u0004 \u0005[כקרקעות\u0006 הם \u0005נחשבים],\u0006 \u0003והדתניא\u0004 \u0005[וזו ששנינו]\u0006 בברייתא השניה \u0003קנה\u0004 מיטלטלים אגב עבדים — \u0003שפיר\u0004 \u0005[יפה]\u0006 ומתאים לכך. \u0003והדתניא\u0004 \u0005[וזו ששנינו]\u0006 בברייתא הראשונה \u0003לא קנה,\u0004 טעמו של תנא זה הוא שסבור כי לקנין אגב \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 שיהא זה מין \u0003קרקע\u0004 שהוא \u0003דומיא\u0004 \u0005[דומה]\u0006 ל\u0003\"ערים מצורות ביהודה\"\u0004 שמהן למדים דין קנין מיטלטלים אגב קרקעות כאלה, ובדומה לערים מדובר בקרקעות ש\u0003לא ניידי\u0004 \u0005[ניידות].\u0006 ולכן אף שהעבד דינו כקרקעות ברוב המקרים, כיון שהוא נייד אין דינו לענין קנין לגמרי כקרקעות. והיכן למדנו דבר זה?","\u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003נכסים שאין להם אחריות,\u0004 כלומר, אלה שאי אפשר לעשות שיעבוד עליהם, כגון מיטלטלים — \u0003נקנין עם\u0004 (אגב) \u0003נכסים שיש להם אחריות,\u0004 כלומר, קרקעות, כאשר קונים את הקרקעות, בכל דרך של קנין מועיל: \u0003בכסף, בשטר, ובחזקה.\u0004 ועל כך שאלו: \u0003מנהני מילי\u0004 \u0005[מנין דברים אלה]\u0006 שמיטלטלים נקנים אגב קרקעות? ו\u0003אמר חזקיה,\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ויתן להם אביהם מתנות רבות לכסף ולזהב ולמגדנות עם ערי מצרות ביהודה\"\u0004 (דברי הימים ב כא, ג), ומאותו מקום המלמד על דין קנין אגב קרקע למד רב איקא גם שאין קנין אגב קרקע נעשה אלא בקרקע שאינה ניידת, ולא בעבדים. זו היתה גירסה אחת בהסברת ההבדל שבין הברייתות ביחס לקנין מיטלטלים אגב עבדים.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 בנוסח אחר: \u0003אמר רב איקא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי: דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003עבדי\u0004 \u0005[עבדים]\u0006 \u0003כמטלטלין דמי\u0004 \u0005[נחשבים],\u0006 \u0003והדתניא\u0004 \u0005[וזו ששנויה]\u0006 \u0003לא קנה\u0004 — \u0003שפיר\u0004 \u0005[יפה]\u0006 שנויה לפי זה, \u0003הא דתניא\u0004 \u0005[\u0006ו\u0005זו ששנויה]\u0006 \u0003קנה,\u0004 מדובר כאשר קנה את המיטלטלים \u0003בעודן עליו\u0004 על העבד, ולכן נקנים עמו.","ומקשים: \u0003וכי\u0004 \u0005[וכאשר]\u0006 \u0003עודן עליו מאי הוי\u0004 \u0005[מה יש\u0006 בכך\u0005]?\u0006 שאף שדבר הנופל בחצירו של אדם נקנה לו, מכל מקום הרי עבד \u0003חצר מהלכת היא, ו\u0004כלל הוא: \u0003חצר מהלכת\u0004 — \u0003לא קנה,\u0004 שדין קנין חצר אינו חל בחצר מהלכת! \u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 שמדובר כאן \u0003ב\u0004עבד \u0003עומד\u0004 ואין זו חצר מהלכת — \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר רבא:\u0004 \u0003כל שאילו\u0004 היה \u0003מהלך לא קנה\u0004 דבר מה — גם ב\u0003עומד ויושב לא קנה!\u0004","ומתרצים: \u0003והלכתא\u0004 \u0005[והלכה]\u0006 היא \u0003ב\u0004עבד \u0003כפות\u0004 שבעליו קונה דברים שעליו מדין חצר.","ושואלים עוד: בברייתא שהובאה קודם לכן שנינו שהמחזיק בקרקע לא קנה עבדים, \u0003והתניא\u0004 \u0005[והרי שנינו]\u0006 בברייתא אחרת: \u0003החזיק בקרקע קנה עבדים!\u0004","ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 בברייתא הראשונה מדובר \u0003ב\u0004עבדים שהיו \u0003עומדין בתוכה\u0004 בקרקע זו, ולכן נקנו עם הקרקע.","ושואלים: \u0003מכלל\u0004 הדברים תאמר \u0003דהאי\u0004 \u0005[שזה]\u0006 שהברייתא שאומרת \u0003לא קנה\u0004 עוסקת במקרה \u0003כשאין עומדין בתוכה?\u0004","\u0003הניחא להך לישנא\u0004 \u0005[זה נוח ללשון זו\u0006 השניה\u0005]\u0006 ש\u0003אמר רב איקא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אמי:\u0004 שלכל הדעות \u0003עבדי כמטלטלי דמי\u0004 \u0005[עבדים כמיטלטלים נחשבים]\u0006 \u0003היינו\u0004 \u0005[זה]\u0006 הטעם \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003עומדין בתוכה\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 נקנים הם אגב הקרקע, כשאר מיטלטלים, \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא\u0004 עומדים בתוכה — \u0003לא,\u0004 אינם נקנים.","\u0003אלא להך לישנא\u0004 \u0005[ללשון זו]\u0006 ש\u0003אמר\u0004 רב איקא שלכל הדעות \u0003עבדי כמקרקעי דמי\u0004 \u0005[\u0006\u0005עבדים כקרקעות\u0006 הם \u0005נחשבים],\u0006 אם כן \u0003למה לי\u0004 שיהיו העבדים \u0003עומדין בתוכה? הא\u0004 \u0005[הרי]\u0006 \u0003אמר שמואל:\u0004 \u0003מכר לו\u0004 לחבירו \u0003עשר שדות\u0004 ש\u0003בעשר מדינות\u0004 שונות, \u0003כיון שהחזיק באחת מהן\u0004 — \u0003קנה כולן,\u0004 ואין צורך שיחזיק בכל אחת ואחת בעצמה. ואף כאן — שייקנו העבדים (שדינם כקרקע) עם אותה קרקע שהחזיק בה, אף שאינם בתוכה!","ודוחים: \u0003וליטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005]\u0006 שכך אתה מקשה, גם \u0003להך לישנא\u0004 \u0005[לאותה לשון]\u0006 ש\u0003אמר\u0004 רב איקא \u0003עבדי כמטלטלין דמי\u0004 \u0005[\u0006ש\u0005עבדים כמיטלטלים\u0006 הם \u0005נחשבים],\u0006 אם כן \u0003למה לי\u0004 שיהא \u0003עומד\u0004 העבד \u0003בתוכה\u0004 בתוך הקרקע?"],["\u0003הא קיימא לן\u0004 \u0005[הרי מוחזק לנו]\u0006 להלכה ש\u0003לא בעינן\u0004 \u0005[צריכים]\u0006 להיות המיטלטלים \u0003צבורין\u0004 בתוך הקרקע כדי שייקנו אגב קנין הקרקע, והם נקנים אגב הקרקע בכל מקום שהם נמצאים!","\u0003אלא, מאי אית\u0004 \u0005[מה יש]\u0006 \u0003לך למימר\u0004 \u0005[לומר]\u0006 כי \u0003שאני מטלטלי דניידי ממטלטלי דלא ניידי\u0004 \u0005[שונים המיטלטלים הניידים\u0006 כגון עבדים, \u0005ממיטלטלים שאינם ניידים],\u0006","\u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 לשיטה שעבדים הריהם כקרקעות, צריך אתה לומר \u0003שאני מקרקעי דניידי ממקרקעי דלא ניידי\u0004 \u0005[שונות הקרקעות הניידות מקרקעות שאינן ניידות],\u0006 \u0003עבדא מקרקעי דניידי\u0004 \u0005[העבד קרקעות הניידים]\u0006 \u0003הוא,\u0004 לכן אינו נקנה עם הקרקע אלא אם כן הוא עומד בתוכה, \u0003התם\u0004 \u0005[שם]\u0006 הקונה עשר קרקעות בעשר מדינות, הלא \u0003סדנא דארעא חד\u0004 \u0005[הסדן,\u0006 המושב, \u0005של הארץ אחד]\u0006 \u0003הוא\u0004 ונמצא שכולן מחוברות כאחת.","שנינו במשנה שחייב המזיק רק על \u0003נכסים שאין בהן מעילה.\u0004","מלשון המשנה מדייקים: רק \u0003מעילה הוא דלית בהו\u0004 \u0005[שאין בהם],\u0006 \u0003הא מקדש קדשי\u0004 \u0005[הרי\u0006 בכל זאת \u0005קדושים הם],\u0006 כלומר, מדובר במשנתנו גם בקדשים, ואולם דווקא באלה שאין בהם חיוב של מעילה אם נהנה מהם.","ושואלים: \u0003מאן\u0004 \u0005[מיהו]\u0006 ה\u0003תנא\u0004 שלפי שיטתו אפשר להבין את הדברים? \u0003אמר ר' יוחנן:\u0004 מדובר במשנתנו \u0003בקדשים קלים\u0004 כגון שלמים, \u0003ואליבא\u0004 \u0005[ועל פי שיטתו]\u0006 של \u0003ר' יוסי הגלילי,\u0004 ש\u0003אמר\u0004 שקדשים קלים \u0003ממון בעלים הוא.\u0004 שרק משמקריבים אותם חלה עליהם קדושה חמורה, שכל הנהנה מהם מועל בקדשי שמים.","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 מה שנאמר במי שכופר בטענה שממון חבירו נמצא בידו \u0003\"ומעלה מעל בה'\u0004 וכיחש בעמיתו בפקדון\u0003\"\u0004 (ויקרא ה, כא), הרי זה בא \u0003לרבות\u0004 אם הפקיד חבירו אצלו \u0003קדשים קלים שהן ממונו\u0004 של המקריב, אלו \u0003דברי ר' יוסי הגלילי,\u0004 שאף זה בכלל \"וכיחש בעמיתו\".","ושואלים, \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 כהן \u0003המקדש\u0004 אשה \u0003בחלקו\u0004 המגיע לו מן הקרבנות, \u0003בין\u0004 שמקדשה בחלקו \u0003בקדשי קדשים, בין\u0004 שמקדשה \u0003בקדשים קלים\u0004 — \u0003אינה מקודשת,\u0004 שאין זה ממונו. \u0003לימא\u0004 \u0005[האם\u0006 \u0005לומר]\u0006 שמשנה זו אינה \u0003כ\u0004דעת \u0003ר' יוסי הגלילי?\u0004","ומתרצים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שהוא כדעת \u0003ר' יוסי הגלילי,\u0004 \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003אמר ר' יוסי הגלילי\u0004 שקדשים קלים ממונו הם — הרי זה דווקא \u0003מחיים, אבל לאחר שחיטה\u0004 למזבח — \u0003אפילו ר' יוסי הגלילי מודה דכי קא זכו\u0004 \u0005[שכאשר זוכים]\u0006 הבעלים והכהנים בחלק מן השלמים — \u0003משלחן גבוה קא זכו\u0004 \u0005[הם זוכים],\u0006 כלומר, שהקרבן נעשה כולו קודש לה', ולאחר מכן ניתן חלק לכהנים ולבעלים שיש להם זכות ליהנות ממנו, ואין זה עוד ממון הבעלים.","ושואלים: \u0003ומחיים\u0004 ובזמן שהקדשים חיים \u0003מי\u0004 \u0005[האם]\u0006 \u0003אמר\u0004 שממונו הם? \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003בכור מוכרין אותו תם חי,\u0004 כלומר, בעודו תמים בלי מום והוא חי (\u0003ו\u0004אולם \u0003לא\u0004 כאשר הוא כבר \u0003שחוט,\u0004 שאז נאסר הוא בהנאה), \u0003ו\u0004אילו בכור \u0003בעל מום\u0004 מוכרים בין שהוא \u0003חי ו\u0004בין שהוא \u0003שחוט. ומקדשין בו\u0004 כהנים \u0003את האשה.\u0004","\u0003ואמר רב נחמן אמר רבה בר אבוה: לא שנו\u0004 הלכה זו \u0003אלא\u0004 דווקא אצל \u0003בכור בזמן הזה,\u0004 ש\u0003כיון\u0004 ש\u0003לא חזי\u0004 \u0005[ראוי\u0006 הוא\u0005]\u0006 \u0003להקרבה,\u0004 שהרי אין בית המקדש קיים ואין מקריבים עוד את הבכורות \u0003אית להו\u0004 \u0005[יש להם]\u0006 \u0003לכהנים זכייה בגוייהו\u0004 \u0005[בהם]\u0006 בבכורות, שהרי מיד כשנופל מום בבכור הוא מותר לכהן באכילה, ולכן אף כשהוא תם יש כבר זכות מסויימת לכהן בו. \u0003אבל בזמן שבית המקדש קיים דחזי\u0004 \u0005[שראוי]\u0006 הבכור \u0003להקרבה\u0004 — \u0003לא.\u0004","\u0003ואיתיביה\u0004 \u0005[והקשה לו]\u0006 \u0003רבא לרב נחמן\u0004 ממה ששנינו: מה שנאמר בכתוב \u0003\"ומעלה מעל בה'\"\u0004 הרי זה בא \u0003לרבות קדשים קלים שהן ממונו,\u0004 אלו \u0003דברי ר' יוסי הגלילי,\u0004 ור' יוסי הגלילי העוסק בדיני מעילה עוסק בזמן שבית המקדש קיים, והרי אף הבכור בכלל קדשים קלים הוא. ואם כן, ממון הכהן הוא!","\u0003ומשני\u0004 \u0005[ומתרץ]\u0006 \u0003רבינא\u0004 קושיה זו, באומרו כי ר' יוסי הגלילי מדבר \u0003בבכור\u0004 ש\u0003בחוצה לארץ, ואליבא\u0004 \u0005[ועל פי\u0006 שיטתו\u0005]\u0006 של \u0003ר' שמעון,\u0004 ש\u0003אמר: אם באו\u0004 הבכורות \u0003תמימים\u0004 מחוץ לארץ — \u0003יקרבו\u0004 לקרבן. ומלשונו שאמר \u0003\"אם באו\"\u0004 אפשר לדייק כי רק בדיעבד — \u0003אין\u0004 \u0005[כן]\u0006 יקריבום, אבל \u0003לכתחלה\u0004 — \u0003לא,\u0004 וכיון שאינם שייכים להקרבה, ברשות כהן הם.","\u0003ואם איתא\u0004 \u0005[יש]\u0006 מקום לסברה זו \u0003דכי\u0004 \u0005[שכאשר]\u0006 \u0003אמר ר' יוסי הגלילי\u0004 שקדשים קלים \u0003ממונו הוא\u0004 — \u0003מחיים,\u0004"],["\u0003לישני\u0004 \u0005[שיתרץ]\u0006 רבינא תירוץ פשוט יותר: \u0003הא\u0004 \u0005[זו]\u0006 — שיטת \u0003ר' יוסי הגלילי\u0004 שקדשים קלים, ובכללם בכור, הם ממונו, \u0003הא\u0004 \u0005[\u0006ו\u0005זו]\u0006 שהעמיד רב נחמן דווקא בזמן הזה — כשיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 היא שאומרים שאינו כן!","ומשיבים: \u0003(אמר ליה\u0004 \u0005[לו],\u0006\u0003)\u0004 קושיה זו יש לדחות: \u0003מתנות כהונה קאמרת\u0004 \u0005[אומר אתה]?\u0006 הלא בכור ממתנות כהונה הוא, \u0003שאני\u0004 \u0005[שונות]\u0006 הם \u0003מתנות כהונה, דכי קא זכו\u0004 \u0005[שכאשר הם,\u0006 הכהנים, \u0005זוכים]\u0006 — \u0003משלחן גבוה קא זכו\u0004 \u0005[הם זוכים],\u0006 שקדושת הבכור היא קדושה מרחם ואינה תלויה בבעליו והוא קדוש לה' מיד, ולכן אין הבכור נחשב ממונו של הכהן מחיים, אף לדעת ר' יוסי הגלילי. מה שאין כן בקדשים קלים אחרים שמפריש אותם הבעלים מרצונו, וקדושתם חלה מכוחו של המפריש.","כיון שהוזכרו מקודם דברי ר' יוסי הגלילי בברייתא ביחס לקדשים קלים, דנים בברייתא זו \u0003גופא\u0004 \u0005[עצמה]:\u0006 נאמר בדין אשם גזילות \u0003\"ומעלה מעל בה'\u0004 וכחש בעמיתו בפקדון\u0003\"\u0004 (ויקרא ה, כא) — \u0003לרבות קדשים קלים, שהם ממונו,\u0004 אלו \u0003דברי ר' יוסי הגלילי.\u0004 שהכופר בכך שממון חבירו נמצא בידו בפקדון, ונשבע על כך ובסופו של דבר נמצא הפקדון בידו — צריך להוסיף חומש ולהביא קרבן אשם, ובכלל זה אף הכופר בפקדון בהמה שהוקדשה לקדשים קלים. \u0003בן עזאי אומר:\u0004 כתוב זה בא \u0003לרבות את השלמים. אבא יוסי בן דוסתאי אומר: לא אמר בן עזאי\u0004 מה שאמר \u0003אלא בבכור בלבד.\u0004","ברייתא זו אינה ברורה כלל, ומבררים אותה: \u0003אמר מר\u0004 \u0005[החכם],\u0006 \u0003בן עזאי אומר: לרבות את השלמים.\u0004 ויש לשאול: דברי בן עזאי אלה \u0003למעוטי מאי\u0004 \u0005[למעט\u0006 את \u0005מה]\u0006 מתוך דברי ר' יוסי הגלילי שקבע כלל זה בכל הקדשים הקלים הם באים?","\u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שבאה \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003בכור,\u0004 ולומר שבכור אין דינו כשלמים, ואינו נחשב כממון בעלים למרות שגם הוא קדשים קלים, אולם דבר זה יש לדחות: \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 קל וחומר הוא זה: \u0003ומה שלמים\u0004 החמורים שיש בהם קדושה יתירה, \u0003שטעונים סמיכה\u0004 בידיים על ראש הבהמה לפני הקרבתם, \u0003ו\u0004יש להביא עמם \u0003נסכים,\u0004 \u0003ו\u0004יש בהם \u0003תנופת\u0004 (הרמת) \u0003חזה ושוק\u0004 לפני ה' על ידי הכהן והבעלים, ובכל זאת \u0003אמרת\u0004 \u0005[אומר אתה]\u0006 בהם כי \u0003ממון בעלים הוא, בכור\u0004 שאין בו אף אחד מדברים אלה \u0003מבעיא\u0004 \u0005[נצרכה]\u0006 לומר שהוא נחשב כממון בעלים?","\u0003אלא אמר ר' יוחנן:\u0004 בן עזאי בא \u0003למעוטי\u0004 \u0005[למעט]\u0006 בדברי ר' יוסי הגלילי \u0003מעשר\u0004 בהמה, שאין הוא נחשב ממון הבעלים,","\u0003כדתניא\u0004 \u0005[כפי ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003בבכור נאמר\u0004 \"אך בכור... \u0003לא תפדה\u0004 \"(במדבר יח, יז), לומר שאי אפשר לפדותו שייעשה כחולין גמורים למכור את בשרו כשאר בשר בשוק, \u0003ו\u0004מכל מקום הוא \u0003נמכר תם חי, ובעל מום\u0004 בין \u0003חי ו\u0004בין \u0003שחוט.\u0004 ו\u0003במעשר נאמר \"לא יגאל\"\u0004 (ויקרא כז, לג) לומר שאין דרך להוציאו מקדושתו \u0003ואינו נמכר לא חי ולא שחוט, לא תם ולא בעל מום.\u0004 ומשום כך אין דינו כשאר קדשים קלים, שהרי אין לבעלים כל זכות ממונית בו בחייו, אלא שזוכים באכילתו משולחן גבוה כאשר מקריבים אותו.","\u0003רבינא מתני לה אסיפא\u0004 \u0005[היה שונה אותה,\u0006 את ההערה הזו, \u0005על סופה של\u0006 הברייתא\u0005]\u0006 \u0003אבא יוסי בן דוסתאי אומר: לא אמר בן עזאי אלא בבכור בלבד.\u0004 ושואלים: \u0003למעוטי מאי\u0004 \u0005[למעט\u0006 את \u0005מה]?\u0006","\u0003אילימא למעוטי\u0004 \u0005[אם תאמר\u0006 שבא \u0005למעט]\u0006 \u0003שלמים\u0004 — אין הדבר מסתבר, כי \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 כנגד זה יש לטעון בקל וחומר: \u0003ומה בכור ש\u0004הוא \u0003קדוש מרחם,\u0004 מעצם לידתו — בכל זאת \u0003ממונו הוא, שלמים\u0004 שמקדיש אותם מעצמו \u0003מבעיא\u0004 \u0005[הוצרכה\u0006 לומר\u0005]\u0006 שהוא ממונו?","ועל כך \u0003אמר ר' יוחנן:\u0004 אבא יוסי בן דוסתאי בא \u0003למעוטי\u0004 \u0005[למעט]\u0006 מדברי ר' יוסי הגלילי \u0003מעשר\u0004 בהמה, שאין זה נחשב ממון בעלים.","\u0003כדתניא\u0004 \u0005[כפי ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003בבכור נאמר \"לא תפדה\"\u0004 — \u0003ו\u0004הוא \u0003נמכר תם חי, ובעל מום חי ושחוט, במעשר\u0004 בהמה \u0003נאמר \"לא יגאל\" ו\u0004הוא \u0003אינו נמכר לא חי ולא שחוט, לא תם ולא בעל מום.\u0004","ומקשים: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003בבכור בלבד קאמר\u0004 \u0005[אמר]\u0006 אבא יוסי בן דוסתאי שרק בו יש דין זה, ולפי מה שאמרנו הוא הדין לשלמים! ואומרים: אכן, לפירוש זו \u0003קשיא\u0004 \u0005[קשה]\u0006 הלשון.","ושוב חוזרים לפירוש המשנה שלנו, ובאופן אחר. \u0003רבא אמר: מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"נכסים שאין בהן מעילה\"\u0004 שנאמרו במשנתנו שאין בהם דין נזיקין — כוונתו \u0003נכסים שאין בהן דין מעילה,\u0004 כלומר, שאין בהם קדושה כלל, \u0003ומאי נינהו\u0004 \u0005[ומה הם]\u0006 נכסים אלה — נכסים של \u0003הדיוט,\u0004 כלומר, נכסי חולין שאינם מוקדשים.","ושואלים: \u0003וליתני\u0004 \u0005[ושישנה]\u0006 במפורש: נכסים של \u0003הדיוט,\u0004 של חולין! ואומרים: אכן, \u0003קשיא\u0004 \u0005[קשה]\u0006 מדוע בחר בלשון זו.","\u0003אמר ר' אבא: שלמים שהזיקו\u0004 — \u0003גובה\u0004 הניזק את התשלום \u0003מבשרן ואינו גובה מאימוריהן\u0004 (החלב ושאר החלקים המוקרבים על המזבח).","ותוהים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שכן הוא, הלא \u0003אימורין לגבוה\u0004 (לה', כקרבן) \u0003סלקי\u0004 \u0005[עולים]\u0006 וכיצד יכול לגבות מהם?","ומשיבים: \u0003לא צריכא\u0004 \u0005[הוצרכה]\u0006 להיאמר אלא \u0003ל\u0004ענין שיהיה \u0003גובה\u0004 התשלומים \u0003מבשרן כנגד אימורים,\u0004 כלומר, אם היה זה שור תם, שגובה תשלום חצי הנזק מגופו של המזיק — אינו יכול לגבות מבשר השור המזיק גם עבור חלק האימורים שבו, כיון שחלק זה שייך לגבוה, ואינו שייך לבעלים.","ושואלים: \u0003אליבא דמאן\u0004 \u0005[לפי שיטת מי]\u0006 נאמרה הלכה זו?","\u0003אי אליבא דרבנן\u0004 \u0005[אם כשיטת חכמים]\u0006 שחלקו על ר' נתן בדין שור שדחף שור אחר לבור, והם סבורים שבעל השור המזיק, אם היה שורו תם — משלם רבע הנזק, ואם היה מועד — משלם מחצית הנזק, ובעל הבור פטור לגמרי. ואין אנו אומרים שישלים את התשלום החסר של בעל השור. אם כן, גם כאן \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שאינו גובה מן הבשר עבור מחצית דמי האימורים, שכן \u0003הא אמרי כי ליכא לאשתלומי מהאי לא משתלמא מהאי\u0004 \u0005[הרי אומרים הם\u0006 שגם \u0005כאשר אי אפשר לקבל את התשלום\u0006 המלא \u0005מזה, אין מקבלים\u0006 את יתרת \u0005התשלום מזה]\u0006 אף על פי שיש לו חלק באחריות.","\u0003ואי אליבא\u0004 \u0005[ואם כשיטת]\u0006 \u0003ר' נתן\u0004 — \u0003הא אמר\u0004 \u0005[הרי\u0006 הוא \u0005אומר\u0006 סבור\u0005]:\u0006 \u0003כי ליכא לאשתלומי מהאי משתלם מהאי\u0004 \u0005[כאשר אין\u0006 אפשרות \u0005לקבל\u0006 כל \u0005התשלום מזה, מקבל\u0006 את יתרת \u0005התשלום מזה],\u0006 שבעל הבור משלם את יתרת הנזק לבעל השור הניזק. ואם כן לדעת ר' נתן יצטרך לקבל גם מן הבשר עבור חלק האימורים!","ומשיבים: אין קושיה זו חמורה ואפשר לענות עליה בשני אופנים: \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 שדברי ר' אבא כדעת \u0003ר' נתן\u0004 הם, \u0003איבעית אימא\u0004 \u0005[\u0006ו\u0005אם תרצה אמור]\u0006 שדבריו כדעת \u0003רבנן\u0004 \u0005[חכמים]\u0006 הם; ומפרטים:","\u0003איבעית אימא רבנן\u0004 \u0005[אם תרצה אמור\u0006 כדעת \u0005חכמים],\u0006 והחידוש בדברי ר' אבא הוא שיכול הייתי לומר: \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 שאין מקבל תשלום מן האחר — נאמרו דווקא \u0003בתרי גופי\u0004 \u0005[בשני גופים]\u0006 שיש שני מקורות לתשלומים, כגון בעל השור המזיק ובעל הבור, \u0003אבל בחד גופא\u0004 \u0005[בגוף אחד]\u0006 כגון בבהמת שלמים שיש בה בשר ואימורים \u0003מצי אמר ליה\u0004 \u0005[יכול לומר לו\u0006 הניזק למזיק\u0005]:\u0006 \u0003מכל היכא דבעינן משתלמנא\u0004 \u0005[מכל מקום שאני רוצה אני מקבל תשלום]\u0006 ואין אתה יכול לומר לי שאני צריך לקחת רק מחלק מסויים. ולכך השמיענו ר' אבא שאינו כן, ואינו גובה מן הבשר כנגד האימורים.","\u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 גם \u0003כ\u0004דעת \u0003ר' נתן: התם\u0004 \u0005[שם]\u0006 \u0003הוא דאמר ליה\u0004 \u0005[ש\u0006יכול \u0005לומר לו]\u0006 \u0003בעל\u0004 ה\u0003שור\u0004 הניזק \u0003לבעל הבור: אנא תוראי בבירך אשכחתיה\u0004 \u0005[אני\u0006 את \u0005שורי בבורך מצאתי]\u0006 הרוג, ויכול היה למות שם גם בלא דחיפת השור, ולכן \u0003מאי דלית\u0004 \u0005[מה שאין]\u0006 \u0003לי\u0004 אפשרות \u0003לאשתלומי מהיאך\u0004 \u0005[לקבל תשלום מזה],\u0006 מבעל השור המזיק, \u0003משתלימנא מינך\u0004 \u0005[מקבל אני תשלום ממך].\u0006"],["\u0003אבל הכא מי מצי אמר\u0004 \u0005[כאן האם יכול\u0006 הניזק \u0005לומר]\u0006 לבעל שור השלמים שהזיק: \u0003בשר אזיק\u0004 \u0005[הזיק],\u0006 \u0003אימורין לא אזיק\u0004 \u0005[הזיקו]?!\u0006 שהרי הבהמה הזיקה בכל כח גופה, ולכן הפסיד הניזק את חלק האימורים שהזיק!","\u0003אמר רבא:\u0004 בהמה שהוקדשה לקרבן \u0003תודה, שהזיקה\u0004 — \u0003גובה\u0004 הניזק אם היה זה תם \u0003מבשרה,\u0004 שהוא בשר שלמים, \u0003ואינו גובה מלחמה\u0004 מארבעים חלות שמביאים עם התודה.","ותוהים: \u0003לחם פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שכן הוא, וכי למה יגבה ממנו, שהרי וודאי הוא אינו חלק מן הבהמה שהזיקה!","ומשיבים: \u0003סיפא אצטריך ליה\u0004 \u0005[סוף\u0006 ההלכה הוא ש\u0005הוצרך לו\u0006 לומר\u0005],\u0006 שכך אמר רבא בהמשך הדברים: כיצד מגיע תשלום זה בפועל? כאשר מקריבים את התודה אז \u0003הניזק אוכל בשר\u0004 (מקצתו או כולו, לפי שיעור הנזק) \u0003ו\u0004ה\u0003מתכפר\u0004 בקרבן התודה, שהוא בעל הבהמה \u0003מביא\u0004 את \u0003לחם\u0004 התודה יחד עם הקרבן.","ומקשים: \u0003הא נמי פשיטא\u0004 \u0005[זה גם כן פשוט]\u0006 ומדוע לא יביא? ומסבירים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 \u0003כיון\u0004 ש\u0003לחם הכשירא\u0004 \u0005[הכשירו\u0006 תיקונו\u0005]\u0006 של ה\u0003זבח הוא, לימא ליה\u0004 \u0005[שיאמר לו]\u0006 המזיק לניזק: \u0003את אכלת\u0004 \u0005[אתה אוכל]\u0006 את ה\u0003בשר, ואנא אייתי\u0004 \u0005ואני אביא]\u0006 את ה\u0003לחם?!,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 ש\u0003לחם חיובא\u0004 \u0005[חובת]\u0006 ה\u0003בעלים הוא\u0004 והוא חלק מן הקרבן, ואין זה קשור למי שאוכל את הבשר בפועל.","שנינו במשנה שמשלמים על נזקים רק כאשר היו אלה \u0003נכסים שהן של בני ברית.\u0004","ושואלים: \u0003למעוטי מאי\u0004 \u0005[למעט\u0006 את \u0005מה]\u0006 בא ביטוי זה? \u0003אי למעוטי\u0004 \u0005[אם למעט]\u0006 נכסים של \u0003גוי\u0004 — \u0003הא קתני לה לקמן\u0004 \u0005[הרי שנה אותה לפנינו]\u0006 במפורש: \u0003שור של ישראל שנגח שור של גוי\u0004 — \u0003פטור!\u0004 ומשיבים: \u0003תנא והדר\u0004 ו\u0003מפרש\u0004 \u0005[שנה\u0006 דין כללי \u0005וחוזר ומפרש\u0006 בפרטות\u0005].\u0006","וכן שנינו במשנתנו שמשלמים הבעלים נזקי ממונם רק אם היו אלה \u0003נכסים המיוחדין.\u0004 ושואלים: \u0003למעוטי מאי\u0004 \u0005[למעט\u0006 את \u0005מה]\u0006 בא ביטוי זה? \u0003אמר רב יהודה: למעוטי\u0004 \u0005[למעט]\u0006 מקרה כאשר הזיק שור, ואין ידוע איזה, \u0003זה אומר \"שורך הזיק\", וזה אומר \"שורך הזיק\",\u0004 שאין כאן נכסים מיוחדים — לפי שאין המזיק מוגדר ומיוחד.","ושואלים: \u0003הא תני לקמן\u0004 \u0005[הרי שנוי\u0006 דבר זה \u0005לפנינו],\u0006 ששנינו: \u0003היו שנים\u0004 (שני שוורים) \u0003רודפין אחר\u0004 שור \u0003אחד,\u0004 וניזוק השור הנרדף ולא ברור על ידי מי, \u0003זה אומר: שורך הזיק, וזה אומר: שורך הזיק\u0004 — \u0003שניהם פטורין,\u0004 לפי שאי אפשר להוכיח במי האשמה! ומשיבים: \u0003תני והדר\u0004 \u0005[שונה וחוזר]\u0006 ו\u0003מפרש\u0004 את הדברים בפרטות.","\u0003במתניתא תנא\u0004 \u0005[בברייתא שנה]\u0006 הסבר אחר ל\"נכסים המיוחדין\" — \u0003פרט לנכסי הפקר.\u0004 ומבררים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אילימא דנגח תורא דידן לתורא\u0004 \u0005[אם תאמר שנגח שור שלנו,\u0006 של אדם מישראל, \u0005לשור]\u0006 של \u0003הפקר\u0004 — \u0003מאן תבע ליה\u0004 \u0005[מי תובע אותו]\u0006 את נזקו של שור ההפקר? \u0003אלא,\u0004 ש\u0003נגח תורא\u0004 \u0005[שור]\u0006 של \u0003הפקר לתורא דידן\u0004 \u0005[שור שלנו]\u0006 —","\u0003ליזיל וליתיה\u0004 \u0005[שילך\u0006 הניזק \u0005ויקח]\u0006 את השור כולו, שהרי של הפקר הוא! ומשיבים: מדובר \u0003ב\u0004מקרה \u0003שקדם וזכה בו אחר\u0004 באותו שור, ואז אינו יכול הניזק לקחת את השור, וגם אינו יכול לתבוע את נזקו מן המחזיק עתה בשור, שהרי כשנגח לא היה שייך לאיש.","\u0003רבינא אמר\u0004 הסבר אחר ל\"נכסים המיוחדין\": \u0003למעוטי\u0004 \u0005[למעט]\u0006 שור ש\u0003נגח ואחר כך הקדיש\u0004 אותו בעליו, או \u0003נגח ואחר כך הפקיר\u0004 אותו — שבמקרה זה פטור, שאין השור מיוחד לבעליו מתחילה ועד הסוף.","ומעירים: \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך],\u0006 \u0003יתר על כן אמר ר' יהודה: אפילו נגח ואחר כך הקדיש, נגח ואחר כך הפקיר\u0004 — \u0003פטור, ש\u0004כן \u0003נאמר\u0004 \u0003\"והועד בבעליו... והמית איש\u0004 או אשה\u0003\"\u0004 (שמות כא, כט), לומר: \u0003עד שתהא מיתה והעמדה בדין\u0004 (שאז מעידים בבעל השור המזיק — \"והועד בבעליו\") \u0003שוין כאחד,\u0004 שתהא עליו בעלות כל אותו זמן, ואם אין לו בעלים — אינו חייב עליו.","ושואלים: ורק העמדה בדין אנו צריכים שתהא בבעלים, \u0003ו\u0004אילו \u0003גמר דין לא בעינן\u0004 \u0005[אין אנו צריכים]\u0006 שיהיה בבעלים? \u0003הא\u0004 \u0005[הרי]\u0006 \u0003\"השור יסקל\u0004 וגם בעליו יומת \u0003\"\u0004שנאמר בהמשך הפסוק — \u0003בגמר דין הוא דכתיב\u0004 \u0005[שנאמר]!\u0006","\u0003אלא אימא\u0004 \u0005[אמור]\u0006 ותקן כך: \u0003עד שתהא מיתה\u0004 שגרם השור, \u0003והעמדה\u0004 של השור \u0003בדין, וגמר\u0004 ה\u0003דין\u0004 שלו, \u0003שוין כאחד\u0004 שיש לו בעלים, ואם לאו — אי אפשר לדונו או לגבות ממנו.","שנינו במשנה שהמזיק חייב על נזקי שורו \u0003חוץ מ\u0004נזקים שהיו ב\u0003רשות המיוחדת למזיק.\u0004 ומסבירים: \u0003דאמר ליה\u0004 \u0005[שיכול לומר לו]\u0006 המזיק לניזק: \u0003תורך\u0004 \u0005[שורך]\u0006 שניזוק על ידי שורי \u0003ברשותי מאי בעי\u0004 \u0005[מה\u0006 הוא \u0005רוצה],\u0006 מדוע בכלל נמצא הוא ברשותי? ולכן איני אחראי על נזקיו.","עוד שנינו במשנה: \u0003ורשות הניזק והמזיק.\u0004 ובענין זה מביאים מחלוקת אמוראים.","\u0003אמר רב חסדא אמר אבימי: חצר השותפין\u0004 — \u0003חייב בה\u0004 המזיק \u0003על\u0004 נזקי \u0003השן ועל\u0004 נזקי \u0003הרגל\u0004 שגרמה בהמתו לרכוש שותפו, \u0003והכי קאמר\u0004 \u0005[וכך\u0006 הוא \u0005אומר],\u0006 כך יש להבין את המשנה: \u0003חוץ מרשות המיוחדת למזיק\u0004 ש\u0003פטור\u0004 המזיק, \u0003ו\u0004אולם ב\u0003רשות הניזק והמזיק\u0004 — \u0003כשהזיק חב המזיק.\u0004","\u0003ור' אלעזר אמר:\u0004 בחצר השותפים \u0003פטור על השן ועל הרגל, והכי קאמר\u0004 \u0005[וכך\u0006 הוא \u0005אומר],\u0006 כך יש להבין את המשנה: כשהזיק חייב המזיק לשלם, \u0003חוץ מרשות המיוחדת למזיק, ורשות הניזק והמזיק נמי\u0004 \u0005[גם כן]\u0006 \u0003פטור.\u0004 והמשך הדברים \u0003\"וכשהזיק חב המזיק\"\u0004 — \u0003לאתויי\u0004 \u0005[להביא,\u0006 לרבות\u0005]\u0006 \u0003קרן.\u0004","ושואלים: \u0003הניחא\u0004 \u0005[זה נוח]\u0006 \u0003ל\u0004שיטת \u0003שמואל\u0004 המסביר ש\"שור\" האמור בתחילת המשנה כוונתו לנזקי רגל או שן, ולשיטתו יש טעם בהוספה זו, ללמד על קרן. \u0003אלא ל\u0004שיטת \u0003רב\u0004 ש\u0003אמר: תנא\u0004 \u0005[שנה]\u0006 \u0003שור וכל מילי\u0004 \u0005[הדברים]\u0006 שב\u0003שור\u0004 ובכללם גם נזקי קרן, אם כן \u0003\"חב המזיק\" לאתויי מאי\u0004 \u0005[להביא\u0006 את \u0005מה]?\u0006 שהרי קרן כבר נשנתה!","ומשיבים: \u0003לאתויי הא דתנו רבנן\u0004 \u0005[להביא\u0006 דבר \u0005זה ששנו חכמים]\u0006 בברייתא, בפירוש המשנה: \u0003כשהזיק חב המזיק\u0004 — \u0003להביא\u0004 (לרבות) \u0003שומר חנם והשואל, נושא שכר והשוכר, שהזיקה בהמה ברשותן,\u0004 ש\u0003תם\u0004 — \u0003משלם חצי נזק, ומועד\u0004 — \u0003משלם נזק שלם. נפרצה\u0004 הגדר במקום שהיתה בו הבהמה \u0003בלילה, או שפרצוה לסטין ויצתה\u0004 הבהמה \u0003והזיקה\u0004 — \u0003פטור.\u0004","ומבארים את הברייתא: \u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003כשהזיק חב המזיק\u0004 — \u0003להביא שומר חנם והשואל נושא שכר והשוכר.\u0004 ויש לברר: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006","\u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003דאזקיה תורא\u0004 \u0005[שהזיק השור]\u0006 של ה\u0003משאיל לתורא\u0004 \u0005[את השור]\u0006 של ה\u0003שואל\u0004 ועל כך אומרת הברייתא שצריך המשאיל לשלם לשואל — \u0003לימא ליה\u0004 \u0005[שיאמר לו]\u0006 המשאיל: \u0003אילו אזיק בעלמא, בעית לשלומי את\u0004 \u0005[אם היה\u0006 שורי \u0005מזיק בכלל,\u0006 שורו של אדם אחר, \u0005הרי אתה\u0006 \u0005היית צריך לשלם]\u0006 עבור הנזקים, שהרי עליך מוטלת חובת שמירתו, \u0003השתא דאזקיה לתורא דידך, בעינא לשלומי\u0004 \u0005[עכשיו שהזיק את השור שלך, צריך אני לשלם\u0006 עבורו\u0005]?!\u0006","\u0003אלא\u0004 תאמר שמדובר במקרה הפוך: \u0003דאזקיה תורא\u0004 \u0005[שהזיק השור]\u0006 של ה\u0003שואל לתורא\u0004 \u0005[את השור]\u0006 של ה\u0003משאיל,\u0004 ואומרת הברייתא שעל השואל לשלם למשאיל חצי נזק (בשור תם) — \u0003לימא ליה\u0004 \u0005[שיאמר לו]\u0006 המשאיל: \u0003אילו\u0004 שורי שבידך \u0003איתזק מעלמא, בעית לשלומי כוליה תורא\u0004 \u0005[היה ניזוק מבחוץ\u0006 על ידי שור אחר, \u0005היית צריך לשלם\u0006 לי את \u0005כל\u0006 דמי \u0005השור],\u0006 שהרי שואל חייב לשלם עבור כל נזק שאירע לבהמה ששאל, \u0003השתא דאזקיה תורא דידך, פלגא ניזקא\u0004 \u0005[עכשיו שהזיק אותו השור שלך,\u0006 רק \u0005חצי נזק]\u0006 \u0003הוא דמשלמת\u0004 \u0005[שאתה משלם]\u0006 \u0003לי\u0004 בגלל ששורך שהזיקו היה שור תם?!","ומסבירים: \u0003לעולם\u0004 תפרש שמדובר כאן \u0003דאזקיה תורא\u0004 \u0005[שהזיק אותו השור]\u0006 של ה\u0003משאיל לתורא\u0004 \u0005[את השור]\u0006 של ה\u0003שואל,\u0004 \u0003ו\u0004אף שלכאורה יכול לטעון המשאיל: הרי קיבלת על עצמך לשמור על שור זה — \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — באופן \u0003שקבל עליו\u0004 השואל רק \u0003שמירת גופו\u0004 של השור שלא יינזק,"]]};
